FLAGSHIP_ROOM_KEY = "repo:mainnode/forkmesh:room:general"
PUBLIC_WORLD_GENERAL_ROOM = "world-general"
PUBLIC_WORLD_GENERAL_ROOM_KEY = (
    "repo:mainnode/forkmesh:room:" + PUBLIC_WORLD_GENERAL_ROOM
)
# A host counts as "online" if it has been active within this window. The window
# self-heals presence rows orphaned by a host that vanished without a clean close;
# active hosts refresh their row at most once per HOST_PRESENCE_REFRESH_MS.
HOST_PRESENCE_STALE_MS = 10 * 60 * 1000
HOST_PRESENCE_REFRESH_MS = 60 * 1000
# Public Git availability is now proven by signed, server-observed direct HTTPS
# endpoint checks. This window intentionally matches the old presence headline
# so the status page's semantics remain stable while its evidence gets stronger.
HTTPS_MIRROR_STATUS_FRESH_MS = 10 * 60 * 1000
# Registered desktop/headless node accounts that have not been seen for this
# long are treated as abandoned: their physical node row and public repo catalog
# namespace are pruned so old one-off registrations stop participating in
# browse/clone routing. A node that returns after this window must register
# again.
REGISTERED_NODE_ACTIVE_MS = 60 * 60 * 1000
STALE_NODE_PURGE_INTERVAL_MS = 60 * 1000
STALE_NODE_PURGE_BATCH = 100
# Reinstalling or rotating a desktop node's key mints a NEW account_devices row
# (device_bi is keyed on the pubkey), so one account slowly accretes a row per
# historical key — the DB side of the "one person, many identities" sprawl. A
# device untouched for this long is pruned, but only when the account still has a
# newer key to sign with, so a node's live/most-recent key (the one the drain
# gate now reuses; see _owner_signing_pubkeys) is never removed.
STALE_DEVICE_RETAIN_MS = 60 * 24 * 60 * 60 * 1000  # 60 days
STALE_DEVICE_PURGE_BATCH = 200
# How long a downed repo's clone traffic stays pinned to one chosen mirror (see
# clone_sticky). Long enough that a clone's info/refs and upload-pack POST land
# on the same node; short enough that the load still rotates across mirrors.
CLONE_STICKY_MS = 5 * 60 * 1000


# Public node name = username = a single DNS-like label: lowercase letters,
# digits, and hyphens; must start with a letter and end with a letter or digit;
# no underscores, no spaces, <= 63 chars. This is the user's public handle and
# their repo namespace, so it is validated identically in the web and desktop
# clients.
NODE_NAME_RE = re.compile(r"^[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$")
MENTION_RE = re.compile(r"(?<![A-Za-z0-9._%+-])@([a-z](?:[a-z0-9-]{0,61}[a-z0-9])?)\b")
DOMAIN_NAME_RE = re.compile(
    r"^(?=.{1,253}$)(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}$")
MASTODON_HANDLE_RE = re.compile(
    r"^@?[A-Za-z0-9_](?:[A-Za-z0-9_.-]{0,62}[A-Za-z0-9_])?@[A-Za-z0-9.-]+\.[A-Za-z]{2,63}$")
MAX_NODE_NAME = 63

# A node's Ed25519 public key (raw 32 bytes, base64url, unpadded) — the value
# the desktop app's profile card itself labels "Node ID". The claim-node flow
# (issue #351) accepts this as an alternative to the account's chosen name,
# since that's what users copy when the app tells them their "node ID".
NODE_PUBKEY_RE = re.compile(r"^[A-Za-z0-9_-]{43}$")
# ACCOUNTS_RE is imported from urls.py with the rest of the route table.
LOGIN_MAX_SKEW_MS = 5 * 60 * 1000
# Login brute-force throttle: after LOGIN_MAX_FAILS failures (counted within a
# rolling window) the identifier is locked out for LOGIN_LOCKOUT_MS.
LOGIN_MAX_FAILS = 10
LOGIN_FAIL_WINDOW_MS = 15 * 60 * 1000
LOGIN_LOCKOUT_MS = 15 * 60 * 1000
# Per-source-IP account-creation throttle: at most SIGNUP_MAX_PER_IP new accounts
# from one IP per rolling SIGNUP_RATE_WINDOW_MS, to blunt mass signup / name
# squatting. Login has its own lockout; catalog writes have their own cooldown.
SIGNUP_RATE_WINDOW_MS = 60 * 60 * 1000
SIGNUP_MAX_PER_IP = 5
ADMIN_SESSION_TTL_MS = 12 * 60 * 60 * 1000
# How long a password-reset link stays valid after it is emailed.
PASSWORD_RESET_TTL_MS = 60 * 60 * 1000
# Users-vs-nodes linking (adhoc #53). A website claim's confirmation code (shown
# on the node, typed into the site) lives this long; an installer link code
# (shown by install.sh, typed into the installing desktop app) lives longer
# because the fresh node still has to build/launch/register before it can
# present the code.
CLAIM_CODE_TTL_MS = 10 * 60 * 1000
CLAIM_CODE_MAX_ATTEMPTS = 5
# An admin-initiated ownership takeover (adhoc #141) rides back to the target
# node on its own heartbeat, same as a claim code, but the node may be offline
# for a while before it's seen and approved/denied, so it gets a long window.
OWNERSHIP_TRANSFER_TTL_MS = 24 * 60 * 60 * 1000
LINK_CODE_TTL_MS = 30 * 60 * 1000
LINK_CODE_RE = re.compile(r"^[0-9]{6}$")
MAX_AVATAR_BYTES = 256 * 1024
MAX_AVATAR_B64 = 4 * ((MAX_AVATAR_BYTES + 2) // 3)
PNG_HEADER = b"\x89PNG\r\n\x1a\n"
# Repo branding (fediverse actor avatar/header). Each image lives in its own
# encrypted repo_media row, so the caps only need to keep ONE image (b64 +
# AES-GCM + b64 again ≈ 1.8x raw) under D1's 2 MB per-value limit.
MAX_REPO_LOGO_BYTES = 256 * 1024
MAX_REPO_BANNER_BYTES = 1024 * 1024


def valid_node_name(value):
    value = (value or "").strip()
    return (bool(value) and len(value) <= MAX_NODE_NAME and
            bool(NODE_NAME_RE.match(value)))


def valid_node_pubkey(value):
    return bool(NODE_PUBKEY_RE.match((value or "").strip()))


def notification_mentions(*parts):
    found = set()
    for part in parts:
        if not part:
            continue
        for match in MENTION_RE.finditer(str(part).lower()):
            name = match.group(1)
            if name and len(name) <= MAX_NODE_NAME and NODE_NAME_RE.match(name):
                found.add(name)
    return sorted(found)


def notification_payload(kind, title, body="", repo="", href="", actor="",
                         source="", ts=0, meta=None):
    kind = kind if kind in NOTIFICATION_KINDS else "pending_inbox"
    return {
        "kind": kind,
        "title": clean_string(title, 160),
        "body": clean_string(body, 500),
        "repo": clean_string(repo, 180),
        "href": clean_string(href, 512),
        "actor": clean_string(actor, 120),
        "source": clean_string(source, 80),
        "ts": int(ts or 0),
        "readAt": 0,
        "meta": meta if isinstance(meta, dict) else {},
    }


def notification_email_preferences(rec):
    prefs = dict(NOTIFICATION_EMAIL_DEFAULTS)
    raw = rec.get("notification_preferences") if isinstance(rec, dict) else {}
    if isinstance(raw, dict):
        for key in NOTIFICATION_EMAIL_KINDS:
            if key in raw:
                prefs[key] = bool(raw.get(key))
    return prefs


def notification_email_enabled(rec, kind):
    kind = clean_string(kind, 40)
    if kind not in NOTIFICATION_EMAIL_DEFAULTS:
        return False
    return bool(notification_email_preferences(rec).get(kind))


def _clean_notification_preferences(raw, rec=None):
    prefs = notification_email_preferences(rec or {})
    if not isinstance(raw, dict):
        return prefs
    for key in NOTIFICATION_EMAIL_KINDS:
        if key in raw:
            prefs[key] = bool(raw.get(key))
    return prefs


def repo_web_href(owner, repo):
    # Clean, shareable repo link (/owner/repo) for notification "Open context"
    # buttons. 404.html bounces this to the dashboard's repo view and dashboard.js
    # keeps the clean path in the address bar, so links read forkmesh.com/owner/repo
    # rather than the old forkmesh.com/dashboard?repo=owner/repo form.
    return "/" + quote(owner) + "/" + quote(repo)


# The signed-event crypto + canonical-content helpers (b64url_decode,
# ed25519_verify, sha256_hex, the verify_* verifiers and *_content
# canonicalizers) were extracted into events.py (adhoc #279); imported above.


def git_bytes_response(data, content_type):
    return JsResponse.new(
        # Copy into a JS-owned buffer: a bare _to_js(bytes) is a view into
        # Python's WASM memory, and the client streams this body AFTER the
        # handler returns and the GIL is released — reading the view then is a
        # runtime crash ("PyProxy when Python GIL not held"), not an exception,
        # and it poisons the isolate for every later invocation (incl. cron).
        Uint8Array.new(_to_js(bytes(data))),
        to_js(
            {
                "status": 200,
                "headers": {
                    "content-type": content_type,
                    "cache-control": "no-cache, max-age=0, must-revalidate",
                },
            }
        ),
    )


def to_js(value):
    return _to_js(value, dict_converter=Object.fromEntries)


def new_socket_id():
    # Stable per-socket id stored in the hibernation attachment, so we can skip
    # the sender on broadcast without relying on object identity (which does not
    # survive a Durable Object eviction).
    rnd = js_crypto.getRandomValues(Uint8Array.new(4))
    return "%d-%d" % (int(Date.now()),
                      (rnd[0] << 24) | (rnd[1] << 16) | (rnd[2] << 8) | rnd[3])


def new_world_peer_id():
    # World ids are random per connection and deliberately contain no account,
    # node, address, timestamp, or device identifier.
    rnd = js_crypto.getRandomValues(Uint8Array.new(8))
    return "".join("%02x" % int(rnd[index]) for index in range(8))


def _ws_attachment(ws):
    try:
        return ws.deserializeAttachment()
    except Exception:
        return None


def _ws_attr(ws, name, default=None):
    att = _ws_attachment(ws)
    if att is None:
        return default
    value = getattr(att, name, default)
    return default if value is None else value


def json_response(data, status=200, cache_seconds=None, cache_control=None,
                  extra_headers=None):
    headers = {"content-type": "application/json; charset=utf-8"}
    if cache_control is not None:
        headers["cache-control"] = cache_control
    elif cache_seconds is not None:
        # Lets both the Cloudflare edge cache (via the Cache API) and the browser
        # reuse this response for cache_seconds, collapsing repeated polls.
        headers["cache-control"] = "public, max-age=%d" % cache_seconds
    if extra_headers:
        headers.update(extra_headers)
    # Compact separators: pretty-printing every API reply cost measurable
    # Pyodide CPU and bytes on hot paths (/api/sync, catalog) — a real factor
    # in the 2026-07-11 free-plan 1102 overload.
    return Response(json.dumps(data, separators=(",", ":")),
                    status=status, headers=headers)


def _legacy_custody_not_ready_response():
    """Public, identity-free readiness failure for an upgraded legacy D1."""
    return json_response({
        "ok": False,
        "status": "not_ready",
        "error": "legacy_custody_migration_required",
        "custody": "offline-reconciliation-required",
        "notice": (
            "This upgraded instance cannot enable its D1-backed API while "
            "historical wallet material remains. The operator must use the "
            "documented offline export, finalized zero-balance reconciliation "
            "and explicit scrub; this response exposes no key, address, "
            "account, repository or balance."
        ),
    }, status=503, cache_control="no-store, max-age=0, must-revalidate")


# --- Edge cache (Cache API) helpers -----------------------------------------
# Dynamic Worker responses are not edge-cached automatically; we cache the few
# read-heavy aggregate endpoints explicitly so a burst of visitors collapses to
# one origin computation per colo per TTL. Keys are synthetic absolute URLs.

async def edge_cache_match(cache_key):
    try:
        hit = await js_caches.default.match(cache_key)
    except Exception:
        hit = None
    return Response(hit) if hit is not None else None


async def edge_cache_put(cache_key, response):
    # cache.put consumes the body it is handed, so store a clone and return the
    # original to the caller. Accepts both the workers.Response wrapper and a
    # raw JS Response (the binary media endpoints build the latter).
    # Best-effort: a cache failure must not fail the read.
    try:
        js_resp = getattr(response, "js_object", None) or response
        await js_caches.default.put(cache_key, js_resp.clone())
    except Exception:
        pass


async def edge_cache_match_media(cache_key, fallback_type):
    # Binary edge-cache read for the media endpoints, which respond with raw
    # JS Responses rather than the workers.Response wrapper the JSON helpers
    # return. Rebuilt like git_advert_cache_get so the body streams cleanly.
    try:
        hit = await js_caches.default.match(cache_key)
    except Exception:
        hit = None
    if hit is None:
        return None
    try:
        ctype = hit.headers.get("content-type")
        ccontrol = hit.headers.get("cache-control")
    except Exception:
        ctype, ccontrol = None, None
    return JsResponse.new(hit.body, to_js({
        "status": 200,
        "headers": {
            "content-type": ctype or fallback_type,
            "cache-control": ccontrol or "public, max-age=86400",
        },
    }))


async def edge_cache_delete(cache_key):
    try:
        await js_caches.default.delete(cache_key)
    except Exception:
        pass


# Seconds a clone ref-advertisement (info/refs) is held in the colo edge cache.
# The cache key already carries the repo's attested state hash, so an entry
# self-invalidates the instant the refs change (its key stops being requested);
# this TTL is only a backstop that lets a colo re-fetch if a state-hash update is
# ever missed. See git_advert_cache_key and Default._clone_advert_cache_key.
GIT_ADVERT_CACHE_TTL = 300


async def git_advert_cache_get(cache_key):
    # Return a cached clone advertisement as a fresh no-cache response. git must
    # re-validate info/refs on every fetch, so the bytes handed to the client
    # keep git's own no-store semantics even though the edge copy is reused.
    try:
        hit = await js_caches.default.match(cache_key)
    except Exception:
        hit = None
    if hit is None:
        return None
    try:
        ctype = hit.headers.get("content-type")
    except Exception:
        ctype = None
    return JsResponse.new(hit.body, to_js({
        "status": 200,
        "headers": {
            "content-type": ctype or "application/x-git-upload-pack-advertisement",
            "cache-control": "no-cache, max-age=0, must-revalidate",
        },
    }))


async def git_advert_cache_put(cache_key, response, ttl=GIT_ADVERT_CACHE_TTL):
    # Store a cacheable clone of the advertisement. The live response carries
    # git's "no-cache, max-age=0" headers, which the Cache API refuses to store,
    # so the stored copy is rebuilt with a public max-age; the original response
    # is returned to the client untouched. Best-effort — a cache failure must not
    # fail the clone.
    try:
        js_resp = getattr(response, "js_object", None) or response
        clone = js_resp.clone()
        try:
            ctype = clone.headers.get("content-type")
        except Exception:
            ctype = None
        cacheable = JsResponse.new(clone.body, to_js({
            "status": 200,
            "headers": {
                "content-type": ctype
                or "application/x-git-upload-pack-advertisement",
                "cache-control": "public, max-age=%d" % ttl,
            },
        }))
        await js_caches.default.put(cache_key, cacheable)
    except Exception:
        pass


async def purge_catalog_related_caches():
    # One concurrent sweep instead of four sequential awaits — this runs on
    # every catalog write, inside the request's critical path.
    await asyncio.gather(*(
        edge_cache_delete(key)
        for key in (
            CATALOG_CACHE_KEY,
            NETWORK_STATS_CACHE_KEY,
            NETWORK_LEADERBOARDS_CACHE_KEY,
            NETWORK_OVERVIEW_CACHE_KEY,
        )), return_exceptions=True)


# Versioned so the fail-closed visibility contract never reuses an edge entry
# produced by the historical plaintext-flag-only catalog.
CATALOG_CACHE_KEY = "https://forkmesh.internal/api/repositories?privacy=v2"
# Guest (viewer-less) GET /api/accounts/<name> payloads, keyed by name.
ACCOUNT_LOOKUP_CACHE_PREFIX = "https://forkmesh.internal/api/accounts/"
PROFILE_CONTRIBUTION_CACHE_PREFIX = (
    "https://forkmesh.internal/api/profile-contributions/"
)
PROFILE_CONTRIBUTION_CACHE_TTL = 30
NETWORK_STATS_CACHE_KEY = "https://forkmesh.internal/api/network/stats"
NETWORK_LEADERBOARDS_CACHE_KEY = "https://forkmesh.internal/api/network/leaderboards"
NETWORK_OVERVIEW_CACHE_KEY = "https://forkmesh.internal/api/network/overview"
# Seconds the repositories list is cached at the edge. Every write path calls
# purge_catalog_related_caches, so a longer TTL only delays third-party edits;
# 10s meant a full (purge + multi-table) rebuild every 10s per colo under load.
CATALOG_TTL = 30


async def repo_live_host_count(env, owner, repo):
    owner = safe_segment(owner)
    repo = safe_segment(repo)
    if not owner or not repo:
        return None
    try:
        await ensure_schema(env)
        now = int(Date.now())
        row = await d1_first(
            env,
            "SELECT COUNT(*) AS total FROM mirror_https_endpoints "
            "WHERE lower(node_name)=lower(?) AND healthy=1 "
            "AND abuse_blocked=0 AND integrity='ok' "
            "AND checked_at>=?",
            owner,
            now - HOST_PRESENCE_STALE_MS,
        )
        return max(0, int((row or {}).get("total") or 0))
    except Exception:
        return None


async def notify_repo_host(env, owner, repo, topic):
    # Repository control sockets were retired. Clients discover changes with
    # bounded HTTPS polling; repository bytes always use the mirror gateway.
    del env, owner, repo, topic


# Per-isolate memo of recent DO live-host probes: key_bi -> {"ts", "hosts"}
# ("hosts" is None when the probe failed/timed out). hydrate_repo_group_live_
# hosts used to await one Durable Object probe PER stale group member
# SEQUENTIALLY (up to HOST_COUNT_TIMEOUT_MS each) on every public info/refs,
# browse and /mirrors request. A logical repo group with many offline mirrors
# (a fleet die-off purges their host_presence rows, so every member stays
# "stale" forever) turned each request into minutes of awaiting dead tunnels —
# the Workers runtime then canceled the request as hung, surfacing the Pyodide
# "Cannot enter into task" error on git-upload-pack info/refs (adhoc #167, the
# same info/refs-hang family as adhoc #144/#153). Probes now run concurrently,
# are capped per request (also protecting the per-request subrequest budget),
# and every completed probe — including a failed one — is memoized briefly so
# a clone burst doesn't re-probe the same dead mirrors on every request.
_LIVE_HOST_PROBE_MEMO = {}
LIVE_HOST_PROBE_MEMO_TTL_MS = 30 * 1000
HYDRATE_PROBE_MAX = 8


async def hydrate_repo_group_live_hosts(env, owner, repo, catalog_rows,
                                        presence, now):
    # host_presence is an eventually-refreshed D1 cache. For routing and the
    # public mirror list, the DO's connected host count is the ground truth. Probe
    # only the logical repo group for this request and patch the in-memory
    # presence map before candidate selection.
    owner_l = str(owner or "").strip().lower()
    repo_l = str(repo or "").strip().lower()
    if not owner_l or not repo_l:
        return presence
    target = None
    for row in catalog_rows or []:
        rec = row.get("data") or {}
        if (str(rec.get("owner") or "").strip().lower() == owner_l and
                str(rec.get("name") or "").strip().lower() == repo_l):
            target = rec
            break
    if target is None:
        # Fallback mirrors can still be selected by name when the named source
        # has no catalog row yet.
        target = {"owner": owner, "name": repo, "rootCommit": ""}
    stale = []
    for row in catalog_rows or []:
        rec = row.get("data") or {}
        key = str(row.get("key_bi") or "")
        if not key or not repo_mirror_same_group(target, rec):
            continue
        # Fresh D1 presence (heartbeat within the last 30s) is trustworthy —
        # skip the per-mirror Durable Object probe subrequest for those. Only
        # stale/missing entries get the ground-truth DO check; this bounded
        # the N-subrequest fan-out that ran on every /mirrors request.
        if now - int(presence.get(key, 0) or 0) < 30 * 1000:
            continue
        memo = _LIVE_HOST_PROBE_MEMO.get(key)
        if memo and now - memo["ts"] < LIVE_HOST_PROBE_MEMO_TTL_MS:
            hosts = memo["hosts"]
            if hosts is not None:
                if hosts > 0:
                    presence[key] = now
                else:
                    presence.pop(key, None)
            continue
        stale.append((key, rec))
    # Probe concurrently (each already bounded by HOST_COUNT_TIMEOUT_MS inside
    # repo_live_host_count, so the whole batch costs one timeout, not one per
    # mirror) and capped per request. Members beyond the cap keep their stale
    # presence this request; because probed members land in the memo, the next
    # request's stale list starts where this one stopped, so a large group is
    # covered across a few requests instead of hanging any single one.
    probes = stale[:HYDRATE_PROBE_MAX]
    results = await asyncio.gather(*(
        repo_live_host_count(env, rec.get("owner"), rec.get("name"))
        for _key, rec in probes), return_exceptions=True)
    for (key, _rec), hosts in zip(probes, results):
        if not isinstance(hosts, int):
            hosts = None  # failed/timed-out probe: memoized, presence untouched
        _LIVE_HOST_PROBE_MEMO[key] = {"ts": now, "hosts": hosts}
        if hosts is None:
            continue
        if hosts > 0:
            presence[key] = now
        else:
            presence.pop(key, None)
    return presence


async def next_clone_rotation(env, repo_bi):
    # Advance and read back this repo's round-robin cursor so consecutive clone
    # fallbacks rotate across its mirrors instead of all hitting the freshest one.
    # Best-effort: any failure yields 0 (the freshest-first pick), so a flaky
    # counter never blocks a redirect.
    try:
        await ensure_schema(env)
        await d1_run(
            env,
            "INSERT INTO clone_rr (repo_bi, n) VALUES (?, 1) "
            "ON CONFLICT(repo_bi) DO UPDATE SET n = n + 1",
            repo_bi,
        )
        row = await d1_first(env, "SELECT n FROM clone_rr WHERE repo_bi=?", repo_bi)
        return int((row or {}).get("n") or 0)
    except Exception:
        return 0


async def _flagship_client_count(env):
    # One internal request to the flagship room's count endpoint (not a WebSocket).
    try:
        room_id = env.FORKMESH_MAINNODE_ROOM.idFromName(FLAGSHIP_ROOM_KEY)
        room = env.FORKMESH_MAINNODE_ROOM.get(room_id)
        resp = await room.fetch(
            "https://forkmesh.internal/api/repo/mainnode/forkmesh/rooms/general/clients"
        )
        data = await resp.json()
        # workers.Response.json() may cross the Python/JS boundary as either a
        # native dict or a JsProxy depending on where the response was created;
        # accept both shapes (see the host-count read in select_install_source).
        clients = (data.get("clients", 0) if isinstance(data, dict)
                   else getattr(data, "clients", 0))
        return int(clients or 0)
    except Exception:
        return 0


async def network_stats(env, include_payouts=False):
    # Aggregate homepage stats: repo count (D1), live host count (presence table),
    # and flagship-room client count (one internal request). Cached at the edge.
    cache_key = NETWORK_STATS_CACHE_KEY + ("?payouts=1" if include_payouts else "")
    cached = await edge_cache_match(cache_key)
    if cached is not None:
        return cached

    await ensure_schema(env)
    now = int(Date.now())
    repo_row = await d1_first(env, "SELECT COUNT(*) AS n FROM repositories")
    repos = int((repo_row or {}).get("n", 0) or 0)

    cutoff = now - HOST_PRESENCE_STALE_MS
    try:
        await notify_stale_hosts_offline(env, cutoff)
        await d1_run(env, "DELETE FROM host_presence WHERE ts < ?", cutoff)
    except Exception:
        pass

    # Named list of the nodes that are actually online right now (same signal the
    # uptime cron samples), so the dashboard rail can show *who* is live instead of
    # painting the 48h uptime leaderboard green — a node offline now must not look
    # active, and a node that just came up must appear even with no accrued minutes.
    #
    # The headline "Nodes" count is the size of THIS set — the distinct, publicly
    # known nodes (a catalog record or a registered account) that are live — rather
    # than a raw COUNT of host_presence rows. A plain row count over-reports: one
    # node hosting several repos counts many times, and an ad-hoc/private tunnel
    # with no public catalog record inflates the total with a node we never name.
    # Deriving the count from the named set is what makes the Network panel agree
    # with the Mirror nodes list on who is online (adhoc #93).
    try:
        online_nodes = sorted(
            {label for label in (await _live_online_nodes(env, now)).values() if label}
        )
        hosts = len(online_nodes)
    except Exception:
        online_nodes = []
        host_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM host_presence WHERE ts >= ?", cutoff
        )
        hosts = int((host_row or {}).get("n", 0) or 0)

    clients = await _flagship_client_count(env)
    payout_nodes = await _network_payout_nodes(env) if include_payouts else None

    resp = json_response(
        {"ok": True, "repos": repos, "hosts": hosts, "clients": clients,
         "onlineNodes": online_nodes,
         **({
             "payoutNodes": payout_nodes,
             "payoutCustody": "external-self-custodial-addresses",
             "payoutFundStates": {
                 "userOwnedFunds": (
                     "Balances belong to each external wallet owner."
                 ),
                 "communityFundedPool": (
                     "Separate public pool metadata is available from "
                     "/api/rewards/pool."
                 ),
                 "pendingRewards": (
                     "Ledger allocations only; funds remain in the external "
                     "source wallet."
                 ),
                 "completedOnChainTransfers": (
                     "Complete only after a finalized public signature."
                 ),
             },
             "payoutNotice": (
                 "Non-custodial: payout nodes publish public addresses only. "
                 "ForkMesh does not hold their funds or wallet keys, and a "
                 "listed balance or eligible state does not guarantee payment."
             ),
         } if include_payouts else {})},
        cache_seconds=NETWORK_STATS_TTL,
    )
    await edge_cache_put(cache_key, resp)
    return resp


async def _network_payout_nodes(env):
    cutoff = int(Date.now()) - ACCOUNT_PRESENCE_STALE_MS
    try:
        await d1_run(env, "DELETE FROM account_presence WHERE ts < ?", cutoff)
    except Exception:
        pass
    rows = await d1_all(
        env,
        """SELECT n.node_bi AS name_bi, n.name, n.data, ap.ts AS online_ts
             FROM nodes n
             LEFT JOIN account_presence ap
               ON ap.name_bi = n.node_bi AND ap.ts >= ?
             ORDER BY COALESCE(ap.ts, 0) DESC, n.name ASC""",
        cutoff,
    )
    mirroring = await _mirroring_owners(env)
    nodes = []
    seen_wallets = set()
    for row in rows:
        rec = await decrypt_row(env, row.get("data"))
        if not rec or rec.get("status") != "active":
            continue
        name = clean_string(row.get("name") or rec.get("name", ""), MAX_NODE_NAME)
        wallet = (rec.get("solana") or "").strip()
        has_wallet = bool(wallet and SOLANA_RE.match(wallet))
        online = bool(row.get("online_ts"))
        first_wallet = has_wallet and wallet not in seen_wallets
        # Balance is public display metadata only. Funding a payout address is
        # never an eligibility or wallet-verification requirement.
        balance = await _solana_balance_lamports(env, wallet) if has_wallet else None
        # A node only shares the split if it mirrors a repo for another node, so
        # its eligibility on /network/ must reflect that too (issue #94).
        mirrors_repo = mirroring is None or bool(name and name.lower() in mirroring)
        eligible = bool(online and first_wallet and mirrors_repo)
        if has_wallet:
            seen_wallets.add(wallet)
        reason = "eligible"
        if not online:
            reason = "offline"
        elif not has_wallet:
            reason = "missing_wallet"
        elif not first_wallet:
            reason = "duplicate_wallet"
        elif not mirrors_repo:
            reason = "no_mirrors"
        nodes.append({
            "name": name or _short_presence_label("node", row.get("name_bi")),
            "wallet": wallet if has_wallet else "",
            "balanceLamports": balance,
            "balanceSol": _amount_sol(balance) if balance is not None else "",
            "online": online,
            "payoutEligible": eligible,
            "eligibilityReason": reason,
        })
    # Main relay: surface only federated candidates whose original node-signed
    # evidence still verifies and is fresh. Historical wallet-only rows never
    # appear payout-eligible.
    if _is_main_relay(env):
        try:
            now = int(Date.now())
            freshness = _reward_config(env)["healthFreshMs"]
            expected_refs = await _https_mirror_expected_forkmesh_refs(env)
            fed = await d1_all(
                env,
                "SELECT fp.*, r.label AS label "
                "FROM federated_presence fp "
                "JOIN relays r ON r.relay_bi = fp.relay_bi "
                "WHERE fp.ts >= ? AND r.status = 'approved' "
                "AND fp.checked_at>=? AND fp.forkmesh_verified_at>=? "
                "ORDER BY fp.ts DESC",
                cutoff,
                now - freshness,
                now - freshness,
            )
            for r in (fed or []):
                attested = await _verified_federated_reward_attestation(
                    env,
                    {
                        "name": r.get("name"),
                        "operator": r.get("name"),
                        "wallet": r.get("wallet"),
                        "publicKey": r.get("public_key"),
                        "baseUrl": r.get("base_url"),
                        "registrationSignature": r.get("registration_sig"),
                        "registrationIssuedAt": r.get(
                            "registration_issued_at"),
                        "healthMessage": r.get("health_message"),
                        "healthSignature": r.get("health_sig"),
                        "checkedAt": r.get("checked_at"),
                        "healthy": bool(int(r.get("healthy") or 0)),
                        "integrity": r.get("integrity"),
                        "mirrorsForkMesh": bool(
                            int(r.get("forkmesh_active") or 0)),
                        "forkmeshVerifiedAt": r.get(
                            "forkmesh_verified_at"),
                        "refsSha256": r.get("forkmesh_refs_sha256"),
                        "operationsSha256": r.get(
                            "forkmesh_operations_sha256"),
                        "requiredOperationsVerified": True,
                        "abuseFlagged": bool(
                            int(r.get("abuse_blocked") or 0)),
                    },
                    now,
                    expected_refs,
                    freshness,
                )
                if not attested:
                    continue
                wallet = attested["wallet"]
                eligible = wallet not in seen_wallets
                seen_wallets.add(wallet)
                relay_label = clean_string(r.get("label", ""), 80) or "relay"
                nodes.append({
                    "name": clean_string(r.get("name", ""), MAX_NODE_NAME) or "node",
                    "wallet": wallet,
                    "balanceLamports": None, "balanceSol": "",
                    "online": True, "payoutEligible": eligible,
                    "eligibilityReason": "eligible" if eligible else "duplicate_wallet",
                    "relay": relay_label,
                    "attestation": "signed-fresh-forkmesh-mirror",
                })
        except Exception:
            pass
    return nodes


# --- Online-activity history (24h graph on /network/) -----------------------
# A per-minute cron records how many nodes are online into the current hour's
# bucket, so each hour's value is "node-minutes online" that hour.

ONLINE_SAMPLE_WINDOW_MS = 2 * 60 * 1000  # treat a node seen in the last 2 min as online
ONLINE_HISTORY_RETAIN_MS = 48 * 60 * 60 * 1000
ONLINE_HISTORY_MAX_NODES = 50


def _short_presence_label(prefix, key):
    return prefix + " " + str(key or "")[:8]


async def _live_online_nodes(env, now):
    nodes = {}
    host_rows = await d1_all(
        env,
        """SELECT hp.repo_bi, r.owner_bi, r.is_private, r.data
             FROM host_presence hp
             LEFT JOIN repositories r ON r.key_bi = hp.repo_bi
             WHERE hp.ts >= ?""",
        now - HOST_PRESENCE_STALE_MS,
    )
    for row in host_rows:
        # A host_presence row is written for ANY owner/repo URL that gets served
        # (touch_host_presence keys on a blind index of the path), so it includes
        # repos that were never published to the catalog — ad-hoc hosts. Those
        # rows don't join to a repository, and the public /network/ graph used to
        # surface them as anonymous "repo <hash>" phantom nodes. Only count hosts
        # serving a published, public, non-blocked repo, keyed by owner — the same
        # filtering the catalog and leaderboards apply.
        owner_bi = row.get("owner_bi")
        if not owner_bi or not row.get("data") or int(row.get("is_private") or 0):
            continue
        rec = await decrypt_row(env, row["data"])
        if not rec:
            continue
        if rec.get("visibility") != "public":
            continue
        if _is_blocked_catalog_identity(env, rec.get("owner"), rec.get("name")):
            continue
        label = clean_string(rec.get("owner", ""), MAX_NODE_NAME)
        if not label:
            continue
        nodes[owner_bi] = label

    endpoint_rows = await d1_all(
        env,
        """SELECT n.node_bi, n.name
             FROM mirror_https_endpoints e
             JOIN nodes n ON lower(n.name)=lower(e.node_name)
            WHERE e.healthy=1 AND e.abuse_blocked=0
              AND e.integrity='verified' AND e.checked_at>=?""",
        now - ONLINE_SAMPLE_WINDOW_MS,
    )
    for row in endpoint_rows:
        node_key = str(row.get("node_bi") or "")
        label = clean_string(row.get("name", ""), MAX_NODE_NAME)
        if node_key and label:
            nodes[node_key] = label

    acct_rows = await d1_all(
        env,
        """SELECT ap.name_bi, n.name, n.data
             FROM account_presence ap
             LEFT JOIN nodes n ON n.node_bi = ap.name_bi
             WHERE ap.ts >= ?""",
        now - ONLINE_SAMPLE_WINDOW_MS,
    )
    for row in acct_rows:
        node_key = row.get("name_bi")
        if not node_key:
            continue
        label = clean_string(row.get("name", ""), MAX_NODE_NAME)
        if not label and row.get("data"):
            rec = await decrypt_row(env, row["data"])
            if rec:
                label = clean_string(rec.get("name", ""), MAX_NODE_NAME)
        nodes[node_key] = label or nodes.get(node_key) or _short_presence_label("node", node_key)
    return nodes


async def record_online_sample(env):
    # Called once a minute by the scheduled (cron) handler. "Online nodes" is the
    # set of fresh signed direct-HTTPS endpoints together with account
    # heartbeats and bounded legacy presence rows.
    await ensure_schema(env)
    now = int(Date.now())
    nodes = await _live_online_nodes(env, now)
    online = len(nodes)
    hour_ts = (now // 3600000) * 3600000
    await d1_run(
        env,
        "INSERT INTO online_hourly (hour_ts, node_minutes) VALUES (?, ?) "
        "ON CONFLICT(hour_ts) DO UPDATE SET node_minutes = node_minutes + ?",
        hour_ts, online, online,
    )
    if nodes:
        # One multi-row upsert for every online node instead of a statement per
        # node — each awaited D1 round trip counts against the cron tick's
        # per-invocation limits (see record_status_sample).
        node_args = []
        for node_key, label in nodes.items():
            node_args.extend([hour_ts, node_key, label])
        await d1_run(
            env,
            "INSERT INTO online_hourly_nodes "
            "(hour_ts, node_key, label, node_minutes) VALUES " +
            ", ".join(["(?, ?, ?, 1)"] * len(nodes)) + " "
            "ON CONFLICT(hour_ts, node_key) DO UPDATE SET "
            "node_minutes = node_minutes + 1, "
            "label = excluded.label",
            *node_args,
        )
    # Retention prunes only need to run occasionally: first sample of each hour.
    if now - hour_ts < 60 * 1000:
        await d1_run(
            env, "DELETE FROM online_hourly WHERE hour_ts < ?",
            hour_ts - ONLINE_HISTORY_RETAIN_MS,
        )
        await d1_run(
            env, "DELETE FROM online_hourly_nodes WHERE hour_ts < ?",
            hour_ts - ONLINE_HISTORY_RETAIN_MS,
        )


ONLINE_HISTORY_CACHE_KEY = "https://forkmesh.internal/api/network/online-history"


async def online_history(env):
    # network.html polls this every minute per open tab (alongside the
    # already-cached leaderboards); serve the burst from the colo edge like
    # its siblings. The data is hourly buckets, so 30s staleness is free.
    cached = await edge_cache_match(ONLINE_HISTORY_CACHE_KEY)
    if cached is not None:
        return cached
    await ensure_schema(env)
    now = int(Date.now())
    cur_hour = (now // 3600000) * 3600000
    start = cur_hour - 23 * 3600000  # last 24 hourly buckets, oldest first
    rows = await d1_all(
        env,
        "SELECT hour_ts, node_minutes FROM online_hourly WHERE hour_ts >= ? "
        "ORDER BY hour_ts",
        start,
    )
    by_hour = {int(r["hour_ts"]): int(r["node_minutes"]) for r in rows}
    series = [{"hourTs": start + i * 3600000,
               "nodeMinutes": by_hour.get(start + i * 3600000, 0)}
              for i in range(24)]
    node_rows = await d1_all(
        env,
        """SELECT node_key, label, hour_ts, node_minutes
             FROM online_hourly_nodes
             WHERE hour_ts >= ?
             ORDER BY node_key, hour_ts""",
        start,
    )
    grouped = {}
    for row in node_rows:
        node_key = str(row.get("node_key") or "")
        if not node_key:
            continue
        item = grouped.setdefault(node_key, {
            "label": clean_string(row.get("label", ""), MAX_NODE_NAME) or
                     _short_presence_label("node", node_key),
            "hours": {},
            "total": 0,
        })
        minutes = int(row.get("node_minutes") or 0)
        hour_ts = int(row.get("hour_ts") or 0)
        item["hours"][hour_ts] = minutes
        item["total"] += minutes
        if row.get("label"):
            item["label"] = clean_string(row.get("label", ""), MAX_NODE_NAME)
    nodes = []
    for node_key, item in grouped.items():
        nodes.append({
            "id": node_key[:12],
            "label": item["label"],
            "totalMinutes": item["total"],
            "hours": [
                {"hourTs": start + i * 3600000,
                 "minutes": item["hours"].get(start + i * 3600000, 0)}
                for i in range(24)
            ],
        })
    nodes.sort(key=lambda n: (-int(n["totalMinutes"]), str(n["label"])))
    resp = json_response(
        {"ok": True, "hours": series, "nodes": nodes[:ONLINE_HISTORY_MAX_NODES]},
        cache_seconds=30,
    )
    await edge_cache_put(ONLINE_HISTORY_CACHE_KEY, resp)
    return resp


async def _response_json(response):
    try:
        data = await response.json()
        return data if isinstance(data, dict) else dict(data)
    except Exception:
        return {}


async def network_overview(env):
    cached = await edge_cache_match(NETWORK_OVERVIEW_CACHE_KEY)
    if cached is not None:
        return cached

    stats = await _response_json(await network_stats(env))
    leaderboards = await _response_json(await network_leaderboards(env))
    history = await _response_json(await online_history(env))
    resp = json_response(
        {
            "ok": True,
            "stats": stats,
            "leaderboards": leaderboards,
            "history": history,
        },
        cache_seconds=NETWORK_STATS_TTL,
    )
    await edge_cache_put(NETWORK_OVERVIEW_CACHE_KEY, resp)
    return resp


# --- System status page (/status) -------------------------------------------
# A per-minute cron folds one health check per system into today's UTC-day
# bucket, so the public /status page can show a 30-day history per system
# (statuspage.io style) without any extra always-on monitoring infra. Every
# system reuses a signal the relay already tracks:
#   - database: a trivial D1 round trip.
#   - git_hosting: at least one identity-bound direct HTTPS mirror has a fresh,
#     signed ForkMesh repository integrity proof.
#   - website / api / realtime: unhandled/5xx errors logged this minute
#     (log_error, see Default.fetch) bucketed by the path they hit, so an
#     incident in one area doesn't paint the whole site down.
#   - durable_objects: room requests killed by Cloudflare's free-tier DO
#     duration cap (log_durable_object_abort), tracked separately from the
#     rest of "realtime" so plan-limit aborts have their own visible history
#     instead of being buried in general realtime noise.
STATUS_SYSTEMS = [
    ("website", "Website"),
    ("api", "API"),
    ("database", "Database"),
    ("git_hosting", "Git hosting network"),
    ("realtime", "Realtime sync (chat & tunnels)"),
    ("durable_objects", "Durable Objects (free-tier duration limit)"),
]
# What each per-minute health sample actually verifies, shown when a /status
# visitor expands a system row. These must describe the real check
# record_status_sample runs — the systems share one sampler cron but each has
# its own signal, and the page must never imply a probe that doesn't exist.
STATUS_SYSTEM_CHECKS = {
    "website": (
        "Scans the last minute of the worker error log for unhandled "
        "exceptions or 5xx responses on page routes (anything outside "
        "/api/*). Passes when no page-serving errors were logged. This is a "
        "server-side error-log signal, not an external HTTP probe."),
    "api": (
        "Scans the last minute of the worker error log for unhandled "
        "exceptions or 5xx responses on /api/* routes. 502/503/504 on "
        "direct-mirror content paths (release blobs, repo browse, git clone) "
        "are excluded — those mean an upstream mirror is unavailable, which "
        "the Git hosting network check tracks instead."),
    "database": (
        "Runs a real SELECT round trip against the D1 database once a "
        "minute. Passes when the query returns a row; fails on any query "
        "error."),
    "git_hosting": (
        "Checks for at least one account-bound direct HTTPS endpoint with a "
        "signed, integrity-matching ForkMesh repository proof observed within "
        "the last 10 minutes. Repository bytes are not sampled into D1."),
    "realtime": (
        "Scans the last minute of the worker error log for failures on "
        "chat room / WebSocket paths and repository smart-HTTP request paths. "
        "Repository bytes use direct HTTPS, not Durable Object sockets. Passes "
        "when no realtime failures were logged."),
    "durable_objects": (
        "Counts requests killed by Cloudflare's free-tier Durable Object "
        "duration cap (\"Exceeded allowed duration\") in the last minute. "
        "Passes when none were killed. Tracked as its own system so "
        "plan-limit aborts stay visible instead of hiding inside the "
        "realtime row."),
}
STATUS_HISTORY_DAYS = 30
STATUS_HISTORY_RETAIN_MS = STATUS_HISTORY_DAYS * 24 * 60 * 60 * 1000
STATUS_SAMPLE_WINDOW_MS = 60 * 1000  # one cron tick
STATUS_HOUR_MS = 60 * 60 * 1000
STATUS_DAY_MS = 24 * STATUS_HOUR_MS
STATUS_MINUTES_SHOWN = 60  # width of the per-minute strip on /status
# Kept a little past what's shown so a slow reader's page load always has a
# full 60 buckets to render even a few minutes after the newest cron tick.
STATUS_MINUTE_RETAIN_MS = 90 * 60 * 1000


def _status_expected_checks_for_hour(hour_ts, now):
    """How many minute samples should exist for an elapsed hourly bucket.

    The current in-progress minute is not expected yet. This prevents the public
    page from flashing degraded between the page load and the next cron tick, but
    still treats missing completed minutes/hours as downtime.
    """
    hour_ts = int(hour_ts)
    now = int(now)
    if hour_ts > now:
        return 0
    if now >= hour_ts + STATUS_HOUR_MS:
        return 60
    return max(0, int((now - hour_ts) // STATUS_SAMPLE_WINDOW_MS))


def _status_effective_hour(hour_ts, now, row):
    """Fold one hourly bucket into what the /status page shows.

    Only recorded samples decide the color and the uptime math. A missing
    sample means the sampling cron itself didn't run that minute (free-tier
    limits regularly kill ticks) — a monitoring gap, not evidence the system
    was down, so it's reported as missingChecks / "unknown" instead of being
    folded into the failure count. Counting gaps as downtime is what used to
    paint every system with the same fabricated ~50% uptime while the site
    was actually up (the gaps are shared: one dead cron tick "fails" all six
    systems at once).
    """
    checks, failures, reason = row or (0, 0, None)
    checks = max(0, int(checks or 0))
    failures = max(0, min(int(failures or 0), checks))
    expected = max(_status_expected_checks_for_hour(hour_ts, now), checks)
    if expected <= 0:
        return {
            "hourTs": hour_ts, "status": "future", "checks": checks,
            "failures": failures, "expectedChecks": 0, "missingChecks": 0,
            "reason": None,
        }
    missing = max(0, expected - checks)
    if checks <= 0:
        status = "unknown"
    elif failures <= 0:
        status = "operational"
    elif failures >= checks:
        status = "down"
    else:
        status = "degraded"
    if status == "unknown":
        hour_reason = (
            "No health samples were recorded this hour — the sampling cron "
            "didn't run (monitoring gap), which is not evidence of an outage.")
    elif status == "operational":
        hour_reason = None
    else:
        hour_reason = reason
    return {
        "hourTs": hour_ts, "status": status,
        "checks": checks, "failures": failures,
        "expectedChecks": expected, "missingChecks": missing,
        "reason": hour_reason,
    }


def _status_minute(minute_ts, current_minute_ts, row):
    """Status of a single 60-second bucket for the /status minute strip.

    Unlike an hour, a minute has no finer subdivision to average over: it's
    either sampled ok, sampled failing, or (if it's the in-progress minute)
    not sampled yet — no "degraded" state is possible at this granularity.
    """
    minute_ts = int(minute_ts)
    if minute_ts >= current_minute_ts and row is None:
        # This minute's cron tick hasn't landed yet (the common case for the
        # newest bucket) — not evidence of an outage, just not elapsed.
        return {"minuteTs": minute_ts, "status": "future", "reason": None}
    if row is None:
        return {
            "minuteTs": minute_ts, "status": "unknown",
            "reason": "No health sample was recorded for this minute — the "
                      "sampling cron didn't run (monitoring gap), which is "
                      "not evidence of an outage.",
        }
    ok = bool(row.get("ok"))
    return {
        "minuteTs": minute_ts,
        "status": "operational" if ok else "down",
        "reason": None if ok else (row.get("reason") or None),
    }


async def record_status_sample(env):
    # Called once a minute by the scheduled (cron) handler. Best-effort per
    # system so one failing check can't blank the rest of the page.
    await ensure_schema(env)
    now = int(Date.now())
    day_ts = (now // 86400000) * 86400000
    hour_ts = (now // 3600000) * 3600000
    minute_ts = (now // 60000) * 60000
    ok = {}
    reason = {}

    try:
        await d1_first(env, "SELECT 1 AS ok")
        ok["database"] = True
    except Exception as exc:
        ok["database"] = False
        reason["database"] = "Database query failed: " + str(exc)[:160]

    try:
        cutoff = now - HTTPS_MIRROR_STATUS_FRESH_MS
        row = await d1_first(
            env,
            "SELECT COUNT(*) AS n FROM mirror_https_endpoints "
            "WHERE checked_at>=? AND forkmesh_verified_at>=? "
            "AND healthy=1 AND forkmesh_active=1 "
            "AND integrity IN ('ok','verified') AND abuse_blocked=0",
            cutoff, cutoff,
        )
        ok["git_hosting"] = int((row or {}).get("n", 0) or 0) > 0
        if not ok["git_hosting"]:
            reason["git_hosting"] = (
                "No healthy direct HTTPS mirror has supplied a valid ForkMesh "
                "repository proof within the last 10 minutes")
    except Exception as exc:
        ok["git_hosting"] = False
        reason["git_hosting"] = (
            "Direct HTTPS mirror health query failed: " + str(exc)[:160])

    try:
        rows = await d1_all(
            env, "SELECT path, status, message FROM error_log WHERE ts >= ?",
            now - STATUS_SAMPLE_WINDOW_MS,
        )
        failed = {"website": False, "api": False, "realtime": False, "durable_objects": False}
        first_hit = {"website": None, "api": None, "realtime": None, "durable_objects": None}
        hit_count = {"website": 0, "api": 0, "realtime": 0, "durable_objects": 0}
        for row in rows:
            path = str(row.get("path") or "")
            message = str(row.get("message") or "")
            try:
                row_status = int(row.get("status") or 0)
            except (TypeError, ValueError):
                row_status = 0
            # A DO duration-cap abort is a real room failure, so it still
            # counts toward "realtime" below — but it also gets its own
            # bucket so free-tier plan-limit aborts have a dedicated, visible
            # history instead of being buried among other realtime incidents.
            # Matches both the tagged 503s log_durable_object_abort records
            # and the raw AbortError tracebacks capture_worker_exception logs
            # for DO calls that aren't wrapped in a retry (same substring the
            # doDurationAborts24h snapshot below keys on).
            if "Exceeded allowed duration" in message:
                failed["durable_objects"] = True
                hit_count["durable_objects"] += 1
                if first_hit["durable_objects"] is None:
                    first_hit["durable_objects"] = (row.get("status"), path, message.strip())
            # 502/503/504 on a direct-mirror content path (release blob, repo
            # browse, git clone) means the selected endpoint is unreachable —
            # upstream availability, which the signed HTTPS health check
            # (the git_hosting signal) already tracks. It is not evidence the
            # Worker/API is down, and a single offline node's blob being
            # re-requested every few minutes used to paint the whole "api"
            # system red on /status. A 500 on the same path still counts.
            if row_status in (502, 503, 504) and (
                    RELEASE_BLOB_RE.match(path) or REPO_HOST_RE.match(path) or
                    GIT_INFO_RE.match(path) or GIT_PACK_RE.match(path)):
                continue
            if (path.rstrip("/") == "/api/world/ws" or
                    ROOM_RE.match(path) or REPO_ROOM_RE.match(path) or
                    GIT_INFO_RE.match(path) or GIT_PACK_RE.match(path)):
                bucket = "realtime"
            elif path.startswith("/api/"):
                bucket = "api"
            else:
                bucket = "website"
            failed[bucket] = True
            hit_count[bucket] += 1
            if first_hit[bucket] is None:
                first_hit[bucket] = (row.get("status"), path, message.strip())
        ok["website"] = not failed["website"]
        ok["api"] = not failed["api"]
        ok["realtime"] = not failed["realtime"]
        ok["durable_objects"] = not failed["durable_objects"]
        for bucket in ("website", "api", "realtime", "durable_objects"):
            if failed[bucket] and first_hit[bucket]:
                status_code, path, message = first_hit[bucket]
                text = (str(status_code) + " on " + path) if status_code else path
                if message:
                    text += ": " + message[:120]
                if hit_count[bucket] > 1:
                    text += " (+%d more)" % (hit_count[bucket] - 1)
                reason[bucket] = text
    except Exception:
        # A query hiccup here is not itself evidence of an outage — don't
        # fabricate a false incident from it.
        ok["website"] = ok["api"] = ok["realtime"] = ok["durable_objects"] = True

    # One multi-row upsert per table (3 statements total) instead of the old
    # 3-statements-per-system loop (15): the per-minute cron runs in a Pyodide
    # worker where every awaited D1 round trip counts against tight per-
    # invocation limits — blowing them killed the whole tick and the /status
    # page recorded the missing sample as downtime.
    daily_args = []
    hourly_args = []
    minute_args = []
    for system_id, _label in STATUS_SYSTEMS:
        failure = 0 if ok.get(system_id, True) else 1
        daily_args.extend([day_ts, system_id, failure])
        # reason is only set when this sample failed; on success it's left NULL
        # so the COALESCE below keeps whatever failure reason was last recorded
        # this hour, rather than blanking it out.
        hourly_args.extend([hour_ts, system_id, failure, reason.get(system_id)])
        # A minute is the raw sample itself (not a counter): one cron tick per
        # minute per system, so ON CONFLICT just overwrites in the rare case a
        # tick somehow re-fires for the same minute.
        minute_args.extend(
            [minute_ts, system_id, 0 if failure else 1, reason.get(system_id)])
    n = len(STATUS_SYSTEMS)
    await d1_run(
        env,
        "INSERT INTO system_status_daily (day_ts, system, checks, failures) "
        "VALUES " + ", ".join(["(?, ?, 1, ?)"] * n) + " "
        "ON CONFLICT(day_ts, system) DO UPDATE SET "
        "checks = checks + excluded.checks, "
        "failures = failures + excluded.failures",
        *daily_args,
    )
    await d1_run(
        env,
        "INSERT INTO system_status_hourly (hour_ts, system, checks, failures, reason) "
        "VALUES " + ", ".join(["(?, ?, 1, ?, ?)"] * n) + " "
        "ON CONFLICT(hour_ts, system) DO UPDATE SET "
        "checks = checks + excluded.checks, "
        "failures = failures + excluded.failures, "
        "reason = COALESCE(excluded.reason, system_status_hourly.reason)",
        *hourly_args,
    )
    await d1_run(
        env,
        "INSERT INTO system_status_minute (minute_ts, system, ok, reason) "
        "VALUES " + ", ".join(["(?, ?, ?, ?)"] * n) + " "
        "ON CONFLICT(minute_ts, system) DO UPDATE SET "
        "ok = excluded.ok, reason = excluded.reason",
        *minute_args,
    )
    # Retention prunes only need to run occasionally, not 60x/hour: sweep on
    # the first sample of each hour.
    if now - hour_ts < STATUS_SAMPLE_WINDOW_MS:
        await d1_run(
            env, "DELETE FROM system_status_daily WHERE day_ts < ?",
            day_ts - STATUS_HISTORY_RETAIN_MS,
        )
        await d1_run(
            env, "DELETE FROM system_status_hourly WHERE hour_ts < ?",
            day_ts - STATUS_HISTORY_RETAIN_MS,
        )
        await d1_run(
            env, "DELETE FROM system_status_minute WHERE minute_ts < ?",
            minute_ts - STATUS_MINUTE_RETAIN_MS,
        )


async def status_history(env):
    await ensure_schema(env)
    now = int(Date.now())
    cur_day = (now // 86400000) * 86400000
    start = cur_day - (STATUS_HISTORY_DAYS - 1) * 86400000
    # Day cells, uptime and coverage all come from the hourly buckets (which
    # sum to the same recorded counts the daily table holds, with per-hour
    # granularity the 24h window needs); the daily table remains as the
    # cron's cheap long-term aggregate.
    hour_rows = await d1_all(
        env,
        "SELECT hour_ts, system, checks, failures, reason FROM system_status_hourly "
        "WHERE hour_ts >= ?",
        start,
    )
    by_system_hour = {}
    for row in hour_rows:
        system_id = str(row.get("system") or "")
        by_system_hour.setdefault(system_id, {})[int(row["hour_ts"])] = (
            int(row.get("checks") or 0), int(row.get("failures") or 0),
            row.get("reason") or None,
        )

    current_minute = (now // 60000) * 60000
    minute_start = current_minute - (STATUS_MINUTES_SHOWN - 1) * 60000
    minute_rows = await d1_all(
        env,
        "SELECT minute_ts, system, ok, reason FROM system_status_minute "
        "WHERE minute_ts >= ?",
        minute_start,
    )
    by_system_minute = {}
    last_sample_ts = 0
    for row in minute_rows:
        system_id = str(row.get("system") or "")
        by_system_minute.setdefault(system_id, {})[int(row["minute_ts"])] = row
        last_sample_ts = max(last_sample_ts, int(row["minute_ts"]))

    systems = []
    for system_id, label in STATUS_SYSTEMS:
        # Uptime is computed over RECORDED samples only; expected-but-missing
        # samples (the sampling cron didn't run) are reported separately as
        # coverage, never counted as downtime. See _status_effective_hour.
        days = []
        total_checks = total_failures = total_expected = 0
        checks_24h = failures_24h = expected_24h = 0
        current_hour = (now // STATUS_HOUR_MS) * STATUS_HOUR_MS
        uptime_24h_start = current_hour - 23 * STATUS_HOUR_MS
        for i in range(STATUS_HISTORY_DAYS):
            this_day = start + i * STATUS_DAY_MS
            day_checks = day_failures = day_expected = 0
            hours = []
            for h in range(24):
                hour_ts = this_day + h * STATUS_HOUR_MS
                if hour_ts > now:
                    break
                hour = _status_effective_hour(
                    hour_ts, now, by_system_hour.get(system_id, {}).get(hour_ts),
                )
                day_expected += hour["expectedChecks"]
                day_checks += hour["checks"]
                day_failures += hour["failures"]
                if hour_ts >= uptime_24h_start:
                    expected_24h += hour["expectedChecks"]
                    checks_24h += hour["checks"]
                    failures_24h += hour["failures"]
                hours.append(hour)
            total_expected += day_expected
            total_checks += day_checks
            total_failures += day_failures
            uptime = (
                round(((day_checks - day_failures) / day_checks) * 100, 2)
                if day_checks else None
            )
            coverage = (
                round((min(day_checks, day_expected) / day_expected) * 100, 2)
                if day_expected else None
            )
            days.append({
                "dayTs": this_day, "checks": day_checks,
                "failures": day_failures,
                "expectedChecks": day_expected,
                "missingChecks": max(0, day_expected - day_checks),
                "uptimePct": uptime, "coveragePct": coverage,
                "hours": hours, "hoursElapsed": len(hours),
            })
        # Current status comes from the most recent HOUR with recorded
        # samples, not the whole current day's aggregate — otherwise an
        # incident that was resolved an hour ago keeps the badge red/yellow
        # for the rest of the day even once every recent check is green.
        # And if the newest recorded sample is over an hour stale, the honest
        # badge is "unknown": we have no current evidence either way, and
        # claiming operational (or down) from old data would be false info.
        latest_hour = None
        for d in reversed(days):
            for h in reversed(d["hours"]):
                if h["checks"]:
                    latest_hour = h
                    break
            if latest_hour:
                break
        reason_text = reason_ts = None
        if latest_hour is not None and (
                latest_hour["hourTs"] >= current_hour - STATUS_HOUR_MS):
            status = latest_hour["status"]
            if status != "operational":
                reason_text = latest_hour.get("reason")
                reason_ts = latest_hour.get("hourTs")
        elif latest_hour is not None:
            status = "unknown"
            reason_text = (
                "No health samples have been recorded since the sampling "
                "cron's last run — monitoring gap; the current state is "
                "unknown, not a confirmed outage.")
            reason_ts = latest_hour.get("hourTs")
        else:
            # No recorded samples anywhere in the 30-day window.
            status = "unknown"
        overall_uptime = (
            round(((total_checks - total_failures) / total_checks) * 100, 2)
            if total_checks else None
        )
        uptime_24h = (
            round(((checks_24h - failures_24h) / checks_24h) * 100, 2)
            if checks_24h else None
        )
        coverage_30d = (
            round((min(total_checks, total_expected) / total_expected) * 100, 2)
            if total_expected else None
        )
        coverage_24h = (
            round((min(checks_24h, expected_24h) / expected_24h) * 100, 2)
            if expected_24h else None
        )
        minutes = [
            _status_minute(
                minute_start + i * 60000, current_minute,
                by_system_minute.get(system_id, {}).get(minute_start + i * 60000),
            )
            for i in range(STATUS_MINUTES_SHOWN)
        ]

        systems.append({
            "id": system_id, "label": label, "status": status,
            "checkDescription": STATUS_SYSTEM_CHECKS.get(system_id, ""),
            "uptimePct": overall_uptime, "uptime24hPct": uptime_24h,
            "coveragePct": coverage_30d, "coverage24hPct": coverage_24h,
            "checks24h": checks_24h, "failures24h": failures_24h,
            "missing24h": max(0, expected_24h - checks_24h),
            "days": days, "minutes": minutes,
            "reason": reason_text,
            "reasonTs": reason_ts,
        })

    # Current-state snapshot (issue #356): the headline health metrics rendered
    # at the top of the page — flagship repository directly reachable, the
    # distinct online node count (same signal as the /network/ headline),
    # catalog size, and errors logged in the last 24h. Each
    # read is best-effort so one failing query can't blank the summary, and it
    # all rides on the single /api/status fetch a page view already makes.
    current = {}
    # When the last recorded health sample was taken. A stale value means the
    # sampling CRON is down (not the site) — the page uses this to say so
    # instead of letting missing samples masquerade as an outage. 0 = no
    # samples in the visible window at all.
    current["lastCronSampleTs"] = last_sample_ts or None
    try:
        repo_row = await d1_first(env, "SELECT COUNT(*) AS n FROM repositories")
        current["catalogRepos"] = int((repo_row or {}).get("n", 0) or 0)
    except Exception:
        current["catalogRepos"] = None
    try:
        online = {
            label for label in (await _live_online_nodes(env, now)).values() if label
        }
        current["onlineNodes"] = len(online)
    except Exception:
        current["onlineNodes"] = None
    try:
        err_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM error_log WHERE ts >= ?",
            now - 24 * 60 * 60 * 1000,
        )
        current["errors24h"] = int((err_row or {}).get("n", 0) or 0)
    except Exception:
        current["errors24h"] = None
    try:
        # Dedicated counter for the platform killing a Durable Object request
        # mid-flight ("Exceeded allowed duration in Durable Objects free
        # tier."). Matches both the tagged 503s the routers record via
        # log_durable_object_abort and the raw tracebacks
        # capture_worker_exception logged before the routers were guarded, so
        # the operator can tell plan-limit churn apart from real bugs inside
        # the generic errors24h count.
        do_row = await d1_first(
            env,
            "SELECT COUNT(*) AS n FROM error_log "
            "WHERE ts >= ? AND message LIKE ?",
            now - 24 * 60 * 60 * 1000, "%Exceeded allowed duration%",
        )
        current["doDurationAborts24h"] = int((do_row or {}).get("n", 0) or 0)
    except Exception:
        current["doDurationAborts24h"] = None
    try:
        # forkmesh_verified_at is written only after an account-bound endpoint
        # signs a fresh challenge whose refs hash matches the owner-attested
        # public forkmesh/forkmesh catalog state. This avoids treating a
        # control WebSocket heartbeat as proof that Git bytes are available.
        endpoint_row = await d1_first(
            env,
            "SELECT MAX(forkmesh_verified_at) AS ts "
            "FROM mirror_https_endpoints WHERE healthy=1 "
            "AND forkmesh_active=1 AND integrity IN ('ok','verified') "
            "AND abuse_blocked=0",
        )
        last_ts = int((endpoint_row or {}).get("ts") or 0) or None
        current["mainnodeLastSeenTs"] = last_ts
        current["mainnodeOnline"] = (
            last_ts is not None
            and now - last_ts < HTTPS_MIRROR_STATUS_FRESH_MS
        )
        current["mainnodeStaleMs"] = HTTPS_MIRROR_STATUS_FRESH_MS
    except Exception:
        current["mainnodeOnline"] = None
        current["mainnodeLastSeenTs"] = None
        current["mainnodeStaleMs"] = HTTPS_MIRROR_STATUS_FRESH_MS

    return json_response(
        {"ok": True, "now": now, "systems": systems, "current": current},
        cache_seconds=60,
    )


# --- Leaderboards (/network/) ----------------------------------------------
# Public ranking boards backing issue #11. Each board has a persisted data
# source: node uptime (online_hourly_nodes), public repos per owner + most-
# mirrored project + longest-hosted repo (repositories / repo_first_hosted),
# contributor activity (contributor_activity, tallied as issues/PRs/commits are
# submitted), and historical completed-transfer totals (funds_received). The
# Worker cannot sign or sweep a wallet.

LEADERBOARD_LIMIT = 10  # rows returned per board


async def _record_contributor(env, author, kind):
    # Bump a contributor's running activity tally. kind is one of
    # "issues"/"pulls"/"commits". Called as signed issue/PR/commit events are
    # accepted into the inbox; best-effort so a tally failure never blocks the
    # submission. author is the public contributor name.
    name = clean_string(author or "", MAX_NODE_NAME)
    if not name or kind not in ("issues", "pulls", "commits"):
        return
    try:
        author_bi = await blind_index(env, name.lower())
        await d1_run(
            env,
            f"""INSERT INTO contributor_activity
                  (author_bi, name, {kind}, total, last_ts)
                VALUES (?, ?, 1, 1, ?)
                ON CONFLICT(author_bi) DO UPDATE SET
                  {kind} = {kind} + 1, total = total + 1,
                  name = excluded.name, last_ts = excluded.last_ts""",
            author_bi, name, int(Date.now()),
        )
    except Exception:
        pass


async def _record_funds_received(env, scope, key, name, lamports):
    # Accumulate disbursed lamports per recipient for the funds-received boards.
    # Best-effort: never let a bookkeeping failure abort a money transfer.
    if not key or int(lamports or 0) <= 0:
        return
    try:
        await d1_run(
            env,
            """INSERT INTO funds_received (scope, key, name, lamports, last_ts)
               VALUES (?, ?, ?, ?, ?)
               ON CONFLICT(scope, key) DO UPDATE SET
                 lamports = lamports + excluded.lamports,
                 name = COALESCE(excluded.name, funds_received.name),
                 last_ts = excluded.last_ts""",
            scope, key, name or None, int(lamports), int(Date.now()),
        )
    except Exception:
        pass


def _catalog_updated_ms(rec):
    # Best-effort parse of a catalog record's free-form updatedAt string, so we
    # can tell which of a node's several repo mirrors last reported in (used to
    # pick the "latest" commit/platform/version for the node as a whole). Any
    # unparseable value sorts last rather than raising.
    try:
        ms = float(Date.parse(str(rec.get("updatedAt") or "")))
        return ms if ms == ms else -1  # NaN check (NaN != NaN)
    except Exception:
        return -1


async def network_leaderboards(env):
    cached = await edge_cache_match(NETWORK_LEADERBOARDS_CACHE_KEY)
    if cached is not None:
        return cached
    await ensure_schema(env)
    now = int(Date.now())

    # --- Uptime: rank nodes by total minutes online over the retained window.
    # online_hourly_nodes is pruned to ONLINE_HISTORY_RETAIN_MS, so this is
    # inherently a "last 48h" board. label is plaintext (the node's own name).
    window_start = now - ONLINE_HISTORY_RETAIN_MS
    uptime_rows = await d1_all(
        env,
        "SELECT node_key, label, node_minutes FROM online_hourly_nodes "
        "WHERE hour_ts >= ?",
        window_start,
    )
    uptime = {}
    for row in uptime_rows:
        key = str(row.get("node_key") or "")
        if not key:
            continue
        item = uptime.setdefault(key, {"label": "", "minutes": 0})
        item["minutes"] += int(row.get("node_minutes") or 0)
        if row.get("label"):
            item["label"] = clean_string(row.get("label", ""), MAX_NODE_NAME)
    uptime_board = [
        {"name": v["label"] or _short_presence_label("node", k),
         "minutes": v["minutes"]}
        for k, v in uptime.items() if v["minutes"] > 0
    ]
    uptime_board.sort(key=lambda n: (-n["minutes"], n["name"]))

    # --- Repos / mirrors / longest-hosted: one pass over the public catalog
    # (public only, blocked identities excluded). counts -> repos-per-owner;
    # mirror_owners -> distinct owners hosting a repo of a given name (a repo
    # mirrored by many nodes shows up under many owners); first-hosted timestamps
    # come from repo_first_hosted joined on key_bi.
    first_rows = await d1_all(env, "SELECT repo_bi, ts FROM repo_first_hosted")
    first_hosted = {str(r.get("repo_bi")): int(r.get("ts") or 0)
                    for r in first_rows if r.get("repo_bi")}
    repo_rows = await d1_all(
        env, "SELECT key_bi, owner_bi, data FROM repositories WHERE is_private = 0")
    try:
        active_nodes = await active_registered_node_bis(env, now)
    except Exception:
        active_nodes = None
    counts = {}
    mirror_owners = {}
    hosted_board = []
    largest_board = []          # per owner/repo, by reported mirror size
    bytes_by_owner = {}         # owner -> total bytes hosted across their repos
    # Per-node detail card for the Network page's "Connected nodes" list: sums
    # the per-repo counters a node reports (adhoc #56's commit/issues/platform/
    # version/id fields) across every repo it mirrors, and keeps the commit/
    # branch/platform/version/sync-time from whichever of its repos reported in
    # most recently — so a multi-repo node shows one coherent "latest" state.
    node_details = {}
    for row in repo_rows:
        if active_nodes is not None and str(row.get("owner_bi") or "") not in active_nodes:
            continue
        rec = await decrypt_row(env, row.get("data"))
        if not rec:
            continue
        if rec.get("visibility") != "public":
            continue
        if _is_blocked_catalog_identity(env, rec.get("owner"), rec.get("name")):
            continue
        owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME)
        name = clean_string(rec.get("name", ""), 120)
        if not owner:
            continue
        counts[owner] = counts.get(owner, 0) + 1
        try:
            size_bytes = max(0, int(rec.get("sizeBytes", 0) or 0))
        except (TypeError, ValueError):
            size_bytes = 0
        if size_bytes > 0:
            bytes_by_owner[owner] = bytes_by_owner.get(owner, 0) + size_bytes
        detail = node_details.setdefault(owner.lower(), {
            "name": owner, "sizeBytes": 0,
            "issueCount": 0, "commitCount": 0, "branchCount": 0,
            "pullCount": 0, "discussionCount": 0, "artifactCount": 0,
            "worktreeCount": 0, "clonesServed": 0, "websiteServed": 0,
            "commit": "", "branch": "", "lastSync": "",
            "platform": "", "version": "", "nodeId": "", "_updatedMs": -1,
        })
        detail["sizeBytes"] += size_bytes
        for field in ("issueCount", "commitCount", "branchCount", "pullCount",
                      "discussionCount", "artifactCount", "worktreeCount",
                      "clonesServed", "websiteServed"):
            try:
                detail[field] += max(0, int(rec.get(field, 0) or 0))
            except (TypeError, ValueError):
                pass
        updated_ms = _catalog_updated_ms(rec)
        if updated_ms > detail["_updatedMs"]:
            detail["_updatedMs"] = updated_ms
            detail["commit"] = clean_string(rec.get("commit", ""), 64)
            detail["branch"] = clean_string(rec.get("branch", ""), 120)
            detail["lastSync"] = clean_string(rec.get("lastSync", ""), 32)
            detail["platform"] = clean_string(rec.get("platform", ""), 16)
            detail["version"] = clean_string(rec.get("version", ""), 32)
            detail["nodeId"] = clean_string(rec.get("nodeId", ""), 64)
        if name:
            mirror_owners.setdefault(name, set()).add(owner.lower())
            if size_bytes > 0:
                largest_board.append(
                    {"name": owner + "/" + name, "bytes": size_bytes})
            ts = first_hosted.get(str(row.get("key_bi")))
            if ts:
                hosted_board.append(
                    {"name": owner + "/" + name, "since": ts,
                     "ageMs": max(0, now - ts)})
    node_board = [
        {k: v for k, v in detail.items() if k != "_updatedMs"}
        for detail in node_details.values()
    ]
    node_board.sort(key=lambda n: (-n["sizeBytes"], n["name"]))

    repo_board = [{"name": o, "repos": c} for o, c in counts.items()]
    repo_board.sort(key=lambda n: (-n["repos"], n["name"]))

    # --- Most mirrored: repo names hosted under more than one owner.
    mirror_board = [{"name": nm, "mirrors": len(owners)}
                    for nm, owners in mirror_owners.items() if len(owners) > 1]
    mirror_board.sort(key=lambda n: (-n["mirrors"], n["name"]))

    # --- Longest hosted: oldest first-hosted timestamp wins.
    hosted_board.sort(key=lambda n: (-n["ageMs"], n["name"]))

    # --- Largest repos / most data hosted: from the size each node reports for
    # its mirror. largest_board ranks individual repos; data_board sums per owner.
    largest_board.sort(key=lambda n: (-n["bytes"], n["name"]))
    data_board = [{"name": o, "bytes": b} for o, b in bytes_by_owner.items()]
    data_board.sort(key=lambda n: (-n["bytes"], n["name"]))

    # --- Contributor activity: cumulative issues + PRs + commits per author.
    contrib_rows = await d1_all(
        env,
        "SELECT name, issues, pulls, commits, total FROM contributor_activity "
        "WHERE total > 0 ORDER BY total DESC LIMIT ?",
        LEADERBOARD_LIMIT,
    )
    contrib_board = [
        {"name": clean_string(r.get("name", ""), MAX_NODE_NAME) or "contributor",
         "total": int(r.get("total") or 0),
         "issues": int(r.get("issues") or 0),
         "pulls": int(r.get("pulls") or 0),
         "commits": int(r.get("commits") or 0)}
        for r in contrib_rows if int(r.get("total") or 0) > 0
    ]

    # --- Funds received: separate boards for mainnodes, contributors, projects.
    # Recipients of node/contributor payouts are stored by wallet; resolve a
    # friendly node name where we can, else show a shortened address.
    funds = await _funds_received_boards(env)

    resp = json_response(
        {"ok": True,
         "windowHours": ONLINE_HISTORY_RETAIN_MS // 3600000,
         "uptime": uptime_board[:LEADERBOARD_LIMIT],
         "nodes": node_board,
         "repos": repo_board[:LEADERBOARD_LIMIT],
         "mirrors": mirror_board[:LEADERBOARD_LIMIT],
         "hosted": hosted_board[:LEADERBOARD_LIMIT],
         "largest": largest_board[:LEADERBOARD_LIMIT],
         "dataHosted": data_board[:LEADERBOARD_LIMIT],
         "contributors": contrib_board,
         "fundsMainnodes": funds["mainnode"][:LEADERBOARD_LIMIT],
         "fundsContributors": funds["contributor"][:LEADERBOARD_LIMIT],
         "fundsProjects": funds["project"][:LEADERBOARD_LIMIT],
         "fundsState": "historical-reporting-aggregate",
         "fundsCustody": "no-wallet-custody",
         "fundsNotice": (
             "These are reporting aggregates, not wallet balances or proof of "
             "payment. ForkMesh holds no recipient key or funds; only a "
             "finalized public transaction signature establishes a completed "
             "on-chain transfer."
         )},
        cache_seconds=NETWORK_STATS_TTL,
    )
    await edge_cache_put(NETWORK_LEADERBOARDS_CACHE_KEY, resp)
    return resp


def _short_wallet(addr):
    addr = (addr or "").strip()
    if len(addr) <= 10:
        return addr or "node"
    return addr[:4] + "…" + addr[-4:]


async def _wallet_name_map(env):
    # Build wallet -> friendly node name from local nodes and federated
    # presence, so funds-received boards can label payout wallets. Best-effort.
    mapping = {}
    try:
        rows = await d1_all(env, "SELECT name, data FROM nodes")
        for row in rows:
            rec = await decrypt_row(env, row.get("data"))
            if not rec:
                continue
            wallet = (rec.get("solana") or "").strip()
            if not wallet:
                continue
            name = clean_string(row.get("name") or rec.get("name", ""), MAX_NODE_NAME)
            if name:
                mapping.setdefault(wallet, name)
    except Exception:
        pass
    try:
        fed = await d1_all(env, "SELECT wallet, name FROM federated_presence")
        for row in fed:
            wallet = (row.get("wallet") or "").strip()
            name = clean_string(row.get("name", ""), MAX_NODE_NAME)
            if wallet and name:
                mapping.setdefault(wallet, name)
    except Exception:
        pass
    return mapping


async def _funds_received_boards(env):
    out = {"mainnode": [], "contributor": [], "project": []}
    try:
        rows = await d1_all(
            env, "SELECT scope, key, name, lamports FROM funds_received "
                 "WHERE lamports > 0")
    except Exception:
        return out
    wallet_names = None
    for row in rows:
        scope = row.get("scope")
        if scope not in out:
            continue
        lamports = int(row.get("lamports") or 0)
        if lamports <= 0:
            continue
        key = row.get("key") or ""
        name = clean_string(row.get("name") or "", 120)
        if scope in ("mainnode", "contributor") and not name:
            if wallet_names is None:
                wallet_names = await _wallet_name_map(env)
            name = wallet_names.get(key) or _short_wallet(key)
        out[scope].append({"name": name or _short_wallet(key),
                           "lamports": lamports, "sol": _amount_sol(lamports)})
    for scope in out:
        out[scope].sort(key=lambda n: (-n["lamports"], n["name"]))
    return out


async def install_source(env):
    await ensure_schema(env)
    now = int(Date.now())
    # Install candidates must be able to serve the flagship over the same
    # direct-HTTPS path the clone will actually use. A control/presence socket
    # says nothing about repository-byte availability, so require a fresh,
    # signed forkmesh/forkmesh proof from a healthy non-abuse-blocked endpoint.
    endpoint_rows = await d1_all(
        env,
        """SELECT node_bi,node_name,checked_at,latency_ms
             FROM mirror_https_endpoints
            WHERE healthy=1 AND integrity='ok' AND abuse_blocked=0
              AND forkmesh_active=1 AND checked_at>=?
              AND forkmesh_verified_at>=?""",
        now - https_routing.ENDPOINT_STALE_MS,
        now - https_routing.ENDPOINT_STALE_MS,
    )
    endpoints = {
        clean_string(row.get("node_name", ""), MAX_NODE_NAME).lower(): row
        for row in endpoint_rows or []
        if valid_node_name(
            clean_string(row.get("node_name", ""), MAX_NODE_NAME).lower())
    }
    rows = await d1_all(
        env,
        "SELECT owner_bi, data FROM repositories",
    )

    candidates = {}
    for row in rows:
        rec = await decrypt_row(env, row.get("data"))
        if (
            not rec
            or rec.get("visibility") != "public"
            or safe_segment(rec.get("name", "")) != "forkmesh"
        ):
            continue
        owner = safe_segment(rec.get("owner", ""))
        owner_bi = row.get("owner_bi")
        endpoint = endpoints.get(owner)
        if not owner or not owner_bi or not endpoint:
            continue
        source_kind = str(rec.get("source") or "local-node").strip()
        try:
            last_sync = int(rec.get("lastSync") or 0)
        except (TypeError, ValueError):
            last_sync = 0
        priority = 2
        if source_kind == "local-node":
            priority = 0 if owner == "forkmesh" else 1
        candidates[owner_bi] = {
            "node": owner,
            "priority": priority,
            "lastSync": last_sync,
            "latencyMs": int(endpoint.get("latency_ms") or 60_000),
        }

    if not candidates:
        return json_response({"ok": False, "error": "no_online_install_source"},
                             status=503,
                             cache_control="no-store, max-age=0, must-revalidate")

    start = now - ONLINE_HISTORY_RETAIN_MS
    uptime_rows = await d1_all(
        env,
        """SELECT node_key, SUM(node_minutes) AS total_minutes
             FROM online_hourly_nodes
             WHERE hour_ts >= ?
             GROUP BY node_key""",
        start,
    )
    totals = {r.get("node_key"): int(r.get("total_minutes") or 0)
              for r in uptime_rows}
    ranked = sorted(
        (
            {**item, "totalMinutes": totals.get(node_key, 0)}
            for node_key, item in candidates.items()
        ),
        key=lambda item: (
            item["priority"], -item["lastSync"],
            item["latencyMs"], -item["totalMinutes"], item["node"]),
    )
    best = ranked[0]
    # Health can change after selection, so hand the installer a bounded
    # failover list. "node" stays for older installers that read one value.
    node_list = [item["node"] for item in ranked[:8]]
    return json_response(
        {"ok": True, "node": best["node"], "nodes": node_list,
         "repo": "forkmesh", "totalMinutes": best["totalMinutes"]},
        cache_control="no-store, max-age=0, must-revalidate",
    )


def method_name(request):
    method = getattr(request, "method", "GET")
    return str(method).upper()


async def durable_object_request(request, target_url=None, include_body=False,
                                 body=None):
    # DurableObject.fetch may outlive the Python call frame. Passing the Python
    # Request proxy directly across that JS boundary can trip Pyodide's
    # "PyProxy when Python GIL not held" crash under load. Rebuild a JS-owned
    # Request from primitive strings/bytes for control/no-body paths, including
    # WebSocket upgrades. Repository payloads do not use Durable Objects.
    headers = {}
    for name in (
        "upgrade", "connection", "sec-websocket-version", "sec-websocket-key",
        "sec-websocket-protocol", "content-type", "content-encoding",
        "authorization", "accept", "user-agent",
    ):
        try:
            value = request.headers.get(name)
        except Exception:
            value = None
        if value:
            headers[name] = value
    init = {"method": method_name(request), "headers": headers}
    if include_body:
        # A caller that buffered the single-use body stream (to replay the
        # request on another node) passes the bytes; otherwise read them here.
        payload = bytes(await request.bytes()) if body is None else bytes(body)
        init["body"] = Uint8Array.new(_to_js(payload))
    return JsRequest.new(str(target_url or request.url), to_js(init))


def world_request_country(request):
    """Trusted coarse country from request.cf, with a local-dev fallback."""
    try:
        cf = getattr(request, "cf", None)
    except Exception:
        cf = None
    if cf is not None:
        raw_country = None
        if isinstance(cf, dict):
            raw_country = cf.get("country")
        else:
            try:
                raw_country = getattr(cf, "country", None)
            except Exception:
                raw_country = None
            if raw_country is None:
                try:
                    raw_country = cf.get("country")
                except Exception:
                    raw_country = None
        if raw_country is not None:
            return world_protocol.approximate_country_code(raw_country)
    # pywrangler/local test requests may not expose request.cf. Cloudflare
    # overwrites CF-IPCountry at the edge when IP Geolocation is enabled.
    try:
        raw_country = request.headers.get("cf-ipcountry") or ""
    except Exception:
        raw_country = ""
    return world_protocol.approximate_country_code(raw_country)


def world_context_handler(request):
    """Return the visitor's coarse country code and the shared world clock.

    This endpoint reads only ``request.cf.country`` (or ``cf-ipcountry`` in
    local/dev environments). It never reads or returns an IP address,
    user-agent, precise location, account, repository, or wallet information.
    """
    if method_name(request) != "GET":
        return json_response(
            {"error": "method_not_allowed"},
            status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "GET"},
        )
    return json_response(
        world_protocol.context_payload(
            world_request_country(request), int(Date.now()), MAX_CONNECTIONS),
        cache_control="no-store, max-age=0, must-revalidate",
        extra_headers={"x-content-type-options": "nosniff"},
    )


def world_websocket_origin_allowed(request):
    """Accept browser WebSockets only from the exact request origin."""
    try:
        origin = (request.headers.get("origin") or "").strip()
    except Exception:
        origin = ""
    if not origin:
        return False
    try:
        request_url = urlparse(request.url)
        origin_url = urlparse(origin)
    except Exception:
        return False
    if origin_url.scheme not in ("http", "https"):
        return False
    if (origin_url.username is not None or origin_url.password is not None
            or origin_url.path not in ("", "/")
            or origin_url.query or origin_url.fragment):
        return False

    def origin_key(parsed):
        host = (parsed.hostname or "").lower().rstrip(".")
        if not host:
            return None
        try:
            port = parsed.port
        except ValueError:
            return None
        if port is None:
            port = 443 if parsed.scheme == "https" else 80
        return parsed.scheme, host, port

    return origin_key(origin_url) == origin_key(request_url)


async def world_durable_object_request(
        request, trusted_claim=None, moderation_tokens=None):
    """Rebuild the world upgrade with no identifying connection headers.

    The general tunnel helper forwards Authorization and User-Agent because Git
    hosts need them. World presence does not. It receives only WebSocket
    handshake headers plus the already-sanitized, approximate country code.
    """
    headers = {}
    for name in (
        "upgrade", "connection", "sec-websocket-version", "sec-websocket-key",
    ):
        try:
            value = request.headers.get(name)
        except Exception:
            value = None
        if value:
            headers[name] = value
    country = world_request_country(request)
    if country:
        # Clients cannot spoof this internal header: the incoming request is
        # rebuilt from the explicit allowlist above.
        headers["x-forkmesh-country"] = country
    claim = trusted_claim if isinstance(trusted_claim, dict) else {}
    if claim:
        # This compact public claim is constructed by this Worker only after a
        # short-lived HMAC ticket has been verified. The incoming request's
        # similarly named headers are deliberately never copied.
        public_claim = world_protocol.trusted_presence_claim(
            claim.get("name", ""), claim.get("accountStatus", "Guest"),
            claim.get("nodeCount", 0))
        private_claim = {
            **public_claim,
            # This flag is verified from the signed, short-lived World ticket.
            # The Durable Object uses it only to tailor moderation handles to
            # an administrator's socket; it is not public presence metadata.
            "isAdmin": claim.get("isAdmin") is True,
        }
        encoded_claim = base64.urlsafe_b64encode(
            json.dumps(private_claim, separators=(",", ":")).encode()
        ).decode().rstrip("=")
        headers["x-forkmesh-world-claim"] = encoded_claim
    tokens = moderation_tokens if isinstance(moderation_tokens, dict) else {}
    for target_type in ("ip", "agent"):
        token = str(tokens.get(target_type) or "")
        if re.fullmatch(r"[a-f0-9]{64}", token):
            # Only keyed opaque tokens cross this boundary. The source address
            # and raw client fingerprint remain in the outer Worker call frame.
            headers["x-forkmesh-world-%s-token" % target_type] = token
    source_url = urlparse(request.url)
    # Strip query/fragment data as an additional privacy boundary. The world
    # protocol has no tokens or user-selected URL state.
    target_url = (
        source_url.scheme + "://" + source_url.netloc + source_url.path)
    return JsRequest.new(
        target_url,
        to_js({"method": "GET", "headers": headers}),
    )


WORLD_TICKET_TTL_MS = 60 * 1000
WORLD_INACTIVE_RETAIN_MS = 30 * 24 * 60 * 60 * 1000
WORLD_MANUAL_BLOCK_MIN_MS = 60 * 1000
WORLD_MANUAL_BLOCK_MAX_MS = 24 * 60 * 60 * 1000
WORLD_MANUAL_BLOCK_DEFAULT_MS = 15 * 60 * 1000
WORLD_MANUAL_BLOCK_RETAIN_MS = 30 * 24 * 60 * 60 * 1000
WORLD_MANUAL_TOKEN_DAY_MS = 24 * 60 * 60 * 1000
# An opted-in seating card represents somebody who has actually been away, not
# somebody who selected "Away" while still walking around the world. A fresh
# authenticated world visit resets this quiet-period clock.
WORLD_INACTIVE_DELAY_MS = 15 * 60 * 1000


def _world_ticket_signature(env, payload):
    return hmac.new(
        _account_session_secret(env),
        b"forkmesh-world-ticket-v1\n" + payload.encode(),
        "sha256",
    ).hexdigest()


def _world_ticket_encode(env, claim):
    payload = base64.urlsafe_b64encode(
        json.dumps(claim, separators=(",", ":"), sort_keys=True).encode()
    ).decode().rstrip("=")
    return payload + "." + _world_ticket_signature(env, payload)


def _world_ticket_decode(env, ticket):
    value = clean_string(ticket or "", 2048).strip()
    if "." not in value:
        return None
    payload, signature = value.rsplit(".", 1)
    if not payload or not re.fullmatch(r"[A-Za-z0-9_-]+", payload):
        return None
    if not hmac.compare_digest(
            signature, _world_ticket_signature(env, payload)):
        return None
    try:
        padded = payload + "=" * ((4 - len(payload) % 4) % 4)
        claim = json.loads(base64.urlsafe_b64decode(padded).decode())
    except Exception:
        return None
    if not isinstance(claim, dict):
        return None
    now = int(Date.now())
    try:
        issued = int(claim.get("issuedAt", 0) or 0)
        expires = int(claim.get("expiresAt", 0) or 0)
    except (TypeError, ValueError):
        return None
    if issued <= 0 or expires <= now or expires - issued > WORLD_TICKET_TTL_MS:
        return None
    if issued > now + 5000:
        return None
    public = world_protocol.trusted_presence_claim(
        claim.get("name", ""), claim.get("accountStatus", "Guest"),
        claim.get("nodeCount", 0))
    if not public["name"] or public["accountStatus"] == "Guest":
        return None
    # `isAdmin` is accepted only from the HMAC-authenticated ticket body. It is
    # never accepted from a browser presence frame.
    public["isAdmin"] = claim.get("isAdmin") is True
    return public


async def _world_account_claim(env, request, data=None):
    """Return a server-derived public world role for a valid user session."""
    account_bi, rec = await _account_session_record(env, request, data)
    if not rec:
        return None
    name = clean_string(rec.get("name", ""), MAX_NODE_NAME).strip().lower()
    if not name:
        return None
    roles = set()
    try:
        now = int(Date.now())
        rows = await d1_all(
            env,
            "SELECT role FROM role_grants WHERE account_bi=? "
            "AND role IN ('supporting_member','mirror_operator',"
            "'organization_administrator','automated_agent') "
            "AND revoked_at=0 AND (expires_at=0 OR expires_at>?)",
            account_bi, now,
        )
        roles = {
            str(row.get("role") or "") for row in (rows or [])
        }
    except Exception:
        roles = set()
    try:
        org_admin = await d1_first(
            env,
            "SELECT 1 AS ok FROM org_members WHERE member_bi=? "
            "AND role IN ('owner','admin') LIMIT 1",
            account_bi,
        )
    except Exception:
        org_admin = None
    node_count = len(_owned_nodes(rec))
    if "automated_agent" in roles or (
            _account_kind(rec) in ("bot", "agent")
            and bool(rec.get("verified"))):
        account_status = "Verified bot"
    elif org_admin or "organization_administrator" in roles:
        account_status = "Organization admin"
    elif node_count or "mirror_operator" in roles:
        account_status = "Mirror operator"
    elif (
        "supporting_member" in roles
        or bool(rec.get("supporting_member"))
        or str(rec.get("account_tier") or "").lower()
            in ("supporter", "supporting", "paid")
    ):
        account_status = "Supporting member"
    elif bool(rec.get("email_verified")):
        account_status = "Registered"
    else:
        # An active but unverified account receives no elevated public badge.
        account_status = "Guest"
    if account_status == "Guest":
        return None
    claim = world_protocol.trusted_presence_claim(
        name, account_status, node_count)
    claim["isAdmin"] = bool(
        await _has_role(env, name, "platform_administrator"))
    return claim


async def world_ticket_handler(env, request):
    if method_name(request) != "GET":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"allow": "GET"})
    claim = await _world_account_claim(env, request)
    if not claim:
        return json_response(
            {
                "ok": True,
                "authenticated": False,
                "accountStatus": "Guest",
                "nodeCount": 0,
                "ticket": "",
            },
            cache_control="no-store, max-age=0, must-revalidate",
        )
    now = int(Date.now())
    # If this account previously opted into the inactive seating area, a fresh
    # authenticated world visit makes that card ineligible immediately. Keep
    # the consent/configuration record so it can reappear after the account has
    # actually been away; do not require the user to opt in on every visit.
    try:
        await ensure_schema(env)
        account_bi = await blind_index(env, claim["name"])
        await d1_run(
            env,
            "UPDATE world_inactive_presence SET updated_at=?, expires_at=? "
            "WHERE account_bi=?",
            now, now + WORLD_INACTIVE_RETAIN_MS, account_bi,
        )
    except Exception:
        # Presence tickets must still work if a rolling deployment has not yet
        # installed the optional inactivity table.
        pass
    ticket_claim = {
        **claim,
        "issuedAt": now,
        "expiresAt": now + WORLD_TICKET_TTL_MS,
    }
    return json_response(
        {
            "ok": True,
            "authenticated": True,
            **claim,
            "expiresAt": ticket_claim["expiresAt"],
            "ticket": _world_ticket_encode(env, ticket_claim),
        },
        cache_control="no-store, max-age=0, must-revalidate",
        extra_headers={"x-content-type-options": "nosniff"},
    )


def _world_inactive_public_id(account_bi):
    return hashlib.sha256(
        ("forkmesh-world-inactive-v1:" + str(account_bi or "")).encode()
    ).hexdigest()[:20]


def _world_inactive_recency(updated_at, now):
    try:
        age = max(0, int(now) - int(updated_at or 0))
    except (TypeError, ValueError):
        age = WORLD_INACTIVE_RETAIN_MS
    if age < 24 * 60 * 60 * 1000:
        return "Last active recently"
    if age < 7 * 24 * 60 * 60 * 1000:
        return "Away this week"
    return "Returning contributor"


async def world_inactive_handler(env, request):
    """Manage the user's optional, generalized Town Square seating card."""
    await ensure_schema(env)
    method = method_name(request)
    now = int(Date.now())
    await d1_run(
        env, "DELETE FROM world_inactive_presence WHERE expires_at<=?", now)
    if method == "GET":
        rows = await d1_all(
            env,
            "SELECT account_bi, data, updated_at FROM world_inactive_presence "
            "WHERE expires_at>? AND updated_at<=? "
            "ORDER BY updated_at DESC LIMIT 64",
            now, now - WORLD_INACTIVE_DELAY_MS,
        )
        people = []
        for row in rows or []:
            try:
                rec = await decrypt_row(env, row.get("data"))
            except Exception:
                rec = None
            if not isinstance(rec, dict):
                continue
            status = str(rec.get("status") or "")
            if status not in world_protocol.WORLD_INACTIVITY_VALUES:
                continue
            claim = world_protocol.trusted_presence_claim(
                rec.get("name", ""), rec.get("accountStatus", "Guest"),
                rec.get("nodeCount", 0))
            people.append({
                "id": _world_inactive_public_id(row.get("account_bi")),
                "name": claim["name"] or "Private contributor",
                "accountStatus": claim["accountStatus"],
                "nodeCount": claim["nodeCount"],
                "availability": status,
                "lastActive": _world_inactive_recency(
                    row.get("updated_at"), now),
            })
        return json_response(
            {
                "ok": True,
                "people": people,
                "retentionDays": 30,
                "visibilityDelayMinutes": (
                    WORLD_INACTIVE_DELAY_MS // (60 * 1000)),
            },
            cache_control="no-store, max-age=0, must-revalidate",
            extra_headers={"x-content-type-options": "nosniff"},
        )
    if method == "DELETE":
        account_bi, rec = await _account_session_record(env, request)
        if not rec:
            return json_response({"error": "invalid_session"}, status=401)
        await d1_run(
            env, "DELETE FROM world_inactive_presence WHERE account_bi=?",
            account_bi)
        return json_response(
            {"ok": True, "visible": False},
            cache_control="no-store, max-age=0, must-revalidate")
    if method != "POST":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            extra_headers={"allow": "GET, POST, DELETE"})
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    account_bi, rec = await _account_session_record(env, request, data)
    if not rec:
        return json_response({"error": "invalid_session"}, status=401)
    selection = world_protocol.sanitize_inactivity_record(data)
    if selection is None:
        # A false/absent consent flag is an explicit removal, never a hidden
        # retained record.
        await d1_run(
            env, "DELETE FROM world_inactive_presence WHERE account_bi=?",
            account_bi)
        return json_response(
            {"ok": True, "visible": False},
            cache_control="no-store, max-age=0, must-revalidate")
    claim = await _world_account_claim(env, request, data)
    if not claim:
        return json_response({"error": "verified_account_required"}, status=403)
    public_rec = {
        "name": claim["name"] if selection["shareName"]
                else "Private contributor",
        "status": selection["status"],
        "accountStatus": claim["accountStatus"],
        "nodeCount": claim["nodeCount"] if selection["shareNodes"] else 0,
    }
    encrypted = await encrypt_row(env, public_rec)
    expires = now + WORLD_INACTIVE_RETAIN_MS
    await d1_run(
        env,
        "INSERT INTO world_inactive_presence "
        "(account_bi,data,updated_at,expires_at) VALUES (?,?,?,?) "
        "ON CONFLICT(account_bi) DO UPDATE SET "
        "data=excluded.data,updated_at=excluded.updated_at,"
        "expires_at=excluded.expires_at",
        account_bi, encrypted, now, expires,
    )
    return json_response(
        {
            "ok": True,
            "visible": False,
            "enrolled": True,
            "availability": selection["status"],
            "visibleAfter": now + WORLD_INACTIVE_DELAY_MS,
            "expiresAt": expires,
        },
        cache_control="no-store, max-age=0, must-revalidate",
    )


class _WorldCommunityRuntime:
    """Narrow adapter from isolated world APIs to established Worker helpers."""

    def __init__(self, env, request=None):
        self.env = env
        self.request = request

    def method(self):
        return method_name(self.request) if self.request is not None else "GET"

    def now(self):
        return int(Date.now())

    def new_id(self):
        # The random id contains no account, address, time, path, or provider
        # information and is safe to use as the public resource identifier.
        return _ap_uuid()

    def instance_id(self):
        """Stable public instance identifier with no account/device material."""
        base = str(getattr(self.env, "PUBLIC_BASE_URL", "") or "").strip()
        try:
            host = str(urlparse(base).hostname or "").strip().lower()
        except Exception:
            host = ""
        if host:
            return host[:253]
        label = clean_string(
            getattr(self.env, "NODE_NAME", "") or "", MAX_NODE_NAME
        ).strip().lower()
        return label or "forkmesh.com"

    def public_origin(self):
        if self.request is not None:
            return _ap_origin(self.env, self.request)
        configured = str(
            getattr(self.env, "PUBLIC_BASE_URL", "") or ""
        ).strip().rstrip("/")
        return configured or "https://forkmesh.com"

    def query_params(self):
        if self.request is None:
            return {}
        values = parse_qs(urlparse(self.request.url).query)
        return {
            str(key): str(items[0])
            for key, items in values.items()
            if isinstance(items, list) and items
        }

    def response(self, data, status=200, cache_control=None,
                 extra_headers=None):
        return json_response(
            data,
            status=status,
            cache_control=cache_control,
            extra_headers=extra_headers,
        )

    async def ensure_schema(self):
        await ensure_schema(self.env)

    async def json_body(self, limit):
        """Read one bounded JSON object; an empty mutation body becomes {}."""
        if self.request is None:
            return None, "invalid_json"
        try:
            raw_length = self.request.headers.get("content-length") or ""
            if raw_length and int(raw_length) > int(limit):
                return None, "payload_too_large"
        except (TypeError, ValueError):
            return None, "invalid_content_length"
        try:
            raw = await self.request.text()
        except Exception:
            return None, "invalid_json"
        if len(str(raw or "").encode("utf-8")) > int(limit):
            return None, "payload_too_large"
        if not str(raw or "").strip():
            return {}, ""
        try:
            data = json.loads(raw)
        except Exception:
            return None, "invalid_json"
        return (data, "") if isinstance(data, dict) else (None, "invalid_json")

    async def session(self, data=None):
        return await _account_session_record(
            self.env, self.request, data if isinstance(data, dict) else {})

    async def is_admin(self, name):
        return await _is_admin(self.env, name)

    async def account(self, name):
        name = clean_string(name or "", MAX_NODE_NAME).strip().lower()
        if not valid_node_name(name):
            return "", ""
        account_bi, rec = await _account_row(self.env, name)
        if (
            not rec
            or rec.get("status") != "active"
            or _account_kind(rec) != "user"
        ):
            return "", ""
        return account_bi, clean_string(
            rec.get("name") or name, MAX_NODE_NAME).strip().lower()

    async def blind(self, value):
        return await blind_index(self.env, str(value or ""))

    async def seal(self, value):
        return await encrypt_row(self.env, value)

    async def open(self, value):
        return await decrypt_row(self.env, value)

    async def repository_access(self, owner, repo, _actor):
        # Named public repository reads are available to signed-in workshop
        # participants. Private/missing names fail closed and require the same
        # owner-session authorization as every other named owner surface.
        _repo_bi, row = await _security_scan_repository_row(
            self.env, owner, repo)
        if not row:
            return False
        if not await _repo_is_private(self.env, owner, repo):
            return True
        ok, _response = await _authorize_owner_account(
            self.env, owner, {}, self.request, allow_admin=False)
        return bool(ok)

    async def authorize_repository_owner(self, owner, data=None):
        account_bi, rec = await _account_session_record(
            self.env,
            self.request,
            data if isinstance(data, dict) else {},
        )
        actor = clean_string(
            (rec or {}).get("name") or "", MAX_NODE_NAME
        ).strip().lower()
        if (
            not account_bi
            or not actor
            or not await _account_owns_node(self.env, actor, owner)
        ):
            return "", ""
        return account_bi, actor

    async def authorize_owner_node(self, owner):
        return bool(
            self.request is not None
            and await _authorize_owner(self.env, self.request, owner)
        )

    async def enqueue_issue(
        self, owner, repo, title, body, requester, mention_id, remote_url
    ):
        provenance = (
            "\n\nReviewed public fediverse source: " + str(remote_url)
            if remote_url else ""
        )
        return await _forkbot_enqueue_issue(
            self.env,
            owner,
            repo,
            title,
            str(body).rstrip() + provenance,
            requester,
            source="fediverse-review",
            labels=["fediverse", "manually-reviewed"],
            federated_mention_id=mention_id,
            federated_remote_url=remote_url,
        )

    async def publish_followup(self, mention_id, record, message, number):
        remote = {
            "actor_id": record.get("actorUrl", ""),
            "url": record.get("actorUrl", ""),
            "handle": record.get("author", ""),
            "inbox": record.get("inbox", ""),
            "shared_inbox": record.get("sharedInbox", ""),
        }
        note = {
            "id": record.get("remoteId", ""),
            "url": record.get("remoteUrl", ""),
        }
        return bool(await _ap_send_mention_reply(
            self.env,
            self.request,
            record.get("actorOwner", ""),
            record.get("repo", ""),
            remote,
            note,
            message,
            number,
            dedupe_id=mention_id,
            object_uuid=mention_id,
        ))

    async def audit(self, actor, action, target_type="", target="",
                    outcome="success", details=None):
        await _audit_sensitive_action(
            self.env,
            actor,
            action,
            target_type,
            target,
            outcome=outcome,
            details=details,
        )

    async def d1_all(self, sql, *args):
        return await d1_all(self.env, sql, *args)

    async def d1_first(self, sql, *args):
        return await d1_first(self.env, sql, *args)

    async def d1_run(self, sql, *args):
        return await d1_run(self.env, sql, *args)


