def _outreach_from(env):
    email = (getattr(env, "OUTREACH_SENDER", "") or OUTREACH_FROM_EMAIL).strip()
    name = (getattr(env, "OUTREACH_SENDER_NAME", "") or OUTREACH_FROM_NAME).strip()
    return email, name


async def _outreach_member(env, name):
    name = (name or "").strip().lower()
    if not name:
        return False
    name_bi = await blind_index(env, name)
    row = await d1_first(
        env, "SELECT name FROM outreach_team WHERE name_bi=?", name_bi)
    return bool(row)


async def _outreach_enabled(env, name):
    # Per-user access flag (users.enable_outreach), the operator-settable
    # sibling of is_admin. Grant it directly in the DB to give a user the
    # /outreach console without a roster row: UPDATE users SET
    # enable_outreach=1 WHERE username='<user>'.
    name = (name or "").strip().lower()
    if not name:
        return False
    name_bi = await blind_index(env, name)
    try:
        row = await d1_first(
            env, "SELECT enable_outreach FROM users WHERE user_bi=?", name_bi)
    except Exception:
        return False  # column may predate migration 0040
    return bool(row and int(row.get("enable_outreach", 0) or 0))


async def _outreach_team_list(env):
    rows = await d1_all(
        env, "SELECT name, added_by, added_at FROM outreach_team ORDER BY added_at")
    return [{"name": str(r.get("name", "") or ""),
             "addedBy": str(r.get("added_by", "") or ""),
             "addedAt": int(r.get("added_at", 0) or 0)}
            for r in (rows or [])]


async def _outreach_sent_today(env, sender):
    day_ago = int(Date.now()) - 24 * 60 * 60 * 1000
    row = await d1_first(
        env, "SELECT COUNT(*) AS n FROM outreach_log WHERE sender=? AND ts>=?",
        sender, day_ago)
    return int((row or {}).get("n", 0) or 0)


async def _outreach_access(env, name, is_admin, allowed):
    from_email, from_name = _outreach_from(env)
    payload = {
        "ok": True, "name": name, "isAdmin": is_admin, "allowed": allowed,
        "fromEmail": from_email, "fromName": from_name,
        "dailyLimit": OUTREACH_DAILY_LIMIT,
        "configured": bool((getattr(env, "MAILTRAP_API_TOKEN", "") or "").strip()),
    }
    if not allowed:
        # Non-members learn only that they lack access — not the templates,
        # roster, or send history.
        return json_response(payload)
    payload["templates"] = OUTREACH_TEMPLATES
    payload["sentToday"] = await _outreach_sent_today(env, name)
    rows = await d1_all(
        env, "SELECT ts, sender, ok, data FROM outreach_log "
             "ORDER BY ts DESC LIMIT ?", OUTREACH_LOG_LIST_LIMIT)
    recent = []
    for r in (rows or []):
        rec = await decrypt_row(env, r.get("data")) or {}
        recent.append({
            "ts": int(r.get("ts", 0) or 0),
            "sender": str(r.get("sender", "") or ""),
            "ok": bool(int(r.get("ok", 0) or 0)),
            "to": rec.get("to", ""),
            "subject": rec.get("subject", ""),
            "template": rec.get("template", ""),
        })
    payload["recent"] = recent
    if is_admin:
        payload["members"] = await _outreach_team_list(env)
    return json_response(payload)


async def _outreach_send(env, sender, data):
    to_email = clean_string(data.get("to", ""), 254).strip().lower()
    subject = clean_string(data.get("subject", ""), OUTREACH_MAX_SUBJECT).strip()
    body = str(data.get("body", "") or "")[:OUTREACH_MAX_BODY].strip()
    template = clean_string(data.get("template", ""), 40).strip()
    if "@" not in to_email or len(to_email) < 3:
        return json_response({"error": "valid_email_required"}, status=400)
    if not subject:
        return json_response({"error": "subject_required"}, status=400)
    if not body:
        return json_response({"error": "body_required"}, status=400)
    sent_today = await _outreach_sent_today(env, sender)
    if sent_today >= OUTREACH_DAILY_LIMIT:
        return json_response(
            {"error": "daily_limit_reached", "dailyLimit": OUTREACH_DAILY_LIMIT},
            status=429)
    from_email, from_name = _outreach_from(env)
    ok = await _send_email(env, to_email, subject, body,
                           from_email=from_email, from_name=from_name)
    blob = await encrypt_row(env, {
        "sender": sender, "to": to_email, "subject": subject,
        "template": template, "ok": bool(ok)})
    await d1_run(
        env, "INSERT INTO outreach_log (ts, sender, ok, data) VALUES (?,?,?,?)",
        int(Date.now()), sender, 1 if ok else 0, blob)
    if not ok:
        return json_response(
            {"error": "send_failed",
             "detail": "The email provider rejected the send (or "
                       "MAILTRAP_API_TOKEN is not configured)."},
            status=502)
    return json_response({"ok": True, "to": to_email, "from": from_email,
                          "sentToday": sent_today + 1,
                          "dailyLimit": OUTREACH_DAILY_LIMIT})


async def _outreach_team_update(env, admin, data):
    action = clean_string(data.get("action", ""), 16).strip().lower()
    target = clean_string(data.get("name", ""), MAX_NODE_NAME).strip().lower()
    if action not in ("add", "remove"):
        return json_response({"error": "invalid_action"}, status=400)
    if not valid_node_name(target):
        return json_response({"error": "invalid_account_name"}, status=400)
    target_bi, rec = await _account_row(env, target)
    audit_action = (
        "admin.outreach_team_grant"
        if action == "add" else "admin.outreach_team_revoke")
    if action == "add" and (not rec or rec.get("status") != "active"):
        await _audit_sensitive_action(
            env, admin, audit_action, "account", target, "denied",
            {"reason": "no_such_account"})
        return json_response({"error": "no_such_account"}, status=404)
    try:
        if action == "add":
            await d1_run(
                env,
                "INSERT INTO outreach_team (name_bi, name, added_by, added_at) "
                "VALUES (?,?,?,?) ON CONFLICT(name_bi) DO NOTHING",
                target_bi, rec.get("name", target), admin, int(Date.now()))
        else:
            await d1_run(
                env, "DELETE FROM outreach_team WHERE name_bi=?", target_bi)
    except Exception:
        await _audit_sensitive_action(
            env, admin, audit_action, "account", target, "failed",
            {"reason": "mutation_error"})
        raise
    await _audit_sensitive_action(
        env, admin, audit_action, "account", target, "success")
    return json_response({"ok": True, "members": await _outreach_team_list(env)})


async def outreach_handler(env, request):
    await ensure_schema(env)
    url = urlparse(request.url)
    method = method_name(request)
    path = url.path.rstrip("/") or url.path
    data = None
    if method == "POST":
        try:
            data = await request.json()
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        if not isinstance(data, dict):
            return json_response({"error": "invalid_json"}, status=400)
    # Every outreach route needs a logged-in account session (bearer token or
    # sessionToken in the POST body); membership/admin gates layer on top.
    _, rec = await _account_session_record(env, request, data)
    if not rec:
        return json_response({"error": "unauthorized"}, status=401)
    name = (rec.get("name", "") or "").strip().lower()
    is_admin = await _is_admin(env, name)
    allowed = (is_admin or await _outreach_member(env, name)
               or await _outreach_enabled(env, name))
    if path == "/api/outreach" and method in ("GET", "POST"):
        return await _outreach_access(env, name, is_admin, allowed)
    if path == "/api/outreach/send" and method == "POST":
        if not allowed:
            return json_response({"error": "forbidden"}, status=403)
        return await _outreach_send(env, name, data)
    if path == "/api/outreach/team" and method == "POST":
        if not is_admin:
            requested_action = str(data.get("action") or "").strip().lower()
            audit_action = (
                "admin.outreach_team_grant"
                if requested_action == "add"
                else "admin.outreach_team_revoke"
                if requested_action == "remove"
                else "admin.outreach_team_change")
            audit_target = clean_string(
                data.get("name", ""), MAX_NODE_NAME).strip().lower()
            await _audit_sensitive_action(
                env, name, audit_action, "account", audit_target, "denied",
                {"reason": "admin_required"})
            return json_response({"error": "admin_required"}, status=403)
        return await _outreach_team_update(env, name, data)
    return json_response({"error": "not_found"}, status=404)


# Step 1 of a password reset: a user who forgot their password gives their email
# (or node name); if it matches an active account with an email on file we send a
# time-bound reset link. Always returns {ok:true} — never revealing whether the
# identifier matched an account — so the endpoint can't be used to enumerate
# which emails/nodes are registered.
async def _account_forgot_password(env, request):
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    identifier = clean_string(
        data.get("identifier", "") or data.get("email", "") or
        data.get("nodeName", ""), 254).strip().lower()
    if identifier:
        rec = None
        if "@" in identifier:
            email_bi = await blind_index(env, identifier)
            row = await d1_first(
                env, "SELECT data FROM users WHERE email_bi=?", email_bi)
            if row:
                rec = await decrypt_row(env, row.get("data"))
        elif valid_node_name(identifier):
            _, rec = await _account_row(env, identifier)
        if (rec and rec.get("status") == "active" and rec.get("email") and
                rec.get("pass_hash")):
            await _send_password_reset_email(
                env, request, rec.get("name", ""), rec.get("email", ""),
                rec.get("pass_hash", ""))
    return json_response({"ok": True})


# Step 2 of a password reset: the emailed link posts back the node name, expiry,
# token and a new password. The token is recomputed from the account's current
# pass_hash + the expiry, so a stale/used/tampered link fails, and the new
# password is PBKDF2-hashed and stored.
async def _account_reset_password(env, request):
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    name = clean_string(
        data.get("node", "") or data.get("nodeName", ""), MAX_NODE_NAME).lower()
    token = clean_string(data.get("token", ""), 64)
    password = (data.get("password", "") or "")[:256]
    try:
        expires = int(data.get("exp", 0))
    except (TypeError, ValueError):
        expires = 0
    if len(password) < 8:
        return json_response({"error": "password_too_short"}, status=400)
    if not name or not token or not expires:
        return json_response({"error": "invalid_reset_token"}, status=400)
    if int(Date.now()) > expires:
        return json_response({"error": "reset_link_expired"}, status=400)
    name_bi, rec = await _account_row(env, name)
    if (not rec or rec.get("status") != "active" or not rec.get("email") or
            not rec.get("pass_hash")):
        return json_response({"error": "invalid_reset_token"}, status=400)
    expected = await _password_reset_token(
        env, name, rec.get("email", ""), rec.get("pass_hash", ""), expires)
    if not hmac.compare_digest(token, expected):
        return json_response({"error": "invalid_reset_token"}, status=400)
    salt, phash = await hash_password(password)
    rec["pass_salt"] = salt
    rec["pass_hash"] = phash
    await _save_account(env, name_bi, rec)
    # A successful reset also lifts any brute-force lockout so the user can log in
    # right away, whether they log in by node name or by email.
    await _login_clear(env, name_bi)
    if rec.get("email"):
        await _login_clear(env, await blind_index(env, rec.get("email", "")))
    return json_response({"ok": True})


def _verify_email_page(message, status):
    # color-scheme: light dark lets the browser render its default light or
    # dark canvas to match the visitor's OS preference (no site CSS needed on
    # this one-line confirmation page).
    body = ("<!doctype html><meta charset=utf-8>"
            "<meta name=\"color-scheme\" content=\"light dark\">"
            "<script src=\"/posthog.js\"></script>"
            "<title>ForkMesh email</title>"
            "<body style=\"font-family:system-ui,sans-serif;max-width:32rem;"
            "margin:4rem auto;padding:0 1rem;line-height:1.5\">" + message +
            "</body>")
    return Response(body, status=status,
                    headers={"content-type": "text/html; charset=utf-8"})


async def _verify_email(env, request):
    params = parse_qs(urlparse(request.url).query)
    name = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    token = clean_string(params.get("token", [""])[0], 64)
    name_bi, rec = await _account_row(env, name)
    if rec and rec.get("email") and token:
        expected = await _email_verify_token(env, name, rec.get("email", ""))
        if hmac.compare_digest(token, expected):
            if not rec.get("email_verified"):
                rec["email_verified"] = True
                await _save_account(env, name_bi, rec)
                await d1_run(
                    env, "DELETE FROM pending_verifications WHERE name_bi=?", name_bi)
            return _verify_email_page(
                "<h1>Email confirmed</h1><p>Your ForkMesh email is verified. "
                "You can close this tab and <a href=\"/login\">log in</a>.</p>",
                200)
    return _verify_email_page(
        "<h1>Verification link invalid</h1><p>This confirmation link is invalid "
        "or has expired. Try logging in; if your email still shows unverified, "
        "sign up again.</p>", 400)


# --- Relay federation -------------------------------------------------------
# Relays exchange signed presence/availability metadata. Historical donation
# proxy endpoints are hard-frozen and require offline custody migration; no
# relay-to-relay request creates a wallet, moves funds, or exposes a seed.

FEDERATION_CANON = "forkmesh-federation-v1"
FEDERATION_NODES_MAX_BYTES = 2 * 1024 * 1024
FEDERATED_HEALTH_MESSAGE_MAX_BYTES = 2048
WORLD_RELAY_HEALTH_FRESH_MS = 10 * 60 * 1000


def _main_relay_url(env):
    return (getattr(env, "MAIN_RELAY_URL", "") or "").strip().rstrip("/")


def _is_main_relay(env):
    return not _main_relay_url(env)


async def _new_ed25519_identity():
    # Fresh Ed25519 keypair as (raw pubkey base64url, seed base64url) — the same
    # base64url-raw shape the desktop identity and ed25519_verify use.
    pair = await js_crypto.subtle.generateKey(
        to_js({"name": "Ed25519"}), True, _to_js(["sign", "verify"]))
    pub_raw = await js_crypto.subtle.exportKey("raw", pair.publicKey)
    pub = bytes(Uint8Array.new(pub_raw).to_py())
    jwk = await js_crypto.subtle.exportKey("jwk", pair.privateKey)
    seed = str(getattr(jwk, "d", "") or "")
    if len(pub) != 32 or not seed:
        return None
    return {"pubkey": _b64url_encode(pub), "seed": seed}


async def ed25519_sign(pubkey_b64url, seed_b64url, data_bytes):
    # Sign relay-federation metadata with the relay's non-wallet identity key.
    # This key cannot authorize a Solana transaction and is domain-separated
    # from every wallet/reward flow.
    try:
        jwk = {"kty": "OKP", "crv": "Ed25519", "x": pubkey_b64url,
               "d": seed_b64url, "ext": True, "key_ops": ["sign"]}
        key = await js_crypto.subtle.importKey(
            "jwk", to_js(jwk), to_js({"name": "Ed25519"}), False, _to_js(["sign"]))
        sig = await js_crypto.subtle.sign(
            to_js({"name": "Ed25519"}), key, _to_js(data_bytes))
        return _b64url_encode(bytes(Uint8Array.new(sig).to_py()))
    except Exception:
        return ""


async def _relay_identity(env):
    # This (federated) relay's own signing identity, auto-generated once and kept
    # in D1 so the operator needs no key management — only MAIN_RELAY_URL.
    row = await d1_first(env, "SELECT data FROM relay_self WHERE id=1")
    if row:
        ident = await decrypt_row(env, row.get("data"))
        if ident and ident.get("pubkey") and ident.get("seed"):
            return ident
    ident = await _new_ed25519_identity()
    if not ident:
        return None
    await d1_run(
        env,
        "INSERT INTO relay_self (id, data) VALUES (1, ?) "
        "ON CONFLICT(id) DO UPDATE SET data=excluded.data",
        await encrypt_row(env, ident))
    return ident


def _federation_canonical(pubkey, ts, body_hash):
    return (FEDERATION_CANON + "\n" + pubkey + "\n" + str(ts) + "\n" +
            body_hash).encode()


async def _relay_sign_headers(env, body_str):
    ident = await _relay_identity(env)
    if not ident:
        return None
    ts = str(int(Date.now()))
    body_hash = await sha256_hex(body_str)
    sig = await ed25519_sign(
        ident["pubkey"], ident["seed"],
        _federation_canonical(ident["pubkey"], ts, body_hash))
    if not sig:
        return None
    return {"content-type": "application/json", "X-Relay-Pubkey": ident["pubkey"],
            "X-Relay-Ts": ts, "X-Relay-Sig": sig}


async def _call_main_relay(env, path, body_dict):
    from js import fetch as js_fetch
    base = _main_relay_url(env)
    if not base:
        return None
    body_str = json.dumps(body_dict)
    headers = await _relay_sign_headers(env, body_str)
    if not headers:
        return None

    async def _post(target_path):
        try:
            resp = await js_fetch(base + target_path, to_js(
                {"method": "POST", "headers": headers, "body": body_str}))
            text = await resp.text()
            data = json.loads(text) if text else {}
            if not isinstance(data, dict):
                return None
            data["_status"] = int(getattr(resp, "status", 0))
            return data
        except Exception:
            return None

    # Callers still pass the legacy /api/federation/* names; prefer the
    # canonical /api/relay-mesh/* route and fall back once for a main relay
    # that hasn't been redeployed with the alias yet.
    reply = await _post(path.replace("/api/federation/", "/api/relay-mesh/", 1))
    if reply is None or reply.get("_status") == 404:
        reply = await _post(path)
    return reply


async def _verify_relay_sig(env, request, body_str):
    # Verify a relay->main request's Ed25519 signature (no approval check).
    pubkey = (request.headers.get("x-relay-pubkey") or "").strip()
    ts = (request.headers.get("x-relay-ts") or "").strip()
    sig = (request.headers.get("x-relay-sig") or "").strip()
    if not pubkey or not sig or not _ts_ok(ts):
        return None
    body_hash = await sha256_hex(body_str or "")
    if not await ed25519_verify(
            pubkey, sig, _federation_canonical(pubkey, ts, body_hash)):
        return None
    return pubkey


async def _relay_authorized(env, request, body_str):
    # As _verify_relay_sig, but also require the relay to be approved. Returns the
    # relay's blind index on success, else None.
    pubkey = await _verify_relay_sig(env, request, body_str)
    if not pubkey:
        return None
    relay_bi = await blind_index(env, pubkey)
    row = await d1_first(
        env, "SELECT status FROM relays WHERE relay_bi=?", relay_bi)
    if not row or row.get("status") != "approved":
        return None
    return relay_bi


def _world_relay_public_origin(value):
    """Return one public HTTPS relay origin without credentials or path data."""
    raw = clean_string(value, 300).strip()
    try:
        parsed = urlparse(raw)
    except Exception:
        return ""
    if (
        parsed.scheme.lower() != "https"
        or not parsed.hostname
        or parsed.username
        or parsed.password
        or parsed.query
        or parsed.fragment
    ):
        return ""
    host = parsed.hostname.lower().rstrip(".")
    if not host or host in ("localhost",) or host.endswith(".local"):
        return ""
    try:
        port = parsed.port
    except ValueError:
        return ""
    authority = host if port in (None, 443) else host + ":" + str(port)
    return "https://" + authority


async def world_relay_instances_handler(env, request):
    """Expose approved relay instances and generalized signed-health state.

    This public World projection deliberately omits federation public keys,
    signatures, node/account/wallet identifiers, operator tokens, exact health
    messages, repository identities, and request telemetry.
    """
    if method_name(request) != "GET":
        return json_response(
            {"error": "method_not_allowed"}, status=405,
            cache_control="no-store", extra_headers={"allow": "GET"})
    await ensure_schema(env)
    now = int(Date.now())
    cutoff = now - WORLD_RELAY_HEALTH_FRESH_MS
    rows = await d1_all(
        env,
        "SELECT r.relay_bi,r.label,r.base_url,r.approved_at,"
        "MAX(fp.ts) AS last_seen,"
        "MAX(CASE WHEN fp.checked_at>=? AND fp.forkmesh_verified_at>=? "
        "AND fp.healthy=1 AND fp.forkmesh_active=1 "
        "AND fp.integrity IN ('ok','verified') AND fp.abuse_blocked=0 "
        "THEN 1 ELSE 0 END) AS fresh_verified "
        "FROM relays r LEFT JOIN federated_presence fp "
        "ON fp.relay_bi=r.relay_bi "
        "WHERE r.status='approved' "
        "GROUP BY r.relay_bi,r.label,r.base_url,r.approved_at "
        "ORDER BY r.approved_at ASC,r.relay_bi ASC",
        cutoff, cutoff,
    )
    instances = []
    for row in rows or []:
        origin = _world_relay_public_origin(row.get("base_url"))
        relay_bi = str(row.get("relay_bi") or "")
        if not origin or not relay_bi:
            continue
        last_seen = max(0, int(row.get("last_seen") or 0))
        verified_online = bool(int(row.get("fresh_verified") or 0))
        health = (
            "online"
            if verified_online
            else "offline"
            if last_seen and last_seen < cutoff
            else "awaiting_verified_health"
        )
        instances.append({
            "id": hashlib.sha256(
                ("forkmesh-world-relay-v1\0" + relay_bi).encode()
            ).hexdigest()[:24],
            "label": clean_string(
                row.get("label") or "ForkMesh instance", 80),
            "origin": origin,
            "approved": True,
            "health": health,
            "online": verified_online,
            "healthEvidence": (
                "approved-relay-signed-fresh-node-health"
                if verified_online
                else "no-fresh-verified-node-health"
            ),
        })
    return json_response({
        "ok": True,
        "instances": instances,
        "count": len(instances),
        "observedAt": now,
        "privacy": (
            "Approved public relay origins and generalized health only. "
            "No federation keys, signatures, tokens, wallets, node identities, "
            "IP addresses, private repositories, or exact activity are exposed."
        ),
    }, cache_control="public, max-age=30",
       extra_headers={"x-content-type-options": "nosniff"})


