async def _federated_donation_address(env, request):
    del env, request
    return json_response({
        "error": "legacy_custody_disabled",
        "custody": "self-custodial-only",
        "notice": (
            "ForkMesh signup is free. The legacy federated deposit-wallet "
            "flow is disabled; no Worker creates or retains a wallet key."
        ),
    }, status=410, cache_control="no-store")


async def _federated_donation_status(env, request):
    params = parse_qs(urlparse(request.url).query)
    name = clean_string(params.get("nodeName", [""])[0], MAX_NODE_NAME).lower()
    _, rec = await _account_row(env, name)
    if not rec:
        return json_response({"error": "no_such_account"}, status=404)
    reference = rec.get("fed_reference", "")
    required = int(rec.get("donation_required_lamports", MIN_JOIN_LAMPORTS))
    if not reference:
        return json_response({"error": "no_donation_address"}, status=400)
    reply = await _call_main_relay(
        env, "/api/federation/donation-status", {"reference": reference})
    if not reply or not reply.get("ok"):
        return json_response({
            "ok": True, "paid": bool(rec.get("donation_confirmed")),
            "checking": True,
            "receivedLamports": int(rec.get("donation_received_lamports", 0)),
            "requiredLamports": required,
            "status": "legacy_custody_frozen",
            "custody": "migration-required",
            "notice": (
                "Read-only legacy status: no Worker can sign or move these "
                "funds. The historical record requires the documented offline "
                "custody migration."
            ),
        }, cache_control="no-store")
    received = int(reply.get("receivedLamports", 0))
    paid = bool(reply.get("paid"))
    return json_response({
        "ok": True, "paid": paid, "checking": bool(reply.get("checking")),
        "receivedLamports": received,
        "requiredLamports": int(reply.get("requiredLamports", required)),
        "status": "legacy_custody_frozen",
        "custody": "migration-required",
        "notice": (
            "Read-only legacy status: no Worker can sign or move these funds. "
            "The historical record requires the documented offline custody "
            "migration."
        ),
    }, cache_control="no-store")


# --- Federation cron --------------------------------------------------------

async def _federation_report_nodes(env):
    # Federated relay: forward only evidence this relay independently verified:
    # account-bound registration plus the exact fresh node-signed
    # forkmesh/forkmesh health challenge. A wallet-only presence report is
    # deliberately impossible.
    now = int(Date.now())
    cutoff = now - ACCOUNT_PRESENCE_STALE_MS
    health_cutoff = now - _reward_config(env)["healthFreshMs"]
    rows = await d1_all(
        env,
        "SELECT e.node_bi,e.node_name,e.base_url,e.public_key,"
        "e.registration_sig,e.issued_at,e.checked_at,e.integrity,"
        "e.health_sig,e.health_message,e.forkmesh_verified_at,"
        "e.forkmesh_refs_sha256,e.forkmesh_operations_sha256,"
        "e.abuse_blocked,n.data "
        "FROM mirror_https_endpoints e "
        "JOIN account_presence p ON p.name_bi=e.node_bi "
        "JOIN nodes n ON n.node_bi=e.node_bi "
        "WHERE p.ts>=? AND e.checked_at>=? "
        "AND e.forkmesh_verified_at>=? AND e.healthy=1 "
        "AND e.integrity='ok' AND e.forkmesh_active=1 "
        "AND e.abuse_blocked=0 AND e.health_message<>'' "
        "ORDER BY e.checked_at DESC LIMIT 500",
        cutoff, health_cutoff, health_cutoff,
    )
    nodes = []
    seen = set()
    for r in (rows or []):
        rec = await decrypt_row(env, r.get("data"))
        if not rec or rec.get("status") != "active":
            continue
        wallet = (rec.get("solana") or "").strip()
        if not wallet or not SOLANA_RE.match(wallet) or wallet in seen:
            continue
        seen.add(wallet)
        nodes.append({
            "name": clean_string(
                r.get("node_name") or rec.get("name", ""),
                MAX_NODE_NAME).lower(),
            "operator": clean_string(
                rec.get("owner") or rec.get("name", ""),
                MAX_NODE_NAME).lower(),
            "wallet": wallet,
            "publicKey": str(r.get("public_key") or ""),
            "baseUrl": str(r.get("base_url") or ""),
            "registrationSignature": str(
                r.get("registration_sig") or ""),
            "registrationIssuedAt": int(r.get("issued_at") or 0),
            "healthMessage": str(r.get("health_message") or ""),
            "healthSignature": str(r.get("health_sig") or ""),
            "checkedAt": int(r.get("checked_at") or 0),
            "healthy": True,
            "integrity": "ok",
            "mirrorsForkMesh": True,
            "forkmeshVerifiedAt": int(
                r.get("forkmesh_verified_at") or 0),
            "refsSha256": str(r.get("forkmesh_refs_sha256") or ""),
            "operationsSha256": str(
                r.get("forkmesh_operations_sha256") or ""),
            "requiredOperationsVerified": True,
            "abuseFlagged": False,
        })
    if nodes:
        await _call_main_relay(env, "/api/federation/nodes", {"nodes": nodes})


async def _federation_cron(env):
    if not _is_main_relay(env):
        ident = await _relay_identity(env)
        if ident:
            label = clean_string(getattr(env, "RELAY_LABEL", "") or "", 80)
            base = clean_string(getattr(env, "PUBLIC_BASE_URL", "") or "", 200)
            await _call_main_relay(
                env, "/api/federation/register",
                {"label": label, "baseUrl": base})
            await _federation_report_nodes(env)
        return
    # Main relay only expires stale presence. Legacy federated deposit rows are
    # intentionally untouched: moving their funds requires the offline custody
    # migration and no scheduled Worker path may consume their retained seeds.
    cutoff = int(Date.now()) - ACCOUNT_PRESENCE_STALE_MS
    try:
        await d1_run(env, "DELETE FROM federated_presence WHERE ts < ?", cutoff)
    except Exception:
        pass


# --- Admin: relay allowlist -------------------------------------------------

async def _admin_relays(env, request):
    params = parse_qs(urlparse(request.url).query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    canonical = ("forkmesh-admin-relays-v1\n" + node + "\n" + ts).encode()
    if not await _admin_authorized(env, node, ts, sig, canonical):
        return json_response({"error": "unauthorized"}, status=401)
    rows = await d1_all(
        env, "SELECT pubkey, label, base_url, status, registered_at, approved_at "
        "FROM relays ORDER BY registered_at DESC")
    relays = [{
        "pubkey": r.get("pubkey", ""), "label": r.get("label", ""),
        "baseUrl": r.get("base_url", ""), "status": r.get("status", ""),
        "registeredAt": r.get("registered_at", 0),
        "approvedAt": r.get("approved_at", 0)} for r in (rows or [])]
    return json_response({"ok": True, "relays": relays})


async def _admin_relay_approve(env, request):
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    pubkey = clean_string(data.get("pubkey", ""), 120)
    action = clean_string(data.get("action", ""), 20)
    if action not in ("approve", "block"):
        return json_response({"error": "bad_action"}, status=400)
    canonical = ("forkmesh-admin-relay-approve-v1\n" + node + "\n" + pubkey +
                 "\n" + action + "\n" + ts).encode()
    if not await _admin_authorized(env, node, ts, sig, canonical):
        return json_response({"error": "unauthorized"}, status=401)
    relay_bi = await blind_index(env, pubkey)
    status = "approved" if action == "approve" else "blocked"
    now = int(Date.now())
    res = await d1_run(
        env, "UPDATE relays SET status=?, approved_at=? WHERE relay_bi=?",
        status, now if action == "approve" else None, relay_bi)
    await _audit_sensitive_action(
        env, node, "admin.relay_" + action, "relay", pubkey, "success",
        {"status": status})
    return json_response({"ok": True, "status": status})


# --- Admin: node ownership takeover (adhoc #141) -----------------------------
# An admin can request to take ownership of any node. The request only parks a
# pending marker on the target node's own record; it does NOT transfer
# ownership by itself. The marker rides back to that node on its own signed
# heartbeat (same channel as a website claim code), the desktop app pops a
# confirm/deny prompt, and only a signature from the node's own key — i.e. the
# node the current owner is actually logged into — can approve or deny it.

async def _park_ownership_transfer(env, target, new_owner):
    # Shared core of every ownership-takeover trigger (signed node request or
    # the operator console): validate the target is a claimable node and park
    # the pending marker. Returns (ok, message_or_result_dict).
    if not valid_node_name(target):
        return False, "invalid_node_id"
    if target == new_owner:
        return False, "cannot_request_self"
    target_bi, target_rec = await _account_row(env, target)
    if not target_rec or target_rec.get("status") != "active":
        return False, "no_such_node"
    if _account_kind(target_rec) != "node":
        # An account that can log in is a user in its own right, not takeable.
        return False, "not_a_node"
    if target_rec.get("owner") == new_owner:
        return True, {"alreadyOwned": True, "nodeId": target}
    now = int(Date.now())
    target_rec["ownership_transfer_pending"] = {
        "admin": new_owner,
        "requestedAt": now,
        "expires": now + OWNERSHIP_TRANSFER_TTL_MS,
    }
    await _save_account(env, target_bi, target_rec)
    return True, {"pending": True, "nodeId": target,
                 "expiresAt": now + OWNERSHIP_TRANSFER_TTL_MS}


async def _admin_request_ownership(env, request):
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
    target = clean_string(data.get("target", ""), MAX_NODE_NAME).lower()
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    canonical = ("forkmesh-admin-request-ownership-v1\n" + node + "\n" +
                 target + "\n" + ts).encode()
    admin_rec = await _admin_authorized(env, node, ts, sig, canonical)
    if not admin_rec:
        return json_response({"error": "unauthorized"}, status=401)
    admin_name = admin_rec.get("name", node)
    ok, result = await _park_ownership_transfer(env, target, admin_name)
    if not ok:
        status = 404 if result == "no_such_node" else (
            403 if result == "not_a_node" else 400)
        return json_response({"error": result}, status=status)
    audit = globals().get("_audit_sensitive_action")
    if callable(audit):
        await audit(
            env, node, "admin.ownership_request", "account", target,
            "requested", {"pending": bool(result.get("pending"))})
    return json_response(dict({"ok": True}, **result),
                         status=201 if result.get("pending") else 200)


async def _account_ownership_transfer_confirm(env, request):
    # Called from the target node's own desktop app in response to the
    # heartbeat-delivered prompt, signed with the node's own key — the same
    # proof-of-control the node uses for its heartbeat, not the admin's.
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node_name = clean_string(data.get("nodeName", ""), MAX_NODE_NAME).lower()
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    action = clean_string(data.get("action", ""), 20)
    if action not in ("approve", "deny"):
        return json_response({"error": "bad_action"}, status=400)
    if not valid_node_name(node_name):
        return json_response({"error": "invalid_node_id"}, status=400)
    node_bi, node_rec = await _account_row(env, node_name)
    if not node_rec or node_rec.get("status") != "active":
        return json_response({"error": "no_such_node"}, status=404)
    pubkey = node_rec.get("pubkey", "")
    if not pubkey or not _ts_ok(ts):
        return json_response({"error": "unauthorized"}, status=401)
    canonical = ("forkmesh-ownership-transfer-confirm-v1\n" + node_name +
                 "\n" + action + "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)
    pending = _transfer_pending(node_rec, int(Date.now()))
    if not pending:
        return json_response({"error": "no_pending_transfer"}, status=404)
    if action == "deny":
        node_rec.pop("ownership_transfer_pending", None)
        await _save_account(env, node_bi, node_rec)
        audit = globals().get("_audit_sensitive_action")
        if callable(audit):
            await audit(
                env, node_name, "ownership_transfer.deny", "account",
                node_name, "success", {})
        return json_response({"ok": True, "denied": True, "nodeId": node_name})
    admin_name = pending.get("admin", "")
    node_rec.pop("ownership_transfer_pending", None)
    await _link_node_to_user(env, node_name, node_bi, node_rec, admin_name)
    audit = globals().get("_audit_sensitive_action")
    if callable(audit):
        await audit(
            env, node_name, "ownership_transfer.approve", "account",
            node_name, "success", {})
    return json_response({"ok": True, "linked": True, "nodeId": node_name,
                          "owner": admin_name})


def _ssh_gateway_settings(env):
    """Return publishable gateway settings only for an operable deployment."""
    host = ssh_auth.configured_gateway_host(
        getattr(env, "SSH_GATEWAY_HOST", ""))
    token = ssh_auth.configured_gateway_token(
        getattr(env, "SSH_GATEWAY_TOKEN", ""))
    repositories = ssh_auth.parse_gateway_repository_allowlist(
        getattr(env, "SSH_GATEWAY_REPOSITORIES", ""))
    try:
        port = int(getattr(env, "SSH_GATEWAY_PORT", 22) or 22)
    except (TypeError, ValueError):
        port = 0
    configured = bool(host and 1 <= port <= 65535 and token and repositories)
    return {
        "configured": configured,
        "host": host if configured else "",
        "port": port if configured else 0,
        "repositories": repositories if configured else {},
    }


def _ssh_gateway_repository_access(env, owner, repo):
    settings = _ssh_gateway_settings(env)
    if not settings["configured"]:
        return ""
    return ssh_auth.gateway_repository_access(
        settings["repositories"], owner, repo)


def _ssh_repository_url(env, owner, repo):
    settings = _ssh_gateway_settings(env)
    if (
        not settings["configured"]
        or not ssh_auth.gateway_repository_access(
            settings["repositories"], owner, repo)
    ):
        return ""
    return ssh_auth.ssh_repository_url(
        settings["host"], settings["port"], owner, repo)


async def _ssh_json_body(request, max_bytes=32 * 1024):
    try:
        announced = int(request.headers.get("content-length") or 0)
    except (TypeError, ValueError):
        return None, "invalid_content_length"
    if announced < 0 or announced > max_bytes:
        return None, "payload_too_large"
    try:
        raw = await request.text()
    except Exception:
        return None, "invalid_json"
    if len(str(raw or "").encode("utf-8")) > max_bytes:
        return None, "payload_too_large"
    try:
        data = json.loads(raw)
    except Exception:
        return None, "invalid_json"
    if not isinstance(data, dict):
        return None, "invalid_json"
    return data, ""


def _ssh_key_public_projection(row, data=None):
    source = data if isinstance(data, dict) else {}
    return {
        "id": str(row.get("key_id") or ""),
        "label": clean_string(source.get("label", ""), ssh_auth.MAX_KEY_LABEL),
        "keyType": str(row.get("key_type") or ""),
        "fingerprint": str(row.get("fingerprint") or ""),
        "createdAt": int(row.get("created_at") or 0),
        "lastUsedAt": int(row.get("last_used_at") or 0),
    }


async def ssh_keys_handler(env, request, key_id=""):
    """Register, list, and revoke the signed-in user's SSH public keys."""
    await ensure_schema(env)
    method = method_name(request)
    data = {}
    if method == "POST":
        data, error = await _ssh_json_body(request)
        if error:
            return json_response({"error": error}, status=413 if (
                error == "payload_too_large") else 400)
    account_bi, account_rec = await _account_session_record(
        env, request, data)
    account = clean_string(
        (account_rec or {}).get("name", ""), MAX_NODE_NAME).lower()
    if (
        not account_bi
        or not account
        or _account_kind(account_rec) != "user"
    ):
        return json_response(
            {"error": "invalid_session"}, status=401,
            cache_control="no-store")

    if method == "GET" and not key_id:
        rows = await d1_all(
            env,
            "SELECT key_id,key_type,fingerprint,data,created_at,last_used_at "
            "FROM account_ssh_keys WHERE account_bi=? AND revoked_at=0 "
            "ORDER BY created_at DESC",
            account_bi,
        )
        keys = []
        for row in rows or []:
            try:
                key_data = await decrypt_row(env, row.get("data"))
            except Exception:
                key_data = None
            if not isinstance(key_data, dict):
                continue
            keys.append(_ssh_key_public_projection(row, key_data))
        gateway = _ssh_gateway_settings(env)
        return json_response({
            "ok": True,
            "keys": keys,
            "maximumKeys": ssh_auth.MAX_KEYS_PER_ACCOUNT,
            "gatewayConfigured": gateway["configured"],
            "gatewayHost": gateway["host"],
            "gatewayPort": gateway["port"],
            "privateKeysStored": False,
            "notice": (
                "ForkMesh stores encrypted public keys only. Keep every SSH "
                "private key and passphrase on your own device."
            ),
        }, cache_control="no-store")

    if method == "POST" and not key_id:
        try:
            parsed = ssh_auth.parse_public_key(data.get("publicKey", ""))
        except ssh_auth.SshPublicKeyError as error:
            return json_response({"error": str(error)}, status=400)
        label = ssh_auth.clean_key_label(
            data.get("label", ""), parsed.get("comment", ""))
        key_bi = await blind_index(
            env, "ssh-public-key:" + parsed["publicKey"])
        existing = await d1_first(
            env,
            "SELECT account_bi,revoked_at FROM account_ssh_keys "
            "WHERE key_bi=?",
            key_bi,
        )
        if existing:
            # Do not disclose whether another account owns the same key or
            # whether it was revoked; either case requires a fresh keypair.
            return json_response(
                {"error": "ssh_key_already_registered"}, status=409,
                cache_control="no-store")
        count = await d1_first(
            env,
            "SELECT COUNT(*) AS n FROM account_ssh_keys "
            "WHERE account_bi=? AND revoked_at=0",
            account_bi,
        )
        if int((count or {}).get("n") or 0) >= ssh_auth.MAX_KEYS_PER_ACCOUNT:
            return json_response(
                {"error": "ssh_key_limit_reached"}, status=429,
                cache_control="no-store")
        key_id = "sk_" + _b64url_encode(_random_bytes(18))
        now = int(Date.now())
        encrypted = await encrypt_row(env, {
            "keyId": key_id,
            "account": account,
            "publicKey": parsed["publicKey"],
            "label": label,
            "createdAt": now,
        })
        try:
            await d1_run(
                env,
                "INSERT INTO account_ssh_keys "
                "(key_id,account_bi,key_bi,key_type,fingerprint,data,"
                "created_at,last_used_at,revoked_at) "
                "VALUES (?,?,?,?,?,?,?,0,0)",
                key_id, account_bi, key_bi, parsed["keyType"],
                parsed["fingerprint"], encrypted, now,
            )
        except Exception:
            await _audit_sensitive_action(
                env, account, "ssh_key.register", "ssh_public_key",
                key_id, "failed", {"reason": "storage_error"})
            raise
        await _audit_sensitive_action(
            env, account, "ssh_key.register", "ssh_public_key",
            key_id, "success", {"keyType": parsed["keyType"]})
        return json_response({
            "ok": True,
            "key": {
                "id": key_id,
                "label": label,
                "keyType": parsed["keyType"],
                "fingerprint": parsed["fingerprint"],
                "createdAt": now,
                "lastUsedAt": 0,
            },
            "privateKeysStored": False,
        }, status=201, cache_control="no-store")

    if method == "DELETE" and key_id:
        key_id = clean_string(key_id, 96)
        if not re.fullmatch(r"sk_[A-Za-z0-9_-]{16,80}", key_id):
            return json_response({"error": "not_found"}, status=404)
        row = await d1_first(
            env,
            "SELECT key_id FROM account_ssh_keys "
            "WHERE key_id=? AND account_bi=? AND revoked_at=0",
            key_id, account_bi,
        )
        if not row:
            return json_response({"error": "not_found"}, status=404)
        now = int(Date.now())
        try:
            await d1_run(
                env,
                "UPDATE account_ssh_keys SET revoked_at=? "
                "WHERE key_id=? AND account_bi=? AND revoked_at=0",
                now, key_id, account_bi,
            )
        except Exception:
            await _audit_sensitive_action(
                env, account, "ssh_key.revoke", "ssh_public_key",
                key_id, "failed", {"reason": "storage_error"})
            raise
        await _audit_sensitive_action(
            env, account, "ssh_key.revoke", "ssh_public_key",
            key_id, "success")
        return json_response(
            {"ok": True, "revoked": True, "id": key_id},
            cache_control="no-store")

    return json_response({"error": "method_not_allowed"}, status=405)


def _ssh_gateway_token_ok(env, request):
    expected = ssh_auth.configured_gateway_token(
        getattr(env, "SSH_GATEWAY_TOKEN", ""))
    if not expected:
        return False
    supplied = str(request.headers.get("authorization") or "")
    if not supplied.lower().startswith("bearer "):
        return False
    return hmac.compare_digest(supplied[7:].strip(), expected)


async def _ssh_key_gateway_record(env, key_id="", public_key=""):
    row = None
    if key_id:
        row = await d1_first(
            env,
            "SELECT key_id,account_bi,key_type,fingerprint,data,created_at,"
            "last_used_at FROM account_ssh_keys "
            "WHERE key_id=? AND revoked_at=0",
            key_id,
        )
    elif public_key:
        try:
            parsed = ssh_auth.parse_public_key(public_key)
        except ssh_auth.SshPublicKeyError:
            return None, None
        key_bi = await blind_index(
            env, "ssh-public-key:" + parsed["publicKey"])
        row = await d1_first(
            env,
            "SELECT key_id,account_bi,key_type,fingerprint,data,created_at,"
            "last_used_at FROM account_ssh_keys "
            "WHERE key_bi=? AND revoked_at=0",
            key_bi,
        )
    if not row:
        return None, None
    try:
        data = await decrypt_row(env, row.get("data"))
        registered = ssh_auth.parse_public_key(data.get("publicKey", ""))
    except Exception:
        return None, None
    if public_key:
        try:
            supplied = ssh_auth.parse_public_key(public_key)
        except ssh_auth.SshPublicKeyError:
            return None, None
        if not hmac.compare_digest(
                registered["publicKey"], supplied["publicKey"]):
            return None, None
    # Resolve the current account name from the indexed account row. The
    # encrypted key envelope deliberately preserves its registration-time
    # metadata, while account rename updates this row's account_bi.
    account_rec = await _account_identity_rec_by_bi(
        env, row.get("account_bi"))
    account = clean_string(
        (account_rec or {}).get("name", ""), MAX_NODE_NAME).lower()
    if (
        not account
        or not account_rec
        or account_rec.get("status") != "active"
        or _account_kind(account_rec) != "user"
    ):
        return None, None
    # Return a copy with the current principal. Registration-time encrypted
    # metadata is useful evidence but must never control authorization after an
    # account rename.
    current = dict(data)
    current["account"] = account
    return row, current


async def _ssh_org_read_allowed(env, owner, repo, reader):
    try:
        rows = await d1_all(
            env, "SELECT org_bi FROM org_repos WHERE node_owner=? AND repo=?",
            owner.lower(), repo.lower())
        for row in rows or []:
            permission = await _org_permission(
                env, str(row.get("org_bi") or ""), reader)
            if team_permission_rank(permission) >= team_permission_rank("read"):
                return True
    except Exception:
        return False
    return False


async def ssh_gateway_authorize_handler(env, request):
    """Authorize a configured node-side SSH forced-command gateway.

    This is an HTTPS control-plane call. The raw SSH connection and Git process
    remain on the independently operated gateway host.
    """
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    if not _ssh_gateway_token_ok(env, request):
        return json_response(
            {"error": "unauthorized"}, status=401,
            cache_control="no-store")
    await ensure_schema(env)
    data, error = await _ssh_json_body(request)
    if error:
        return json_response(
            {"error": error},
            status=413 if error == "payload_too_large" else 400,
            cache_control="no-store")
    action = clean_string(data.get("action", ""), 20).lower()
    request_id = clean_string(data.get("requestId", ""), 40)
    if not re.fullmatch(r"[A-Za-z0-9_-]{24}", request_id):
        return json_response(
            {"authorized": False}, status=403,
            cache_control="no-store")
    if action == "lookup":
        row, _key_data = await _ssh_key_gateway_record(
            env, public_key=data.get("publicKey", ""))
        if not row:
            return json_response(
                {"authorized": False}, status=403,
                cache_control="no-store")
        return json_response({
            "ok": True,
            "authorized": True,
            "keyId": row.get("key_id"),
            "requestId": request_id,
        }, cache_control="no-store")
    if action != "authorize":
        return json_response({"error": "bad_action"}, status=400)

    key_id = clean_string(data.get("keyId", ""), 96)
    owner = safe_segment(data.get("owner", ""))
    repo = safe_segment(data.get("repository", ""))
    operation = clean_string(data.get("operation", ""), 40)
    if (
        not re.fullmatch(r"sk_[A-Za-z0-9_-]{16,80}", key_id)
        or not owner
        or not repo
        or operation not in ("git-upload-pack", "git-receive-pack")
    ):
        return json_response(
            {"authorized": False}, status=403,
            cache_control="no-store")
    row, key_data = await _ssh_key_gateway_record(env, key_id=key_id)
    if not row or not key_data:
        return json_response(
            {"authorized": False}, status=403,
            cache_control="no-store")
    account = clean_string(
        key_data.get("account", ""), MAX_NODE_NAME).lower()

    # An SSH URL may use an organization alias. Resolve it to the canonical
    # node namespace before repository lookup, permission enforcement, and the
    # path returned to the gateway.
    canonical_owner = await _org_repo_node(env, owner, repo) or owner
    gateway_access = _ssh_gateway_repository_access(
        env, canonical_owner, repo)
    repo_bi = await blind_index(env, canonical_owner + "/" + repo)
    repo_row = await d1_first(
        env,
        "SELECT is_private,data FROM repositories WHERE key_bi=?",
        repo_bi,
    )
    record = None
    if repo_row:
        try:
            record = await decrypt_row(env, repo_row.get("data"))
        except Exception:
            record = None
    authoritative_private = bool(
        int((repo_row or {}).get("is_private") or 0))
    public_record = bool(
        isinstance(record, dict)
        and record.get("visibility") == "public")
    if (
        not gateway_access
        or (
            operation == "git-receive-pack"
            and gateway_access != "read-write"
        )
        or not _catalog_record_matches_identity(
            record, canonical_owner, repo)
    ):
        allowed = False
    else:
        owns_repo = await _account_owns_node(
            env, account, canonical_owner)
        if operation == "git-receive-pack":
            allowed = bool(
                owns_repo
                or await _org_write_allowed(
                    env, canonical_owner, repo, account)
            )
        else:
            allowed = bool(
                (public_record and not authoritative_private)
                or owns_repo
                or await _repo_shared_with(
                    env, canonical_owner, repo, account)
                or await _ssh_org_read_allowed(
                    env, canonical_owner, repo, account)
            )
    if not allowed:
        if operation == "git-receive-pack":
            await _audit_sensitive_action(
                env, account, "ssh.git_authorize", "repository",
                canonical_owner + "/" + repo, "denied",
                {"operation": operation})
        return json_response(
            {"authorized": False}, status=403,
            cache_control="no-store")

    now = int(Date.now())
    await d1_run(
        env, "UPDATE account_ssh_keys SET last_used_at=? WHERE key_id=?",
        now, key_id)
    if operation == "git-receive-pack":
        await _audit_sensitive_action(
            env, account, "ssh.git_authorize", "repository",
            canonical_owner + "/" + repo, "success",
            {"operation": operation})
    return json_response({
        "ok": True,
        "authorized": True,
        "keyId": key_id,
        "requestId": request_id,
        "operation": operation,
        "owner": canonical_owner,
        "repository": repo,
        "repositoryRelativePath": canonical_owner + "/" + repo + ".git",
    }, cache_control="no-store")


async def _account_treasury_address(env, request):
    """Frozen alias for the removed Worker-custodied treasury flow."""
    del env, request
    return _legacy_treasury_disabled_response()


def _legacy_treasury_disabled_response():
    """Fail closed without returning an operational legacy deposit address."""
    return json_response({
        "error": "legacy_custody_disabled",
        "address": "",
        "featureState": "migration-only",
        "custody": "non-custodial",
        "fundStates": {
            "userOwnedFunds": (
                "Remain in each user's external self-custodial wallet."
            ),
            "communityFundedRewardPool": (
                "Use /api/rewards/pool for its configured public address, "
                "balance, and finalized history."
            ),
            "pendingRewards": (
                "Ledger allocations only; funds remain in their external "
                "source wallet until a locally approved transfer."
            ),
            "completedOnChainTransfers": (
                "Only finalized public transaction signatures are complete."
            ),
        },
        "notice": (
            "The legacy treasury/deposit flow is disabled. ForkMesh does not "
            "hold a wallet key or user funds. Historical rows require the "
            "documented offline custody migration."
        ),
    }, status=410, cache_control="no-store")


async def _account_central_fund(env, request):
    """Compatibility alias for canonical public community reward-pool state.

    It never returns an encrypted key-bearing legacy central_fund row. On a
    federated relay it proxies only the same public metadata produced by
    _central_fund_public: explicit fund states, on-chain balance/history, and
    the external-local-signer custody notice.
    """
    if not _is_main_relay(env):
        reply = await _call_main_relay(env, "/api/federation/central-fund", {})
        if reply and reply.get("address"):
            reply.pop("_status", None)
            return json_response(reply)
        return json_response({"address": ""}, status=503)
    payload = await _central_fund_public(env)
    if not payload or not payload.get("address"):
        return json_response({"address": ""}, status=503)
    return json_response(payload)


async def accounts_handler(env, request):
    await ensure_schema(env)
    url = urlparse(request.url)
    method = method_name(request)
    if url.path == "/api/accounts/signup" and method == "POST":
        return await _account_signup(env, request)
    if url.path == "/api/accounts/reserve" and method == "POST":
        return await _account_reserve(env, request)
    if url.path == "/api/accounts/profile" and method == "POST":
        return await _account_profile(env, request)
    if url.path == "/api/accounts/donation-address" and method == "POST":
        return await _account_donation_address(env, request)
    if url.path == "/api/accounts/donation-status" and method == "GET":
        return await _account_donation_status(env, request)
    if url.path == "/api/accounts/treasury-address" and method == "GET":
        return await _account_treasury_address(env, request)
    if url.path == "/api/accounts/central-fund" and method == "GET":
        return await _account_central_fund(env, request)
    if url.path.rstrip("/") == "/api/accounts/ssh-keys" and method in (
            "GET", "POST"):
        return await ssh_keys_handler(env, request)
    ssh_key_prefix = "/api/accounts/ssh-keys/"
    if url.path.startswith(ssh_key_prefix) and method == "DELETE":
        key_id = url.path[len(ssh_key_prefix):].strip("/")
        if "/" not in key_id:
            return await ssh_keys_handler(env, request, key_id)
    if url.path == "/api/accounts/finalize" and method == "POST":
        return await _account_finalize(env, request)
    if url.path == "/api/accounts/heartbeat" and method == "POST":
        return await _account_heartbeat(env, request)
    if url.path == "/api/accounts/verify-email" and method == "GET":
        return await _verify_email(env, request)
    if url.path == "/api/accounts/admin-pending" and method == "GET":
        return await _admin_pending(env, request)
    if url.path == "/api/accounts/admin-verify-email" and method == "POST":
        return await _admin_verify_email(env, request)
    if url.path == "/api/accounts/admin-relays" and method == "GET":
        return await _admin_relays(env, request)
    if url.path == "/api/accounts/admin-relay-approve" and method == "POST":
        return await _admin_relay_approve(env, request)
    if url.path == "/api/accounts/admin-ap" and method == "GET":
        return await _admin_ap_settings(env, request)
    if url.path == "/api/accounts/admin-ap-update" and method == "POST":
        return await _admin_ap_update(env, request)
    if url.path == "/api/accounts/admin-request-ownership" and method == "POST":
        return await _admin_request_ownership(env, request)
    if url.path == "/api/accounts/ownership-transfer-confirm" and method == "POST":
        return await _account_ownership_transfer_confirm(env, request)
    if url.path == "/api/accounts/login" and method == "POST":
        return await _account_login(env, request)
    if url.path == "/api/accounts/rotate" and method == "POST":
        return await _account_rotate(env, request)
    if url.path == "/api/accounts/logout" and method == "POST":
        return await _account_logout(env, request)
    if url.path == "/api/accounts/admin-session" and method == "POST":
        return await _account_admin_session(env, request)
    if url.path == "/api/accounts/rotate" and method == "POST":
        return await _account_rotate(env, request)
    if url.path == "/api/accounts/forgot-password" and method == "POST":
        return await _account_forgot_password(env, request)
    if url.path == "/api/accounts/reset-password" and method == "POST":
        return await _account_reset_password(env, request)
    if url.path == "/api/accounts/claim-node" and method == "POST":
        return await _account_claim_node(env, request)
    if url.path == "/api/accounts/claim-confirm" and method == "POST":
        return await _account_claim_confirm(env, request)
    if url.path == "/api/accounts/reclaim-node" and method == "POST":
        return await _account_reclaim_node(env, request)
    if url.path == "/api/accounts/link-node" and method == "POST":
        return await _account_link_node(env, request)
    if url.path == "/api/accounts/link-self" and method == "POST":
        return await _account_link_self(env, request)
    if url.path == "/api/accounts/link-grant" and method == "POST":
        return await _account_link_grant(env, request)
    if url.path == "/api/accounts/users" and method == "GET":
        return await _account_users_directory(env, request)
    contributions_match = ACCOUNT_CONTRIBUTIONS_RE.match(url.path)
    if contributions_match and method == "GET":
        return await _contribution_profile_api(
            env, request, contributions_match.group(1))
    follow_match = ACCOUNT_FOLLOW_RE.match(url.path)
    if follow_match and method in ("POST", "DELETE"):
        return await _account_follow(env, request, follow_match.group(1), method)
    match = ACCOUNTS_RE.match(url.path)
    if match and method == "GET":
        name = clean_string(match.group(1), MAX_NODE_NAME).lower()
        # The viewer-less lookup is what every /@name view, fediverse
        # click-through and dashboard page boot fires, and it cost 6-8 D1
        # ops (record decrypt + admin check + three follow COUNTs + mirror
        # count + presence) per hit: park the guest variant at the edge.
        # viewer=<name> responses stay per-caller (isFollowing) and skip the
        # cache; _ap_broadcast_actor_update purges the key on profile edits.
        viewer_less = "viewer" not in parse_qs(urlparse(request.url).query)
        lookup_cache_key = ACCOUNT_LOOKUP_CACHE_PREFIX + quote(name)
        # Users and nodes are separate tables: this public profile lookup reads
        # from those authoritative per-kind stores (keyless reservations live
        # in nodes too, so the signup availability check below still sees a
        # reserved name as taken).
        name_bi = await blind_index(env, name)
        rec = await _account_identity_rec_by_bi(env, name_bi)
        if not rec:
            # Availability misses are deliberately uncached: the signup
            # form's name check must see a just-taken name immediately.
            return json_response(
                {"ok": True, "exists": False, "available": True, "name": name})
        profile_private = bool(rec.get("profile_private"))
        if profile_private:
            # A query-string `viewer` is display-only and can be spoofed; only
            # a real bearer session may reveal a private profile. Node profiles
            # are also visible to the user account that explicitly owns them.
            _, viewer_rec = await _account_session_record(env, request)
            viewer_account = clean_string(
                (viewer_rec or {}).get("name", ""),
                MAX_NODE_NAME,
            ).lower()
            target_name = clean_string(
                rec.get("name", name), MAX_NODE_NAME).lower()
            owner_view = bool(
                viewer_account and (
                    viewer_account == target_name
                    or await _account_owns_node(
                        env, viewer_account, target_name)
                )
            )
            if not owner_view:
                # Name availability necessarily remains visible to prevent
                # duplicate registration, but no profile, device, status,
                # activity, social, key, or ownership fields are disclosed.
                taken = (
                    rec.get("status") == "active"
                    or bool(rec.get("donation_confirmed")))
                return json_response({
                    "ok": True,
                    "exists": True,
                    "available": not taken,
                    "name": target_name or name,
                    "profilePrivate": True,
                }, cache_control="no-store")
        # Positive cache entries are consulted only after the current encrypted
        # record has confirmed the profile is public. This prevents an old warm
        # entry from surviving a privacy toggle.
        cacheable_guest = viewer_less and not profile_private
        if cacheable_guest:
            cached = await edge_cache_match(lookup_cache_key)
            if cached is not None:
                return cached
        # Public lookup never returns email/secret material. Active accounts and
        # migration-era confirmed records keep their names unavailable.
        taken = rec.get("status") == "active" or bool(rec.get("donation_confirmed"))
        # isAdmin + pubkey let any client authenticate a signed admin-moderation
        # action (e.g. a chat admin-delete) made by this account's identity key.
        # kind/owner/nodes let the dashboard's claim form tell "that's a user
        # account, not a claimable node" (and "already owned") before starting a
        # claim, and let a node's own profile list the nodes linked to its user
        # account; node ownership is public catalog-adjacent data like the name
        # itself (same fields _account_public_payload already exposes).
        # emailVerified is a boolean only (no address) so the dashboard's
        # periodic self-profile poll (refreshPublicProfile, which reuses this
        # same lookup) can pick up a verification that happened in another
        # tab instead of showing "verify your email" forever (issue #320).
        kind = _account_kind(rec)
        online = False
        if kind == "node":
            # account_presence is the same heartbeat table the network page
            # uses for online/offline; the /@name node page shows it as
            # node-specific info the way a user page shows followers.
            presence = await d1_first(
                env, "SELECT ts FROM account_presence WHERE name_bi=?", name_bi)
            online = bool(presence and int(presence.get("ts") or 0) >=
                          int(Date.now()) - ACCOUNT_PRESENCE_STALE_MS)
        payload = {"ok": True, "exists": True, "available": not taken,
                   "name": rec.get("name", name), "status": rec.get("status", ""),
                   "pubkey": rec.get("pubkey", ""),
                   "isAdmin": await _is_admin(env, rec.get("name", name)),
                   "emailVerified": bool(rec.get("email_verified")),
                   "avatarPng": rec.get("avatar_png", ""),
                   "avatarUpdatedAt": rec.get("avatar_updated_at", 0),
                   "createdAt": rec.get("created_at", 0),
                   "kind": kind,
                   "online": online,
                   "owner": rec.get("owner", ""),
                   "nodes": _owned_nodes(rec)}
        # viewer=<name> lets the public-profile page show the caller's own
        # Follow/Following state. Display-only: a spoofed viewer can only see
        # a wrong button label; actual follow writes are session-token gated.
        viewer = clean_string(
            parse_qs(urlparse(request.url).query).get("viewer", [""])[0],
            MAX_NODE_NAME).lower()
        social = await _account_social_counts(
            env, rec.get("name", name), viewer)
        payload = {**payload, "social": social, **social}
        payload = {**payload, **_account_profile_fields(rec)}
        if cacheable_guest:
            resp = json_response(payload, cache_seconds=60)
            await edge_cache_put(lookup_cache_key, resp)
            return resp
        return json_response(payload)
    return json_response({"error": "not_found"}, status=404)


# --- Repository submission inboxes (encrypted) ------------------------------

# =============================================================================
# --- ActivityPub federation (fediverse interop) -------------------------------
#
# Makes local users (@alice@<domain>) and repositories (@owner.repo@<domain>)
# followable from Mastodon-compatible servers, publishes signed-inbox events
# (issues, PR/discussion/commit activity) plus owner-pushed announcements
# (releases, merges) as Notes to followers, and ingests remote replies as
# clearly-marked "federated comments" — kept OUTSIDE the Ed25519-signed event
# log, since a fediverse reply can never carry a forkmesh author signature.
#
# Wire compatibility follows Mastodon/Wildebeest: RSA-2048 actor keys published
# as publicKeyPem, draft-cavage HTTP signatures over
# "(request-target) host date digest content-type", Digest: SHA-256=<b64>.
# Delivery is queue-free (free plan): a publish inserts one ap_outbox row per
# unique destination inbox, best-effort drains a few inline via the request,
# and the per-minute cron drains the backlog with capped exponential backoff.
# Operator configuration lives in ap_settings/ap_blocked_domains, managed via
# the signed admin API (/api/accounts/admin-ap, /api/accounts/admin-ap-update):
# a global enable switch plus a remote-domain blocklist (defederation).
# The Solana payout relay mesh is a separate system at /api/relay-mesh/*
# (legacy alias /api/federation/*); the fediverse layer lives under /ap/*.
# =============================================================================

AP_ACTOR_USER = "user"
AP_ACTOR_REPO = "repo"
AP_ACTOR_INSTANCE = "instance"
AP_INSTANCE_HANDLE = "instance"
AP_MAX_INBOX_BYTES = 128 * 1024
AP_MAX_COMMENTS_PER_THREAD = 500
AP_MAX_FOLLOWERS_PER_ACTOR = 5000
# The `first` page embedded directly in a followers/following collection
# (collection_doc) — a fixed cap keeps the response small even for popular
# actors instead of paginating with next/prev links.
AP_COLLECTION_PAGE_SIZE = 200
AP_REMOTE_ACTOR_TTL_MS = 24 * 60 * 60 * 1000
AP_DATE_SKEW_MS = 12 * 60 * 60 * 1000
# Inline sends per publish; the rest waits for the cron drain. Kept small so a
# signed-inbox POST never burns its subrequest budget on fediverse fan-out.
AP_IMMEDIATE_DELIVERIES = 5
AP_CRON_DELIVERIES = 20
AP_DIGEST_CRON_BATCH = 12
AP_FEDI_KINDS = ("issue", "pull", "discussion", "commit", "release")
# Brand images served from Static Assets, shown as every actor's avatar and
# profile header on Mastodon-compatible servers.
AP_AVATAR_PATH = "/assets/fediverse-avatar.png"
AP_BANNER_PATH = "/assets/fediverse-banner.png"

_AP_RSA_ALG = {"name": "RSASSA-PKCS1-v1_5", "hash": "SHA-256"}


def _ap_origin(env, request=None):
    # Absolute https origin for actor/object ids. PUBLIC_BASE_URL wins (set on
    # self-hosted relays); otherwise the request's own host; cron falls back to
    # the canonical production domain.
    base = (getattr(env, "PUBLIC_BASE_URL", "") or "").strip().rstrip("/")
    if base.startswith("https://") or base.startswith("http://"):
        return base
    if request is not None:
        try:
            host = urlparse(request.url).netloc
            if host:
                return "https://" + host
        except Exception:
            pass
    return "https://forkmesh.com"


def _ap_domain_of(origin):
    return origin.split("://", 1)[-1]


# Operator configuration (admin-managed via /api/accounts/admin-ap*): a global
# on/off switch plus the remote-domain blocklist. Cached per isolate briefly so
# every /ap request and publish hook doesn't re-read two tables.
_AP_SETTINGS_CACHE = {"ts": 0, "enabled": True, "blocked": set()}
AP_SETTINGS_TTL_MS = 60 * 1000


async def _ap_settings(env, fresh=False):
    now = int(Date.now())
    if not fresh and now - _AP_SETTINGS_CACHE["ts"] < AP_SETTINGS_TTL_MS:
        return _AP_SETTINGS_CACHE
    row = await d1_first(env, "SELECT v FROM ap_settings WHERE k='enabled'")
    enabled = (row or {}).get("v", "1") != "0"
    rows = await d1_all(env, "SELECT domain FROM ap_blocked_domains")
    blocked = {r.get("domain", "") for r in (rows or []) if r.get("domain")}
    _AP_SETTINGS_CACHE.update({"ts": now, "enabled": enabled,
                               "blocked": blocked})
    return _AP_SETTINGS_CACHE


async def _ap_enabled(env):
    return (await _ap_settings(env))["enabled"]


async def _ap_domain_blocked(env, host):
    return ap.domain_blocked_by(host, (await _ap_settings(env))["blocked"])


def _ap_disabled_response():
    return json_response({"error": "not_found"}, status=404)


def _ap_actor_url(origin, kind, handle):
    if kind == AP_ACTOR_INSTANCE:
        return origin + ap.INSTANCE_ACTOR_PATH
    if kind == AP_ACTOR_USER:
        return origin + ap.user_actor_path(handle)
    owner, _, repo = handle.partition(".")
    return origin + ap.repo_actor_path(owner, repo)


def _ap_uuid():
    raw = js_crypto.getRandomValues(Uint8Array.new(16))
    return bytes(raw.to_py()).hex()


async def _ap_generate_keypair():
    params = to_js({"name": "RSASSA-PKCS1-v1_5", "modulusLength": 2048,
                    "hash": "SHA-256"})
    params.publicExponent = _to_js(bytes([1, 0, 1]))  # 65537
    pair = await js_crypto.subtle.generateKey(
        params, True, _to_js(["sign", "verify"]))
    spki = await js_crypto.subtle.exportKey("spki", pair.publicKey)
    pkcs8 = await js_crypto.subtle.exportKey("pkcs8", pair.privateKey)
    pub_pem = ap.pem_wrap(
        "PUBLIC KEY",
        base64.b64encode(bytes(Uint8Array.new(spki).to_py())).decode())
    priv_b64 = base64.b64encode(bytes(Uint8Array.new(pkcs8).to_py())).decode()
    return pub_pem, priv_b64


async def _ap_rsa_sign_b64(priv_b64, text):
    key = await js_crypto.subtle.importKey(
        "pkcs8", _to_js(base64.b64decode(priv_b64)), to_js(_AP_RSA_ALG),
        False, _to_js(["sign"]))
    sig = await js_crypto.subtle.sign(
        to_js({"name": "RSASSA-PKCS1-v1_5"}), key, _to_js(text.encode()))
    return base64.b64encode(bytes(Uint8Array.new(sig).to_py())).decode()


async def _ap_rsa_verify(pub_pem, sig_b64, text):
    try:
        der = base64.b64decode(ap.pem_body(pub_pem))
        signature = base64.b64decode(sig_b64)
    except Exception:
        return False
    try:
        key = await js_crypto.subtle.importKey(
            "spki", _to_js(der), to_js(_AP_RSA_ALG), False, _to_js(["verify"]))
        ok = await js_crypto.subtle.verify(
            to_js({"name": "RSASSA-PKCS1-v1_5"}), key, _to_js(signature),
            _to_js(text.encode()))
        return bool(ok)
    except Exception:
        return False


async def _ap_actor_bi(env, kind, handle):
    return await blind_index(env, "ap-actor:%s:%s" % (kind, handle))


async def _ap_local_actor(env, kind, handle, create=False):
    # A local actor's keypair, minted lazily on the first fediverse lookup so
    # users/repos nobody follows never get a row.
    actor_bi = await _ap_actor_bi(env, kind, handle)
    row = await d1_first(
        env, "SELECT data FROM ap_actors WHERE actor_bi=?", actor_bi)
    if row:
        rec = await decrypt_row(env, row.get("data"))
        if rec and rec.get("privkey") and rec.get("pubkeyPem"):
            rec["actorBi"] = actor_bi
            return rec
    if not create:
        return None
    pub_pem, priv_b64 = await _ap_generate_keypair()
    rec = {"kind": kind, "handle": handle, "pubkeyPem": pub_pem,
           "privkey": priv_b64, "createdAt": int(Date.now())}
    await d1_run(
        env,
        "INSERT INTO ap_actors (actor_bi, kind, pubkey_pem, data, created_at)"
        " VALUES (?,?,?,?,?) ON CONFLICT(actor_bi) DO NOTHING",
        actor_bi, kind, pub_pem, await encrypt_row(env, rec),
        rec["createdAt"])
    # Re-read: a concurrent first-lookup may have won the insert race with a
    # different keypair, and the stored row is the canonical one (the pubkey
    # is already being served to the remote server that triggered it).
    row = await d1_first(
        env, "SELECT data FROM ap_actors WHERE actor_bi=?", actor_bi)
    stored = await decrypt_row(env, row.get("data")) if row else None
    rec = stored or rec
    rec["actorBi"] = actor_bi
    return rec


async def _ap_user_federates(env, name):
    # Any active, non-private account federates as a Person — node-owner
    # accounts included, not just login ("user"-kind) accounts: the node name
    # is the public authoring identity on issues/PRs, so it is what fediverse
    # followers expect to find at @name@<domain>. The web follow API
    # (_account_follow) accepts the same targets.
    name = (name or "").strip().lower()
    if not valid_node_name(name):
        return False
    _, rec = await _account_row(env, name)
    return bool(rec and rec.get("status") == "active"
                and not rec.get("profile_private"))


async def _ap_org_alias_owner(env, owner, repo):
    # Organization repo aliases (issue #388): a fediverse actor is addressed by
    # the org handle (@org.repo@host), but the backing repo — its repositories
    # row, media, per-repo AP settings and issue inbox — lives under the linked
    # node, never under the org name. Resolve org->node for those data reads so
    # federation keeps working after a repo is fronted by an org, while the
    # public actor identity (handle, reply author, web URLs) stays the org. A
    # plain node URL (no alias) resolves to itself, so this is a safe no-op on
    # every non-org path.
    node = await _org_repo_node(env, owner, repo)
    return node or owner


async def _ap_repo_federates(env, owner, repo):
    # Only published, public repos federate. A missing catalog row means the
    # repo was never published — unlike the git-clone path (which stays open
    # for ad-hoc hosts), an unpublished repo has no fediverse presence. The
    # owner can also switch federation off per repo (web/Qt repo settings).
    data_owner = await _ap_org_alias_owner(env, owner, repo)
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader):
        if await privacy_reader(env, data_owner, repo):
            return False
    else:
        # Isolated compatibility harnesses may omit _repo_is_private.
        # Production always uses its signed-record, fail-closed decision.
        key_bi = await blind_index(env, data_owner + "/" + repo)
        row = await d1_first(
            env, "SELECT is_private FROM repositories WHERE key_bi=?", key_bi)
        if not row or int(row.get("is_private") or 0):
            return False
    return (await _ap_repo_settings_get(env, data_owner, repo))["federate"]


# Per-repo fediverse switches the owner manages from the web and Qt repo
# settings. Defaults are "all on" so a repo without a row (every repo before
# migration 0035) federates exactly as before.
AP_REPO_SETTING_DEFAULTS = {
    "federate": True,        # actor/webfinger exist at all
    "broadcastEvents": True,  # issues/PRs/releases posted to followers
    "acceptComments": True,  # remote replies ingested as federated comments
}


async def _ap_repo_settings_bi(env, owner, repo):
    # Distinct namespace + full lowercasing on both halves: callers reach this
    # with URL-cased (About handler) and handle-cased (AP gates) names, and
    # they must all land on the same row. Org-alias handles resolve to the
    # backing node so a mention gate keys on the same row the owner's repo
    # settings wrote under the node name (issue #388).
    owner = await _ap_org_alias_owner(env, owner, repo)
    return await blind_index(
        env, "ap-repo-settings:%s/%s" % (str(owner or "").strip().lower(),
                                         str(repo or "").strip().lower()))


async def _ap_repo_settings_get(env, owner, repo):
    row = await d1_first(
        env, "SELECT data FROM ap_repo_settings WHERE repo_bi=?",
        await _ap_repo_settings_bi(env, owner, repo))
    settings = dict(AP_REPO_SETTING_DEFAULTS)
    if row:
        try:
            stored = json.loads(row.get("data") or "{}")
        except Exception:
            stored = {}
        if isinstance(stored, dict):
            for key in AP_REPO_SETTING_DEFAULTS:
                if key in stored:
                    settings[key] = bool(stored[key])
    return settings


async def _ap_org_digest_settings_get(env, org_bi):
    """Return the org-alias digest gate.

    Organization controls are deliberately a second, suppress-only gate. The
    linked repository owner's `federate` and `broadcastEvents` settings must
    also be enabled before any org-alias event can enter a queue.
    """
    row = await d1_first(
        env, "SELECT data FROM ap_org_digest_settings WHERE org_bi=?", org_bi)
    controls = fedi_digest.normalize_controls({})
    if row:
        try:
            stored = json.loads(row.get("data") or "{}")
        except Exception:
            stored = {}
        if isinstance(stored, dict):
            controls = fedi_digest.normalize_controls(stored)
    return controls


async def _ap_digest_scope_bi(env, scope):
    return await blind_index(
        env, "ap-digest:" + str(scope or "").strip().lower())


async def _ap_digest_queue_record(env, scope):
    scope_bi = await _ap_digest_scope_bi(env, scope)
    row = await d1_first(
        env,
        "SELECT scope_bi, next_ts, last_published_at, data "
        "FROM ap_digest_queues WHERE scope_bi=?",
        scope_bi)
    if not row:
        return scope_bi, None, None
    rec = await decrypt_row(env, row.get("data")) or {}
    if not isinstance(rec, dict) or rec.get("scope") != scope:
        # Fail closed if the encrypted payload does not match its blind key.
        return scope_bi, row, None
    return scope_bi, row, rec


async def _ap_enqueue_digest_scope(
        env, scope_owner, repo, source_owner, event):
    """Insert one already-reduced public event into an encrypted scope queue."""
    scope_owner = clean_string(scope_owner, MAX_NODE_NAME).strip().lower()
    source_owner = clean_string(source_owner, MAX_NODE_NAME).strip().lower()
    repo = clean_string(repo, MAX_REPO_SEGMENT).strip()
    scope = scope_owner + "/" + repo.lower()
    if (not valid_node_name(scope_owner) or not valid_node_name(source_owner)
            or not repo or not event):
        return False
    scope_bi, row, rec = await _ap_digest_queue_record(env, scope)
    now = int(Date.now())
    last_published = int((row or {}).get("last_published_at") or 0)
    events = fedi_digest.add_event(
        (rec or {}).get("events") if rec else [], event)
    if not events:
        return False
    # A new queue waits a full cadence so several meaningful events can be
    # combined. After a prior post, the next due time remains anchored to that
    # post rather than sliding forward with every incoming event.
    if row:
        next_ts = int(row.get("next_ts") or 0)
        if next_ts <= 0:
            next_ts = max(now, last_published + fedi_digest.DAY_MS)
    else:
        next_ts = now + fedi_digest.DAY_MS
    payload = {
        "scope": scope,
        "scopeOwner": scope_owner,
        "repo": repo,
        "sourceOwner": source_owner,
        "events": events,
        "lastPublishedAt": last_published,
    }
    await d1_run(
        env,
        "INSERT INTO ap_digest_queues "
        "(scope_bi, next_ts, last_published_at, data, updated_at) "
        "VALUES (?,?,?,?,?) ON CONFLICT(scope_bi) DO UPDATE SET "
        "next_ts=excluded.next_ts, data=excluded.data, "
        "updated_at=excluded.updated_at",
        scope_bi, next_ts, last_published,
        await encrypt_row(env, payload), now)
    return True


async def _ap_enqueue_repo_digest(
        env, request, owner, repo, kind, event_type, ref, title, body):
    """Queue a safe repository event for its repo and enabled org aliases."""
    if await _repo_is_private(env, owner, repo):
        return False
    settings = await _ap_repo_settings_get(env, owner, repo)
    if not (settings["federate"] and settings["broadcastEvents"]):
        return False
    origin = _ap_origin(env, request)
    timestamp = int(Date.now())
    canonical = fedi_digest.repository_event(
        origin, owner, repo, kind, event_type, ref, title, body, timestamp)
    queued = await _ap_enqueue_digest_scope(
        env, owner, repo, owner, canonical)

    # An organization alias has its own repo actor/followers and therefore its
    # own daily cadence. Org admins may suppress that alias, but cannot enable
    # it when the backing repository owner disabled federation.
    rows = await d1_all(
        env,
        "SELECT r.org_bi AS org_bi, o.name AS name, s.data AS settings "
        "FROM org_repos r JOIN orgs o ON o.org_bi=r.org_bi "
        "LEFT JOIN ap_org_digest_settings s ON s.org_bi=r.org_bi "
        "WHERE r.node_owner=? AND r.repo=? ORDER BY o.name LIMIT ?",
        str(owner).lower(), str(repo).lower(), MAX_ORGS_PER_ACCOUNT)
    for linked in rows or []:
        try:
            raw_controls = json.loads(linked.get("settings") or "{}")
        except Exception:
            raw_controls = {}
        controls = fedi_digest.normalize_controls(raw_controls)
        org = clean_string(linked.get("name"), MAX_NODE_NAME).strip().lower()
        if not controls["enabled"] or not valid_node_name(org):
            continue
        org_event = fedi_digest.repository_event(
            origin, org, repo, kind, event_type, ref, title, body, timestamp)
        queued = (await _ap_enqueue_digest_scope(
            env, org, repo, owner, org_event)) or queued
    return queued


async def _ap_purge_repo_digest_queues(env, owner, repo):
    """Drop queued automatic posts when the repository owner disables them."""
    scopes = [str(owner).lower() + "/" + str(repo).lower()]
    rows = await d1_all(
        env,
        "SELECT o.name AS name FROM org_repos r "
        "JOIN orgs o ON o.org_bi=r.org_bi "
        "WHERE r.node_owner=? AND r.repo=? LIMIT ?",
        str(owner).lower(), str(repo).lower(), MAX_ORGS_PER_ACCOUNT)
    scopes.extend(
        str(row.get("name") or "").lower() + "/" + str(repo).lower()
        for row in (rows or []) if row.get("name"))
    for scope in scopes:
        await d1_run(
            env, "DELETE FROM ap_digest_queues WHERE scope_bi=?",
            await _ap_digest_scope_bi(env, scope))


async def _ap_digest_preview(env, scope):
    _, row, rec = await _ap_digest_queue_record(env, scope)
    events = (rec or {}).get("events") if rec else []
    digest = fedi_digest.build_digest(events, scope)
    return {
        "scope": scope,
        "pending": len(events or []),
        "preview": digest,
        "lastPublishedAt": int((row or {}).get("last_published_at") or 0),
        "nextPublishAt": int((row or {}).get("next_ts") or 0),
    }


async def _ap_digest_scope_allowed(env, rec):
    """Revalidate privacy/ownership controls immediately before publishing."""
    scope_owner = clean_string(
        (rec or {}).get("scopeOwner"), MAX_NODE_NAME).strip().lower()
    source_owner = clean_string(
        (rec or {}).get("sourceOwner"), MAX_NODE_NAME).strip().lower()
    repo = clean_string((rec or {}).get("repo"), MAX_REPO_SEGMENT).strip()
    if not scope_owner or not source_owner or not repo:
        return False
    if await _repo_is_private(env, source_owner, repo):
        return False
    settings = await _ap_repo_settings_get(env, source_owner, repo)
    if not (settings["federate"] and settings["broadcastEvents"]):
        return False
    if scope_owner == source_owner:
        return True
    org_bi, org_row = await _org_row(env, scope_owner)
    if not org_row:
        return False
    linked = await d1_first(
        env,
        "SELECT 1 AS one FROM org_repos "
        "WHERE org_bi=? AND repo=? AND node_owner=?",
        org_bi, repo.lower(), source_owner)
    if not linked:
        return False
    return (await _ap_org_digest_settings_get(env, org_bi))["enabled"]


async def _ap_publish_digest_row(env, row):
    """Durably create one digest Note/outbox fan-out, then consume its events."""
    scope_bi = str((row or {}).get("scope_bi") or "")
    rec = await decrypt_row(env, (row or {}).get("data")) or {}
    scope = str(rec.get("scope") or "")
    if not scope_bi or not scope or not await _ap_digest_scope_allowed(env, rec):
        # A repo made private, an owner opt-out, or an unlinked/disabled org
        # must revoke queued metadata rather than leave it probeable.
        if scope_bi:
            await d1_run(
                env, "DELETE FROM ap_digest_queues WHERE scope_bi=?", scope_bi)
        return False
    now = int(Date.now())
    events = rec.get("events") if isinstance(rec.get("events"), list) else []
    last_published = int(row.get("last_published_at") or 0)
    if not fedi_digest.digest_due(events, last_published, now):
        return False
    digest = fedi_digest.build_digest(events, scope)
    if not digest:
        await d1_run(
            env, "DELETE FROM ap_digest_queues WHERE scope_bi=?", scope_bi)
        return False

    origin = _ap_origin(env)
    scope_owner = str(rec.get("scopeOwner") or "").lower()
    repo = str(rec.get("repo") or "")
    handle = ap.repo_handle(scope_owner, repo.lower())
    local = await _ap_local_actor(env, AP_ACTOR_REPO, handle)
    if not local:
        # Preserve lazy actor creation: a repo nobody follows does not mint an
        # RSA key merely because it had local activity.
        return False
    followers = await d1_all(
        env,
        "SELECT inbox, shared_inbox FROM ap_followers WHERE actor_bi=?",
        local["actorBi"])
    actor_url = _ap_actor_url(origin, AP_ACTOR_REPO, handle)
    object_uuid = hashlib.sha256(
        ("forkmesh-ap-digest-v1\n" + scope + "\n"
         + "\n".join(digest["eventIds"])).encode()).hexdigest()[:32]
    object_url = origin + "/ap/o/" + object_uuid
    web_url = origin + repo_web_href(scope_owner, repo)
    note = ap.note_doc(
        object_url, actor_url, actor_url + "/followers",
        ap.note_html_from_text(digest["text"]), now, web_url=web_url)
    stored = {
        "note": note,
        "context": {
            "owner": scope_owner, "repo": repo, "kind": "daily_digest",
            "ref": object_uuid, "key": "digest:" + scope,
        },
        "media": [],
        "automated": True,
        "eventIds": digest["eventIds"],
    }
    body_str = json.dumps(ap.create_activity(note))
    out_data = await encrypt_row(env, {
        "body": body_str, "actorKind": AP_ACTOR_REPO,
        "actorHandle": handle, "actorUrl": actor_url})

    remaining = fedi_digest.remove_published(events, digest["eventIds"])
    rec["events"] = remaining
    rec["lastPublishedAt"] = now
    next_ts = now + fedi_digest.DAY_MS
    statements = [(
        "INSERT OR IGNORE INTO ap_objects "
        "(object_uuid, actor_bi, context_bi, data, published) "
        "VALUES (?,?,NULL,?,?)",
        (object_uuid, local["actorBi"], await encrypt_row(env, stored), now),
    )]
    seen = set()
    for follower in followers or []:
        inbox = ((follower.get("shared_inbox") or "").strip()
                 or (follower.get("inbox") or "").strip())
        if not inbox or inbox in seen:
            continue
        seen.add(inbox)
        delivery_bi = await blind_index(
            env, "ap-digest-delivery:" + object_uuid + ":" + inbox)
        statements.append((
            "INSERT OR IGNORE INTO ap_outbox "
            "(inbox, data, attempts, next_ts, created_at, dedupe_bi) "
            "VALUES (?,?,0,?,?,?)",
            (inbox, out_data, now, now, delivery_bi),
        ))
    statements.append((
        "UPDATE ap_digest_queues SET next_ts=?, last_published_at=?, "
        "data=?, updated_at=? WHERE scope_bi=?",
        (next_ts, now, await encrypt_row(env, rec), now, scope_bi),
    ))
    # D1 batch is transactional: event ids are removed only in the same durable
    # commit that creates the deterministic Note and retryable outbox rows.
    await _contribution_run_batch(env, statements)
    return True


async def _ap_process_digest_queues(env, limit=AP_DIGEST_CRON_BATCH):
    """Cron: publish a bounded batch of due, non-empty daily digests."""
    if not await _ap_enabled(env):
        return 0
    now = int(Date.now())
    rows = await d1_all(
        env,
        "SELECT scope_bi, next_ts, last_published_at, data "
        "FROM ap_digest_queues WHERE next_ts<=? "
        "ORDER BY next_ts ASC LIMIT ?",
        now, max(1, min(int(limit), AP_DIGEST_CRON_BATCH)))
    published = 0
    for row in rows or []:
        if await _ap_publish_digest_row(env, row):
            published += 1
    return published


# The unauthenticated ActivityPub read endpoints (webfinger, nodeinfo, actor
# docs, collections, objects) are what fediverse servers and crawlers hammer
# in bursts — every server that sees a federated post resolves the actor and
# its collections, and each of those hits used to reach D1. Under a burst
# that pressure is what pushed the free-plan worker/D1 into "Too many
# requests" (issue #416, round two of adhoc #9). They already sent public
# max-age headers, but dynamic Worker responses are never edge-cached
# implicitly, so store them in the colo cache explicitly: a burst collapses
# to one origin computation per colo per TTL. Keyed by the canonical public
# URL; only successful (200) documents are stored.

async def _ap_negative_response(cache_key, error="not_found"):
    # Park a 404 at the edge briefly. Probes for handles that don't federate
    # (deleted accounts, crawlers, Mastodon re-resolving after a failed
    # follow) otherwise re-run the full D1 federation gate on every hit, and
    # they arrive in the same bursts the 200s do.
    resp = json_response({"error": error}, status=404, cache_seconds=120)
    await edge_cache_put(cache_key, resp)
    return resp


async def ap_hostmeta_handler(env, request):
    # Mastodon's resolver falls back to GET /.well-known/host-meta whenever a
    # webfinger lookup fails, so during any failure window each missed
    # resolution used to cost a SECOND request that walked the entire route
    # chain into the terminal JSON 404 — a self-amplifying loop. The document
    # is a constant pointer at our webfinger template: no schema, no D1, and
    # a day at the edge.
    if method_name(request) not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    origin = _ap_origin(env, request)
    cache_key = origin + "/.well-known/host-meta"
    cached = await edge_cache_match(cache_key)
    if cached is not None:
        return cached
    xrd = ('<?xml version="1.0" encoding="UTF-8"?>\n'
           '<XRD xmlns="http://docs.oasis-open.org/ns/xri/xrd-1.0">'
           '<Link rel="lrdd" '
           'template="%s/.well-known/webfinger?resource={uri}"/>'
           '</XRD>' % origin)
    resp = Response(xrd, status=200, headers={
        "content-type": "application/xrd+xml; charset=utf-8",
        "cache-control": "public, max-age=86400",
    })
    await edge_cache_put(cache_key, resp)
    return resp


async def ap_webfinger_handler(env, request):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    params = parse_qs(urlparse(request.url).query)
    handle, domain = ap.parse_acct_resource(params.get("resource", [""])[0])
    if not handle:
        return json_response({"error": "invalid_resource"}, status=400)
    origin = _ap_origin(env, request)
    our_domain = _ap_domain_of(origin)
    if domain != our_domain:
        return json_response({"error": "not_found"}, status=404)
    # Key on the parsed acct (already lowercase-normalized), so the many
    # spellings of the same resource share one cache entry.
    cache_key = ("%s/.well-known/webfinger?resource=acct:%s@%s"
                 % (origin, handle, domain))
    cached = await edge_cache_match(cache_key)
    if cached is not None:
        try:
            if int(cached.status) >= 400:
                return cached
        except Exception:
            pass
    await ensure_schema(env)
    if not await _ap_enabled(env):
        return _ap_disabled_response()
    if handle == our_domain:
        kind, actor_handle, acct_name = (
            AP_ACTOR_INSTANCE, AP_INSTANCE_HANDLE, our_domain)
    else:
        parsed = ap.split_handle(handle)
        if not parsed:
            return await _ap_negative_response(cache_key)
        if parsed[0] == "user":
            if not await _ap_user_federates(env, parsed[1]):
                return await _ap_negative_response(cache_key)
            kind, actor_handle, acct_name = AP_ACTOR_USER, parsed[1], parsed[1]
        else:
            if not await _ap_repo_federates(env, parsed[1], parsed[2]):
                return await _ap_negative_response(cache_key)
            kind = AP_ACTOR_REPO
            actor_handle = ap.repo_handle(parsed[1], parsed[2])
            acct_name = actor_handle
    # Resolve visibility before reading edge cache. Otherwise a public actor
    # document could remain discoverable after its account/repository is made
    # private, for the remainder of the old cache entry's TTL.
    if cached is not None:
        return cached
    actor_url = _ap_actor_url(origin, kind, actor_handle)
    doc = ap.webfinger_doc(acct_name + "@" + our_domain, actor_url)
    resp = json_response(doc, cache_seconds=3600, extra_headers={
        "content-type": ap.JRD_CONTENT_TYPE,
        "access-control-allow-origin": "*",
    })
    await edge_cache_put(cache_key, resp)
    return resp


# NodeInfo usage counts, cached per isolate. Every fediverse server that hears
# about this instance polls /nodeinfo/2.1, and each hit ran two COUNT(*) table
# scans — pure statistics that don't need to be fresher than the cache TTL,
# and one of the first things to fall over when D1 is under pressure.
_NODEINFO_CACHE = {"ts": 0, "users": 0, "posts": 0}
NODEINFO_CACHE_TTL_MS = 10 * 60 * 1000


async def ap_nodeinfo_handler(env, request, index):
    origin = _ap_origin(env, request)
    cache_key = origin + ("/.well-known/nodeinfo" if index else "/nodeinfo/2.1")
    cached = await edge_cache_match(cache_key)
    if cached is not None:
        return cached
    await ensure_schema(env)
    if not await _ap_enabled(env):
        return _ap_disabled_response()
    if index:
        resp = json_response(ap.nodeinfo_index(origin), cache_seconds=3600)
        await edge_cache_put(cache_key, resp)
        return resp
    now = int(Date.now())
    if now - _NODEINFO_CACHE["ts"] >= NODEINFO_CACHE_TTL_MS:
        users = await d1_first(env, "SELECT COUNT(*) AS c FROM users")
        posts = await d1_first(env, "SELECT COUNT(*) AS c FROM ap_objects")
        _NODEINFO_CACHE.update({
            "ts": now,
            "users": (users or {}).get("c", 0) or 0,
            "posts": (posts or {}).get("c", 0) or 0,
        })
    doc = ap.nodeinfo_doc(
        _build_rev(env)[:12], _NODEINFO_CACHE["users"],
        _NODEINFO_CACHE["posts"])
    resp = json_response(doc, cache_seconds=3600)
    await edge_cache_put(cache_key, resp)
    return resp


async def _ap_build_actor_doc(env, origin, kind, handle, rec):
    """The actor document, shared by the GET endpoint and the Update
    broadcast (profile/branding changes). Returns None when the actor does
    not federate (missing/private/blocked account or repo)."""
    # Brand defaults; repos with uploaded branding override below.
    icon_url = origin + AP_AVATAR_PATH
    image_url = origin + AP_BANNER_PATH
    if kind == AP_ACTOR_INSTANCE:
        return ap.instance_actor_doc(
            origin, _ap_domain_of(origin), rec["pubkeyPem"],
            icon_url=icon_url, image_url=image_url)
    if kind == AP_ACTOR_USER:
        if not await _ap_user_federates(env, handle):
            return None
        actor_type, display = "Person", handle
        profile_url = origin + "/@" + handle
        # Surface the account's own bio as the fediverse summary so the
        # Mastodon profile card mirrors the /@name page.
        _, account_rec = await _account_row(env, handle)
        bio = clean_string(
            (account_rec or {}).get("profile_bio", "") or "", 500).strip()
        summary = (ap.note_html_from_text(bio) if bio
                   else "ForkMesh profile of @%s." % handle)
    else:
        owner, _, repo = handle.partition(".")
        # Org handles read their repo data from the linked node (issue #388),
        # but display, profile URL and web links stay under the org name below.
        data_owner = await _ap_org_alias_owner(env, owner, repo)
        key_bi = await blind_index(env, data_owner + "/" + repo)
        repo_row = await d1_first(
            env, "SELECT is_private, data FROM repositories WHERE key_bi=?",
            key_bi)
        privacy_reader = globals().get("_repo_is_private")
        hidden = (
            await privacy_reader(env, data_owner, repo)
            if callable(privacy_reader)
            else bool(int((repo_row or {}).get("is_private") or 0))
        )
        if not repo_row or hidden:
            return None
        actor_type, display = "Group", owner + "/" + repo
        repo_web_url = origin + repo_web_href(owner, repo)
        # The actor's canonical `url` is the repo's fediverse profile page (a
        # feed of its federated posts), not the raw git-forge page: Mastodon
        # sends a user who clicks the repo handle — in a mention, or via the
        # profile's external-link — to this `url`, and dropping them onto a
        # code page straight from a social timeline is jarring (adhoc #50).
        # The git page stays one row away ("Repository", below) and is linked
        # prominently on the profile page itself.
        profile_url = origin + "/@" + handle
        # Owner-set About description becomes the fediverse bio.
        catalog_rec = await decrypt_row(env, repo_row.get("data"))
        description = clean_string(
            (catalog_rec or {}).get("description", "") or "", 240).strip()
        summary = (ap.note_html_from_text(description) if description
                   else ("ForkMesh repository %s/%s. Follow for new issues, "
                         "pull requests, discussions and releases.")
                   % (owner, repo))
        # Owner-uploaded branding (repo About tab): logo = avatar, banner =
        # header. updated_at rides along as a cache-buster so Mastodon
        # refetches when the image changes.
        media_rows = await d1_all(
            env, "SELECT kind, updated_at FROM repo_media WHERE repo_bi=?",
            key_bi)
        for media in media_rows or []:
            media_url = "%s/api/repo/%s/%s/media/%s.png?v=%d" % (
                origin, quote(owner), quote(repo), media.get("kind", ""),
                int(media.get("updated_at") or 0))
            if media.get("kind") == "logo":
                icon_url = media_url
            elif media.get("kind") == "banner":
                image_url = media_url
    # Profile metadata rows: the canonical page link (VERIFIABLE — the served
    # page carries a reciprocal rel="me" back to this same URL, which is also
    # the actor's `url`, so Mastodon's link verification turns it green) and
    # the relay this actor lives on (origin-derived, so self-hosted relays
    # advertise their own domain).
    # The verified profile row links the human page ("Repository" = a repo's
    # git page, "Profile" = a user's /@name page). For repos that page is no
    # longer the actor's `url`, so the reciprocal rel="me" that earns the green
    # check lives on the git page (see _serve_repo_page), pointing at this actor.
    web_link = repo_web_url if kind == AP_ACTOR_REPO else profile_url
    attachments = [
        ap.property_value(
            "Repository" if kind == AP_ACTOR_REPO else "Profile", web_link),
        # Plain text, deliberately: an anchor here made every follower
        # server's link verifier fetch the worker-served homepage on each
        # verification round, for a row that can never earn the green check.
        ap.property_text("Relay", _ap_domain_of(origin)),
    ]
    return ap.actor_doc(
        _ap_actor_url(origin, kind, handle), actor_type, handle, display,
        summary, profile_url, rec["pubkeyPem"],
        shared_inbox=origin + "/ap/inbox",
        published_ms=rec.get("createdAt"),
        icon_url=icon_url, image_url=image_url,
        attachments=attachments)


async def _ap_actor_doc_response(env, request, kind, handle):
    if method_name(request) not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    origin = _ap_origin(env, request)
    # Keyed on the canonical actor URL so every route shape that serves this
    # document (/ap/users/x, /@x with an ActivityPub Accept header, /ap/actor)
    # shares one edge entry.
    cache_key = _ap_actor_url(origin, kind, handle)
    cached = await edge_cache_match(cache_key)
    if cached is not None:
        try:
            if int(cached.status) >= 400:
                return cached
        except Exception:
            pass
    await ensure_schema(env)
    if not await _ap_enabled(env):
        return _ap_disabled_response()
    if kind != AP_ACTOR_INSTANCE:
        # Cheap federation gate before minting keys for a 404.
        parsed = await _ap_resolve_local_target(
            env, origin, _ap_actor_url(origin, kind, handle))
        if not parsed:
            return await _ap_negative_response(cache_key)
    if cached is not None:
        return cached
    rec = await _ap_local_actor(env, kind, handle, create=True)
    if not rec:
        return json_response({"error": "unavailable"}, status=503)
    doc = await _ap_build_actor_doc(env, origin, kind, handle, rec)
    if not doc:
        return await _ap_negative_response(cache_key)
    resp = json_response(doc, cache_seconds=300, extra_headers={
        "content-type": ap.ACTIVITY_CONTENT_TYPE})
    await edge_cache_put(cache_key, resp)
    return resp


async def _ap_broadcast_actor_update(env, request, kind, handle):
    """Push an Update(actor) to every follower so remote servers refetch the
    profile (avatar/banner/bio) immediately instead of waiting out their
    cache — this is how a repo's uploaded logo actually appears on Mastodon
    next to existing followers' timelines."""
    if not await _ap_enabled(env):
        return
    actor_bi = await _ap_actor_bi(env, kind, handle)
    rec = await _ap_local_actor(env, kind, handle)
    if not rec:
        return  # never followed / fetched — nothing to update
    origin = _ap_origin(env, request)
    actor_url = _ap_actor_url(origin, kind, handle)
    # Drop the edge-cached actor doc so refetches see the new profile — even
    # with no followers to notify, a remote server may hold the URL and poll
    # it (best-effort: other colos age out within the TTL). The rel=me page
    # the actor points at is edge-cached too (_serve_profile_page /
    # _serve_repo_page), so drop the canonical page keys alongside it.
    await edge_cache_delete(actor_url)
    if kind == AP_ACTOR_USER:
        await edge_cache_delete(origin + "/@" + quote(handle))
        await edge_cache_delete(origin + "/@" + quote(handle) + "/repositories")
        await edge_cache_delete(ACCOUNT_LOOKUP_CACHE_PREFIX + quote(handle))
        # Toggling "make my followers/following public" (Settings) changes
        # what ap_collection_handler returns for the same cached URL, so drop
        # it too — otherwise the old bare-collection response (or stale
        # items) lingers for the rest of its 300s TTL.
        await edge_cache_delete(actor_url + "/followers")
        await edge_cache_delete(actor_url + "/following")
    elif kind == AP_ACTOR_REPO:
        page_owner, _, page_repo = handle.partition(".")
        # The git page carries the rel="me" the green check verifies; the
        # /@owner.repo profile page is the actor's `url` and its post feed.
        await edge_cache_delete(origin + repo_web_href(page_owner, page_repo))
        await edge_cache_delete(origin + "/@" + handle)
    followers = await d1_all(
        env, "SELECT inbox, shared_inbox FROM ap_followers WHERE actor_bi=?",
        actor_bi)
    if not followers:
        return
    doc = await _ap_build_actor_doc(env, origin, kind, handle, rec)
    if not doc:
        return
    now = int(Date.now())
    body_str = json.dumps(ap.update_activity(actor_url, doc, now))
    out_data = await encrypt_row(env, {
        "body": body_str, "actorKind": kind, "actorHandle": handle,
        "actorUrl": actor_url})
    seen = set()
    for follower in followers:
        inbox = ((follower.get("shared_inbox") or "").strip()
                 or (follower.get("inbox") or "").strip())
        if not inbox or inbox in seen:
            continue
        seen.add(inbox)
        await d1_run(
            env,
            "INSERT INTO ap_outbox (inbox, data, attempts, next_ts,"
            " created_at) VALUES (?,?,0,?,?)",
            inbox, out_data, now, now)
    await _ap_drain_outbox(env, AP_IMMEDIATE_DELIVERIES)


async def ap_collection_handler(env, request, kind, handle, which):
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    origin = _ap_origin(env, request)
    collection_url = _ap_actor_url(origin, kind, handle) + "/" + which
    cached = await edge_cache_match(collection_url)
    if cached is not None:
        try:
            if int(cached.status) >= 400:
                return cached
        except Exception:
            pass
    await ensure_schema(env)
    if not await _ap_enabled(env):
        return _ap_disabled_response()
    if kind == AP_ACTOR_USER and not await _ap_user_federates(env, handle):
        return await _ap_negative_response(collection_url)
    if kind == AP_ACTOR_REPO:
        owner, _, repo = handle.partition(".")
        if not await _ap_repo_federates(env, owner, repo):
            return await _ap_negative_response(collection_url)
    if cached is not None:
        return cached
    actor_bi = await _ap_actor_bi(env, kind, handle)
    total = 0
    items = None
    if which == "followers":
        row = await d1_first(
            env, "SELECT COUNT(*) AS c FROM ap_followers WHERE actor_bi=?",
            actor_bi)
        total = (row or {}).get("c", 0) or 0
        # Repo watchers are already public (the About/Watch popover lists
        # them), so repo actors always enumerate. User actors only enumerate
        # when the account owner opted in via Settings — otherwise remote
        # servers correctly read the bare collection as "not made visible".
        show_items = True
        if kind == AP_ACTOR_USER:
            _, account_rec = await _account_row(env, handle)
            show_items = bool((account_rec or {}).get(
                "profile_followers_public"))
        if show_items and total:
            rows = await d1_all(
                env,
                "SELECT follower_id FROM ap_followers WHERE actor_bi=?"
                " ORDER BY created_at DESC LIMIT ?",
                actor_bi, AP_COLLECTION_PAGE_SIZE)
            items = [r.get("follower_id", "") for r in (rows or [])
                     if r.get("follower_id")]
        elif show_items:
            items = []
    elif which == "outbox":
        row = await d1_first(
            env, "SELECT COUNT(*) AS c FROM ap_objects WHERE actor_bi=?",
            actor_bi)
        total = (row or {}).get("c", 0) or 0
    resp = json_response(
        ap.collection_doc(collection_url, total, items=items),
        cache_seconds=300,
        extra_headers={"content-type": ap.ACTIVITY_CONTENT_TYPE})
    await edge_cache_put(collection_url, resp)
    return resp


async def ap_object_handler(env, request, object_uuid):
    if method_name(request) not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    cache_key = _ap_origin(env, request) + "/ap/o/" + object_uuid
    await ensure_schema(env)
    if not await _ap_enabled(env):
        return _ap_disabled_response()
    row = await d1_first(
        env, "SELECT data FROM ap_objects WHERE object_uuid=?", object_uuid)
    rec = await decrypt_row(env, row.get("data")) if row else None
    if not rec or not isinstance(rec.get("note"), dict):
        return json_response({"error": "not_found"}, status=404)
    context = rec.get("context") if isinstance(rec.get("context"), dict) else {}
    segmenter = globals().get("safe_segment")
    context_owner = (
        segmenter(context.get("owner", ""))
        if callable(segmenter) else str(context.get("owner", "") or ""))
    context_repo = (
        segmenter(context.get("repo", ""))
        if callable(segmenter) else str(context.get("repo", "") or ""))
    privacy_reader = globals().get("_repo_is_private")
    if (context_owner and context_repo and callable(privacy_reader)
            and await privacy_reader(env, context_owner, context_repo)):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    cached = await edge_cache_match(cache_key)
    if cached is not None:
        return cached
    doc = dict(rec["note"])
    doc["@context"] = ap.AS_CONTEXT
    resp = json_response(doc, cache_seconds=300, extra_headers={
        "content-type": ap.ACTIVITY_CONTENT_TYPE})
    await edge_cache_put(cache_key, resp)
    return resp


async def ap_object_media_handler(env, request, object_uuid, index):
    # Re-serves one image that was embedded as a "data:" URL in the source
    # issue/comment body, at a real URL — remote servers fetch a Note's
    # attachment URLs directly and can't resolve a data: URI.
    if method_name(request) not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    # Every remote server that receives the Note fetches its attachment URLs,
    # and the bytes are immutable — serve the burst from the colo cache.
    idx = int(index)
    cache_key = "%s/ap/o/%s/media/%d" % (
        _ap_origin(env, request), object_uuid, idx)
    await ensure_schema(env)
    if not await _ap_enabled(env):
        return _ap_disabled_response()
    row = await d1_first(
        env, "SELECT data FROM ap_objects WHERE object_uuid=?", object_uuid)
    rec = await decrypt_row(env, row.get("data")) if row else None
    context = rec.get("context") if isinstance((rec or {}).get("context"), dict) \
        else {}
    segmenter = globals().get("safe_segment")
    context_owner = (
        segmenter(context.get("owner", ""))
        if callable(segmenter) else str(context.get("owner", "") or ""))
    context_repo = (
        segmenter(context.get("repo", ""))
        if callable(segmenter) else str(context.get("repo", "") or ""))
    privacy_reader = globals().get("_repo_is_private")
    if (context_owner and context_repo and callable(privacy_reader)
            and await privacy_reader(env, context_owner, context_repo)):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    media = (rec or {}).get("media") or []
    if idx < 0 or idx >= len(media):
        return json_response({"error": "not_found"}, status=404)
    cached = await edge_cache_match_media(cache_key, "image/png")
    if cached is not None:
        return cached
    item = media[idx]
    try:
        raw = base64.b64decode(item.get("data", ""), validate=True)
    except Exception:
        return json_response({"error": "not_found"}, status=404)
    # Uint8Array.new copies into a JS-owned buffer; a bare _to_js(bytes) view
    # into WASM memory would be read off the GIL (edge-cache put / client
    # stream, after this handler returns) and crash the isolate.
    resp = JsResponse.new(Uint8Array.new(_to_js(bytes(raw))), to_js({
        "status": 200,
        "headers": {
            "content-type": item.get("mediaType", "image/png"),
            "cache-control": "public, max-age=31536000, immutable",
        },
    }))
    await edge_cache_put(cache_key, resp)
    return resp


# --- Outbound HTTP: signed fetch, remote actors, delivery ---------------------

async def _ap_signed_request(key_id, priv_b64, method, url, body_str=None,
                             accept="application/activity+json"):
    # One signed outbound HTTP request (draft-cavage). GETs sign
    # (request-target) host date accept; POSTs add digest + content-type.
    from js import fetch as js_fetch
    parts = urlparse(url)
    if parts.scheme != "https" or not parts.netloc:
        return None
    path = (parts.path or "/") + (("?" + parts.query) if parts.query else "")
    headers = {"host": parts.netloc, "date": ap.http_date(int(Date.now())),
               "accept": accept}
    names = list(ap.SIGNED_HEADERS_GET)
    if body_str is not None:
        headers["digest"] = ap.digest_header_value(body_str.encode())
        headers["content-type"] = "application/activity+json"
        names = list(ap.SIGNED_HEADERS_POST)
    base = ap.signing_string(method, path, headers, names)
    if base is None:
        return None
    signature = await _ap_rsa_sign_b64(priv_b64, base)
    send_headers = {
        "date": headers["date"],
        "accept": accept,
        "user-agent": "forkmesh-relay/1.0 (+https://forkmesh.com)",
        "signature": ap.build_signature_header(key_id, names, signature),
    }
    init = {"method": method, "headers": send_headers}
    if body_str is not None:
        send_headers["digest"] = headers["digest"]
        send_headers["content-type"] = headers["content-type"]
        init["body"] = body_str
    try:
        return await js_fetch(url, to_js(init))
    except Exception:
        return None


async def _ap_instance_key(env):
    origin = _ap_origin(env)
    rec = await _ap_local_actor(
        env, AP_ACTOR_INSTANCE, AP_INSTANCE_HANDLE, create=True)
    if not rec:
        return None, None
    key_id = _ap_actor_url(origin, AP_ACTOR_INSTANCE,
                           AP_INSTANCE_HANDLE) + "#main-key"
    return key_id, rec.get("privkey")


async def _ap_remote_actor(env, actor_id, force_refresh=False):
    # Cached remote actor document (inbox + public key). Fetches are signed
    # with the instance actor so "secure mode" servers answer.
    actor_id = (actor_id or "").split("#")[0].rstrip("/")
    if not actor_id.startswith("https://"):
        return None
    if await _ap_domain_blocked(env, urlparse(actor_id).netloc):
        return None
    row = await d1_first(
        env, "SELECT * FROM ap_remote_actors WHERE actor_id=?", actor_id)
    now = int(Date.now())
    if (row and not force_refresh and row.get("pubkey_pem")
            and now - int(row.get("updated_at") or 0) < AP_REMOTE_ACTOR_TTL_MS):
        return row
    key_id, priv = await _ap_instance_key(env)
    if not priv:
        return row or None
    resp = await _ap_signed_request(key_id, priv, "GET", actor_id)
    if resp is None or int(getattr(resp, "status", 0)) >= 400:
        return row or None
    try:
        doc = json.loads(await resp.text())
    except Exception:
        return row or None
    ess = ap.actor_essentials(doc)
    # The document must describe the URL we fetched (same host at minimum) so
    # a malicious document can't impersonate another server's actor.
    if not ess or urlparse(ess["id"]).netloc != urlparse(actor_id).netloc:
        return row or None
    handle = ess["preferredUsername"]
    if handle:
        handle = handle + "@" + urlparse(ess["id"]).netloc
    await d1_run(
        env,
        "INSERT INTO ap_remote_actors (actor_id, inbox, shared_inbox,"
        " pubkey_pem, handle, display_name, url, updated_at)"
        " VALUES (?,?,?,?,?,?,?,?)"
        " ON CONFLICT(actor_id) DO UPDATE SET inbox=excluded.inbox,"
        " shared_inbox=excluded.shared_inbox, pubkey_pem=excluded.pubkey_pem,"
        " handle=excluded.handle, display_name=excluded.display_name,"
        " url=excluded.url, updated_at=excluded.updated_at",
        actor_id, ess["inbox"], ess["sharedInbox"], ess["pubkeyPem"],
        handle, clean_string(ess["name"], 200), ess["url"], now)
    return {
        "actor_id": actor_id, "inbox": ess["inbox"],
        "shared_inbox": ess["sharedInbox"], "pubkey_pem": ess["pubkeyPem"],
        "handle": handle, "display_name": clean_string(ess["name"], 200),
        "url": ess["url"], "updated_at": now,
    }


async def _ap_deliver_body(env, actor_url, priv_b64, inbox_url, body_str):
    """Returns (status, retry_after_ms). retry_after_ms is 0 unless the
    remote answered 429/503 with a parseable Retry-After — the drain uses it
    as a floor under the normal backoff so a throttling server isn't re-hit
    sooner than it asked."""
    resp = await _ap_signed_request(
        actor_url + "#main-key", priv_b64, "POST", inbox_url,
        body_str=body_str)
    if resp is None:
        return 0, 0
    status = int(getattr(resp, "status", 0))
    retry_after_ms = 0
    if status in (429, 503):
        try:
            raw = (resp.headers.get("retry-after") or "").strip()
        except Exception:
            raw = ""
        if raw.isdigit():
            retry_after_ms = int(raw) * 1000
        elif raw:
            when = ap.parse_http_date_ms(raw)
            if when:
                retry_after_ms = when - int(Date.now())
        retry_after_ms = max(0, min(retry_after_ms, 24 * 60 * 60 * 1000))
    return status, retry_after_ms


async def _ap_drain_outbox(env, limit):
    # Deliver due ap_outbox rows. Success (or a permanently-gone inbox, or the
    # attempt cap) deletes the row; anything else reschedules with backoff.
    if not await _ap_enabled(env):
        return
    now = int(Date.now())
    rows = await d1_all(
        env,
        "SELECT id, inbox, data, attempts FROM ap_outbox WHERE next_ts<=?"
        " ORDER BY next_ts ASC LIMIT ?",
        now, int(limit))
    for row in rows or []:
        if await _ap_domain_blocked(
                env, urlparse(row.get("inbox", "")).netloc):
            await d1_run(env, "DELETE FROM ap_outbox WHERE id=?", row.get("id"))
            continue
        rec = await decrypt_row(env, row.get("data"))
        attempts = int(row.get("attempts") or 0) + 1
        status, retry_after_ms = 0, 0
        if rec and rec.get("body") and rec.get("actorKind"):
            local = await _ap_local_actor(
                env, rec["actorKind"], rec["actorHandle"])
            if local:
                status, retry_after_ms = await _ap_deliver_body(
                    env, rec.get("actorUrl", ""), local["privkey"],
                    row.get("inbox", ""), rec["body"])
        done = (200 <= status < 400) or status in (404, 410)
        if done or not rec or attempts >= ap.MAX_DELIVERY_ATTEMPTS:
            await d1_run(env, "DELETE FROM ap_outbox WHERE id=?", row.get("id"))
        else:
            await d1_run(
                env, "UPDATE ap_outbox SET attempts=?, next_ts=? WHERE id=?",
                attempts,
                now + max(ap.retry_backoff_ms(attempts), retry_after_ms),
                row.get("id"))


# --- Outbound publishing -------------------------------------------------------

async def _ap_publish_repo_event(env, request, owner, repo, kind, event_type,
                                 ref, title, body, author_name,
                                 extra_images=None, manual=False):
    """Queue an automatic repo event, or immediately publish an explicit one.

    Normal issue/PR/discussion/commit/release hooks use the encrypted,
    deterministic, at-most-daily digest queue. Only an owner-authenticated
    caller that explicitly passes ``manual=True`` retains the immediate Note
    path (including its historical repo/user actor fan-out).

    Actor rows remain lazy. Queued digests are published only after a
    fediverse lookup has created the corresponding repository actor."""
    owner = (owner or "").strip().lower()
    repo = (repo or "").strip()
    if not owner or not repo or kind not in AP_FEDI_KINDS:
        return
    if not await _ap_enabled(env):
        return
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        return
    if not manual:
        await _ap_enqueue_repo_digest(
            env, request, owner, repo, kind, event_type, ref, title, body)
        return
    origin = _ap_origin(env, request)
    web_url = origin + repo_web_href(owner, repo)
    author = clean_string(author_name or "", MAX_NODE_NAME).lower()
    # Handles (and thus actor ids) are lowercase-normalized so the same repo
    # always federates as one stable actor URL regardless of link casing.
    # The explicit/manual compatibility path preserves its historical actor
    # fan-out: the repo actor obeys both per-repo switches, while the author's
    # own actor is governed by that user's federation presence.
    settings = await _ap_repo_settings_get(env, owner, repo)
    candidates = []
    if settings["federate"] and settings["broadcastEvents"]:
        candidates.append((AP_ACTOR_REPO, ap.repo_handle(owner, repo.lower())))
    if author and valid_node_name(author):
        candidates.append((AP_ACTOR_USER, author))
    # Attached issue/comment images travel as inline "![name](data:...)"
    # markdown (there's no separate upload channel); pull them out so they
    # federate as real Image attachments instead of unrenderable base64 text.
    clean_body, images = ap.extract_body_images(body or "")
    # Caller-supplied media (the generated pull-request badge PNG, adhoc #44)
    # leads the attachment list so it becomes the visible preview.
    images = [img for img in (extra_images or []) if img] + images
    text = ap.event_note_text(
        kind, event_type, owner, repo, ref, clean_string(title, 240),
        clean_body, author, web_url)
    content_html = ap.note_html_from_text(text)
    ckey = ap.context_key(owner, repo, kind, ref)
    context_bi = await blind_index(env, "ap-context:" + ckey)
    now = int(Date.now())
    queued = False
    for actor_kind, handle in candidates:
        actor_bi = await _ap_actor_bi(env, actor_kind, handle)
        exists = await d1_first(
            env, "SELECT kind FROM ap_actors WHERE actor_bi=?", actor_bi)
        if not exists:
            continue
        followers = await d1_all(
            env,
            "SELECT inbox, shared_inbox FROM ap_followers WHERE actor_bi=?",
            actor_bi)
        if not followers:
            continue
        actor_url = _ap_actor_url(origin, actor_kind, handle)
        object_uuid = _ap_uuid()
        attachments = [
            ap.image_object(
                "%s/ap/o/%s/media/%d" % (origin, object_uuid, i),
                media_type=img["mediaType"])
            for i, img in enumerate(images)]
        note = ap.note_doc(
            origin + "/ap/o/" + object_uuid, actor_url,
            actor_url + "/followers", content_html, now, web_url=web_url,
            attachments=attachments)
        rec = {"note": note,
               "context": {"owner": owner, "repo": repo, "kind": kind,
                           "ref": str(ref), "key": ckey},
               "media": images}
        await d1_run(
            env,
            "INSERT INTO ap_objects (object_uuid, actor_bi, context_bi, data,"
            " published) VALUES (?,?,?,?,?)",
            object_uuid, actor_bi, context_bi,
            await encrypt_row(env, rec), now)
        body_str = json.dumps(ap.create_activity(note))
        out_data = await encrypt_row(env, {
            "body": body_str, "actorKind": actor_kind, "actorHandle": handle,
            "actorUrl": actor_url})
        seen = set()
        for follower in followers:
            inbox = ((follower.get("shared_inbox") or "").strip()
                     or (follower.get("inbox") or "").strip())
            if not inbox or inbox in seen:
                continue
            seen.add(inbox)
            await d1_run(
                env,
                "INSERT INTO ap_outbox (inbox, data, attempts, next_ts,"
                " created_at) VALUES (?,?,0,?,?)",
                inbox, out_data, now, now)
            queued = True
    if queued:
        await _ap_drain_outbox(env, AP_IMMEDIATE_DELIVERIES)


# --- Inbound: the shared/actor inbox --------------------------------------------

async def _ap_forget_remote(env, actor_id):
    await d1_run(env, "DELETE FROM ap_followers WHERE follower_id=?", actor_id)
    await d1_run(env, "DELETE FROM ap_remote_actors WHERE actor_id=?", actor_id)


async def _ap_resolve_local_target(env, origin, url):
    """Map an activity's object URL to a local actor: returns (kind, handle,
    notify_recipient, display) or None."""
    target = ap.parse_local_actor_url(origin, url)
    if not target or target[0] == "instance":
        return None
    if target[0] == "user":
        if not await _ap_user_federates(env, target[1]):
            return None
        return (AP_ACTOR_USER, target[1], target[1], "@" + target[1])
    owner, repo = target[1], target[2]
    if not await _ap_repo_federates(env, owner, repo):
        return None
    return (AP_ACTOR_REPO, ap.repo_handle(owner, repo), owner,
            owner + "/" + repo)


async def _ap_handle_follow(env, request, activity, remote):
    origin = _ap_origin(env, request)
    resolved = await _ap_resolve_local_target(
        env, origin, ap.activity_object_id(activity.get("object")))
    if not resolved:
        return json_response({"error": "not_found"}, status=404)
    kind, handle, recipient, display = resolved
    local = await _ap_local_actor(env, kind, handle, create=True)
    if not local:
        return json_response({"error": "unavailable"}, status=503)
    count = await d1_first(
        env, "SELECT COUNT(*) AS c FROM ap_followers WHERE actor_bi=?",
        local["actorBi"])
    if ((count or {}).get("c", 0) or 0) >= AP_MAX_FOLLOWERS_PER_ACTOR:
        return json_response({"error": "followers_limit"}, status=429)
    now = int(Date.now())
    await d1_run(
        env,
        "INSERT INTO ap_followers (actor_bi, follower_id, inbox, shared_inbox,"
        " follower_handle, created_at) VALUES (?,?,?,?,?,?)"
        " ON CONFLICT(actor_bi, follower_id) DO UPDATE SET"
        " inbox=excluded.inbox, shared_inbox=excluded.shared_inbox,"
        " follower_handle=excluded.follower_handle",
        local["actorBi"], remote["actor_id"], remote.get("inbox", ""),
        remote.get("shared_inbox", "") or "", remote.get("handle", "") or "",
        now)
    # Auto-accept (no manual follow approval), delivered synchronously — one
    # subrequest, and Mastodon marks the follow pending until it arrives.
    actor_url = _ap_actor_url(origin, kind, handle)
    follow_ref = {
        "id": str(activity.get("id", "") or ""),
        "type": "Follow",
        "actor": remote["actor_id"],
        "object": actor_url,
    }
    accept_body = json.dumps(ap.accept_activity(actor_url, follow_ref))
    inbox_url = (remote.get("inbox") or "").strip()
    status, _ = await _ap_deliver_body(
        env, actor_url, local["privkey"], inbox_url, accept_body)
    if inbox_url and not (200 <= status < 400) and status not in (404, 410):
        # The remote server keeps the follow "pending" (spinner) until the
        # Accept lands, and it does NOT retry a Follow we already 202'd — so
        # a lost Accept used to leave the follow stuck forever. Queue it for
        # the cron drain, which retries with the normal backoff.
        out_data = await encrypt_row(env, {
            "body": accept_body, "actorKind": kind, "actorHandle": handle,
            "actorUrl": actor_url})
        await d1_run(
            env,
            "INSERT INTO ap_outbox (inbox, data, attempts, next_ts,"
            " created_at) VALUES (?,?,1,?,?)",
            inbox_url, out_data, now, now)
    follower_label = remote.get("handle") or remote.get("actor_id", "")
    await _best_effort_inbox_side_effect(enqueue_notification(
        env, recipient, "subscribed", "New fediverse follower",
        body="%s is now following %s on the fediverse." % (follower_label,
                                                           display),
        source="fediverse",
        dedupe="ap-follow:%s:%s" % (remote["actor_id"], handle)))
    return json_response({"ok": True}, status=202)


async def _ap_handle_undo(env, request, activity):
    inner = activity.get("object")
    if isinstance(inner, dict) and str(inner.get("type", "")) == "Follow":
        origin = _ap_origin(env, request)
        target = ap.parse_local_actor_url(
            origin, ap.activity_object_id(inner.get("object")))
        if target and target[0] != "instance":
            if target[0] == "user":
                kind, handle = AP_ACTOR_USER, target[1]
            else:
                kind, handle = AP_ACTOR_REPO, ap.repo_handle(
                    target[1], target[2])
            actor_bi = await _ap_actor_bi(env, kind, handle)
            await d1_run(
                env,
                "DELETE FROM ap_followers WHERE actor_bi=? AND follower_id=?",
                actor_bi, ap.activity_object_id(activity.get("actor")))
    return json_response({"ok": True}, status=202)


async def _ap_comment_by_remote_id(env, remote_id):
    """Return (row, decrypted record, blind index) for a remote reply."""
    if not str(remote_id or "").startswith("https://"):
        return None, None, ""
    remote_id_bi = await blind_index(env, "ap-comment:" + str(remote_id))
    row = await d1_first(
        env,
        "SELECT context_bi, remote_id_bi, parent_remote_id_bi, lifecycle,"
        " data, ts FROM ap_comments WHERE remote_id_bi=?",
        remote_id_bi)
    rec = await decrypt_row(env, row.get("data")) if row else None
    return row, rec, remote_id_bi


async def _ap_reply_parent(env, origin, parent_url):
    """Resolve a direct local-object or nested remote-reply parent.

    Remote activities cannot choose a ForkMesh context themselves. Nested
    Lemmy comments inherit the verified parent's encrypted local context.
    """
    parent_uuid = ap.parse_local_object_url(origin, parent_url)
    if parent_uuid:
        row = await d1_first(
            env, "SELECT data, context_bi FROM ap_objects WHERE object_uuid=?",
            parent_uuid)
        parent = await decrypt_row(env, row.get("data")) if row else None
        if parent and isinstance(parent.get("context"), dict):
            return row.get("context_bi"), parent["context"], ""
        return None, None, ""
    row, rec, parent_bi = await _ap_comment_by_remote_id(env, parent_url)
    if row and rec and isinstance(rec.get("context"), dict):
        return row.get("context_bi"), rec["context"], parent_bi
    return None, None, ""


def _ap_activity_is_public(activity):
    """True only when Create/Note addressing explicitly names AS Public."""
    if not isinstance(activity, dict):
        return False
    candidates = [activity]
    embedded = activity.get("object")
    if isinstance(embedded, dict):
        candidates.append(embedded)
    for candidate in candidates:
        for key in ("to", "cc", "audience"):
            values = candidate.get(key, [])
            if not isinstance(values, list):
                values = [values]
            for value in values:
                target = ap.activity_object_id(value)
                if target == ap.AS_PUBLIC:
                    return True
    return False


async def _ap_handle_create(env, request, activity, remote):
    # A remote reply to one of our published Notes becomes a federated comment
    # on the underlying thread; a post that @-mentions one of our repo actors
    # becomes verified public activity awaiting optional, explicit owner
    # review. Nothing in this inbound path files an issue automatically.
    # Anything else is acknowledged and dropped (we host repos, not timelines).
    note = ap.note_essentials(activity.get("object"))
    if not note:
        return json_response({"ok": True}, status=202)
    # HTTP signatures authenticate the sender, not the intended audience.
    # Direct/private Notes must never enter a public thread or World feed.
    if not _ap_activity_is_public(activity):
        return json_response({"ok": True}, status=202)
    # The note's author must be the signing actor (same host is not enough:
    # one compromised account must not be able to speak for a whole server).
    if note["attributedTo"].split("#")[0].rstrip("/") != remote["actor_id"]:
        return json_response({"error": "author_mismatch"}, status=401)
    origin = _ap_origin(env, request)
    context_bi, context, parent_remote_id_bi = await _ap_reply_parent(
        env, origin, note["inReplyTo"])
    if not context:
        mention = _ap_note_repo_mention(origin, note)
        if mention:
            return await _ap_handle_repo_mention(
                env, request, note, remote, mention[0], mention[1])
        return json_response({"ok": True}, status=202)
    # Owner switched federated comments (or the whole actor) off: acknowledge
    # and drop, same as any non-reply — redelivery storms must not 4xx.
    reply_settings = await _ap_repo_settings_get(
        env, context.get("owner", ""), context.get("repo", ""))
    if not reply_settings["federate"] or not reply_settings["acceptComments"]:
        return json_response({"ok": True}, status=202)
    existing_row, existing_rec, remote_id_bi = \
        await _ap_comment_by_remote_id(env, note["id"])
    if existing_row and existing_rec:
        return json_response({"ok": True, "duplicate": True}, status=202)
    count = await d1_first(
        env, "SELECT COUNT(*) AS c FROM ap_comments WHERE context_bi=?",
        context_bi)
    if ((count or {}).get("c", 0) or 0) >= AP_MAX_COMMENTS_PER_THREAD:
        return json_response({"error": "thread_full"}, status=429)
    now = int(Date.now())
    normalized = ap_threads.apply_activity(
        {}, activity, remote_actor=remote, context=context, received_ms=now)
    if not normalized.get("ok"):
        return json_response({"ok": True}, status=202)
    rec = normalized["record"]
    # The HTTP delivery signature was verified above, but that is explicitly
    # not a ForkMesh Ed25519 native-event signature.
    rec["provenance"]["deliverySignatureVerified"] = True
    rec["provenance"]["nativeSignatureVerified"] = False
    await d1_run(
        env,
        "INSERT OR IGNORE INTO ap_comments (context_bi, remote_id_bi,"
        " parent_remote_id_bi, lifecycle, data, ts) VALUES (?,?,?,?,?,?)",
        context_bi, remote_id_bi, parent_remote_id_bi or None,
        rec["lifecycle"], await encrypt_row(env, rec), now)
    if context.get("kind") == "issue":
        reply_owner = context.get("owner", "")
        reply_repo = context.get("repo", "")
        data_owner = await _ap_org_alias_owner(
            env, reply_owner, reply_repo)
        if not await _repo_is_private(env, data_owner, reply_repo):
            public_note = dict(note)
            public_note["content"] = rec.get("body", "")
            await fediverse_mentions_api.record_verified(
                _WorldCommunityRuntime(env, request),
                note=public_note,
                remote=remote,
                actor_owner=reply_owner,
                data_owner=data_owner,
                repo=reply_repo,
                kind="reply",
                context={
                    "ref": context.get("ref", ""),
                    "issueUrl": (
                        origin
                        + repo_web_href(reply_owner, reply_repo)
                        + "/issues/"
                        + str(context.get("ref", ""))
                    ),
                },
                signature_verified=True,
                public_activity=True,
                public_repository=True,
            )
    title = "Fediverse reply on %s/%s %s %s" % (
        context.get("owner", ""), context.get("repo", ""),
        context.get("kind", ""), context.get("ref", ""))
    await _best_effort_inbox_side_effect(enqueue_notification(
        env, context.get("owner", ""), "subscribed", title,
        body="%s: %s" % (rec["author"], rec["body"][:280]),
        repo="%s/%s" % (context.get("owner", ""), context.get("repo", "")),
        href=repo_web_href(context.get("owner", ""), context.get("repo", "")),
        source="fediverse", dedupe="ap-comment:" + note["id"]))
    return json_response({"ok": True}, status=202)


async def _ap_handle_update(env, activity, remote):
    note = ap.note_essentials(activity.get("object"))
    if not note:
        return json_response({"ok": True}, status=202)
    row, existing, _ = await _ap_comment_by_remote_id(env, note["id"])
    if not row or not existing:
        return json_response({"ok": True}, status=202)
    result = ap_threads.apply_activity(
        {note["id"]: existing}, activity, remote_actor=remote,
        context=existing.get("context"), received_ms=int(Date.now()))
    if not result.get("ok"):
        status = 401 if result.get("reason") == "author_mismatch" else 202
        return json_response({"error": result.get("reason")}, status=status)
    if result.get("changed"):
        rec = result["record"]
        rec["provenance"]["deliverySignatureVerified"] = True
        rec["provenance"]["nativeSignatureVerified"] = False
        await d1_run(
            env,
            "UPDATE ap_comments SET lifecycle=?, data=?"
            " WHERE remote_id_bi=?",
            rec["lifecycle"], await encrypt_row(env, rec),
            row.get("remote_id_bi"))
    return json_response(
        {"ok": True, "duplicate": not result.get("changed")}, status=202)


async def _ap_handle_remove(env, activity, remote):
    target_id = ap.activity_object_id(activity.get("object"))
    row, existing, _ = await _ap_comment_by_remote_id(env, target_id)
    if not row or not existing:
        return json_response({"ok": True}, status=202)
    # Lemmy community moderators use a different actor from the comment
    # author. Accept moderation only from the same already-verified instance.
    actor_host = urlparse(remote.get("actor_id", "")).hostname or ""
    if actor_host.lower() != existing.get("sourceInstance", "").lower():
        return json_response({"error": "moderator_instance_mismatch"},
                             status=401)
    result = ap_threads.apply_activity(
        {target_id: existing}, activity, remote_actor=remote,
        context=existing.get("context"), received_ms=int(Date.now()))
    if result.get("changed"):
        rec = result["record"]
        rec["provenance"]["deliverySignatureVerified"] = True
        rec["provenance"]["nativeSignatureVerified"] = False
        await d1_run(
            env,
            "UPDATE ap_comments SET lifecycle=?, data=?"
            " WHERE remote_id_bi=?",
            rec["lifecycle"], await encrypt_row(env, rec),
            row.get("remote_id_bi"))
    return json_response({"ok": True}, status=202)


def _ap_note_repo_mention(origin, note):
    """First Mention tag pointing at one of our repo actors -> (owner, repo)
    (lowercased), else None. Pure string parsing so the inbox can gate on it
    before the signature dance."""
    for href in note.get("mentions", []):
        target = ap.parse_local_actor_url(origin, href)
        if target and target[0] == "repo":
            return target[1], target[2]
    return None


async def _ap_send_mention_reply(env, request, owner, repo, remote, note,
                                 text, issue_number, dedupe_id="",
                                 object_uuid=""):
    """Reply to the mentioning post as the repo actor: a public Note in the
    author's thread with a Mention tag so their server notifies them. Queued
    through ap_outbox so a lost delivery retries on the cron drain. The stored
    object carries the new issue's context, so fediverse replies to OUR reply
    land as federated comments on that issue."""
    origin = _ap_origin(env, request)
    handle = ap.repo_handle(owner, repo)
    local = await _ap_local_actor(env, AP_ACTOR_REPO, handle, create=True)
    if not local:
        return False
    actor_url = _ap_actor_url(origin, AP_ACTOR_REPO, handle)
    now = int(Date.now())
    if not re.fullmatch(r"[a-f0-9]{32}", str(object_uuid or "")):
        object_uuid = _ap_uuid()
    reply = ap.note_doc(
        origin + "/ap/o/" + object_uuid, actor_url, actor_url + "/followers",
        ap.note_html_from_text(text), now,
        web_url=origin + repo_web_href(owner, repo) + "/issues",
        in_reply_to=note["id"])
    # Address the author directly (still public, so the exchange is visible
    # in the thread); the Mention tag is what triggers their notification.
    reply["to"] = [remote["actor_id"]]
    reply["cc"] = [ap.AS_PUBLIC, actor_url + "/followers"]
    tag = {"type": "Mention", "href": remote["actor_id"]}
    if remote.get("handle"):
        tag["name"] = "@" + remote["handle"]
    reply["tag"] = [tag]
    ckey = ap.context_key(owner, repo, "issue", issue_number)
    rec = {"note": reply,
           "context": {"owner": owner, "repo": repo, "kind": "issue",
                       "ref": str(issue_number), "key": ckey},
           "media": []}
    await d1_run(
        env,
        "INSERT OR IGNORE INTO ap_objects "
        "(object_uuid, actor_bi, context_bi, data,"
        " published) VALUES (?,?,?,?,?)",
        object_uuid, await _ap_actor_bi(env, AP_ACTOR_REPO, handle),
        await blind_index(env, "ap-context:" + ckey),
        await encrypt_row(env, rec), now)
    inbox = ((remote.get("inbox") or "").strip()
             or (remote.get("shared_inbox") or "").strip())
    if not inbox:
        return False
    out_data = await encrypt_row(env, {
        "body": json.dumps(ap.create_activity(reply)),
        "actorKind": AP_ACTOR_REPO, "actorHandle": handle,
        "actorUrl": actor_url})
    if dedupe_id:
        dedupe_bi = await blind_index(
            env,
            "ap-mention-followup:" + str(dedupe_id) + ":" + inbox,
        )
        await d1_run(
            env,
            "INSERT OR IGNORE INTO ap_outbox "
            "(inbox, data, attempts, next_ts, created_at, dedupe_bi)"
            " VALUES (?,?,0,?,?,?)",
            inbox, out_data, now, now, dedupe_bi)
    else:
        await d1_run(
            env,
            "INSERT INTO ap_outbox "
            "(inbox, data, attempts, next_ts, created_at)"
            " VALUES (?,?,0,?,?)",
            inbox, out_data, now, now)
    await _ap_drain_outbox(env, 1)
    return True


async def _ap_handle_repo_mention(env, request, note, remote, owner, repo):
    """A verified fediverse post that @-mentions one of our repo actors
    ("@owner.repo@host this button is broken ..."). It becomes sanitized
    public activity in World's manual review feed. It never runs AI, enters an
    issue inbox, or publishes a reply here. Only a later owner-authorized
    preview + explicit create action may queue it, and even then it stays
    pending until the owner node confirms the materialized issue number."""
    dropped = json_response({"ok": True}, status=202)
    data_owner = await _ap_org_alias_owner(env, owner, repo)
    if await _repo_is_private(env, data_owner, repo):
        return dropped
    settings = await _ap_repo_settings_get(env, data_owner, repo)
    if not settings["federate"] or not settings["acceptComments"]:
        return dropped
    # A legacy deployment may already have auto-filed this note. Preserve that
    # historical dedupe marker so a redelivery cannot reintroduce it as a new
    # manual-review candidate.
    mention_bi = await blind_index(env, "ap-mention:" + note["id"])
    seen = await d1_first(
        env, "SELECT ts FROM ap_mentions WHERE remote_id_bi=?", mention_bi)
    if seen:
        return dropped
    text = ap.sanitize_remote_html(note["content"])
    text = re.sub(
        r"(?i)@" + re.escape(ap.repo_handle(owner, repo))
        + r"(?:@[A-Za-z0-9.-]+)?", " ", text)
    text = "\n".join(
        re.sub(r"[ \t]+", " ", line).strip() for line in text.split("\n"))
    text = text.strip()
    if not text:
        return dropped
    public_note = dict(note)
    public_note["content"] = text
    await fediverse_mentions_api.record_verified(
        _WorldCommunityRuntime(env, request),
        note=public_note,
        remote=remote,
        actor_owner=owner,
        data_owner=data_owner,
        repo=repo,
        kind="mention",
        signature_verified=True,
        public_activity=True,
        public_repository=True,
    )
    return dropped


async def _ap_handle_delete(env, activity, remote=None):
    object_id = ap.activity_object_id(activity.get("object"))
    if object_id:
        row, existing, _ = await _ap_comment_by_remote_id(env, object_id)
        if not row or not existing:
            return json_response({"ok": True}, status=202)
        remote_actor_id = (remote or {}).get("actor_id", "")
        if remote_actor_id.rstrip("/") != \
                str(existing.get("authorId", "")).rstrip("/"):
            return json_response({"error": "author_mismatch"}, status=401)
        result = ap_threads.apply_activity(
            {object_id: existing}, activity, remote_actor=remote,
            context=existing.get("context"), received_ms=int(Date.now()))
        if not result.get("ok"):
            return json_response({"error": result.get("reason")},
                                 status=401)
        rec = result["record"]
        rec["provenance"]["deliverySignatureVerified"] = True
        rec["provenance"]["nativeSignatureVerified"] = False
        await d1_run(
            env,
            "UPDATE ap_comments SET lifecycle=?, data=?"
            " WHERE remote_id_bi=?",
            rec["lifecycle"], await encrypt_row(env, rec),
            row.get("remote_id_bi"))
    return json_response({"ok": True}, status=202)


async def ap_inbox_handler(env, request):
    # Shared + per-actor ActivityPub inbox: verify the draft-cavage HTTP
    # signature (keyId fetched from the remote server) and the body digest,
    # then dispatch on activity type. Processing is synchronous — no queues on
    # the free plan — and every path is a handful of D1 statements.
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    if not await _ap_enabled(env):
        return _ap_disabled_response()
    body = await request.text()
    body_bytes = body.encode()
    if len(body_bytes) > AP_MAX_INBOX_BYTES:
        return json_response({"error": "too_large"}, status=413)
    try:
        activity = json.loads(body)
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    if not isinstance(activity, dict):
        return json_response({"error": "invalid_activity"}, status=400)
    activity_type = str(activity.get("type", "") or "")
    actor_id = ap.activity_object_id(activity.get("actor")).rstrip("/")
    origin = _ap_origin(env, request)
    if not actor_id.startswith("https://") or actor_id.startswith(origin + "/"):
        return json_response({"error": "invalid_actor"}, status=401)
    if await _ap_domain_blocked(env, urlparse(actor_id).netloc):
        return json_response({"error": "domain_blocked"}, status=403)
    object_id = ap.activity_object_id(activity.get("object")).rstrip("/")

    # Actor self-delete: the remote document is already gone, so the key can
    # no longer be fetched. Clean up local edges without a wasted subrequest —
    # a spoofed self-delete can at worst drop a follower edge that re-follows.
    # Mastodon broadcasts every account deletion to every instance it has ever
    # seen, so nearly all of these are for actors we don't know: check first
    # (two indexed reads) instead of always issuing two D1 writes.
    if activity_type == "Delete" and object_id == actor_id:
        known = await d1_first(
            env, "SELECT actor_id FROM ap_remote_actors WHERE actor_id=?",
            actor_id)
        if not known:
            known = await d1_first(
                env, "SELECT follower_id FROM ap_followers WHERE follower_id=?",
                actor_id)
        if known:
            await _ap_forget_remote(env, actor_id)
        return json_response({"ok": True}, status=202)

    # Anything we'd acknowledge-and-drop after verifying (Like/Announce/
    # Accept/...) is dropped before the signature dance instead: the
    # verify path costs a signed GET back to the sender's server (plus D1
    # reads/writes to cache its actor), so fediverse-wide Like/boost floods
    # both melted our origin AND hammered Mastodon with actor refetches —
    # the "too many requests" loop of issue #416.
    if activity_type not in (
            "Follow", "Undo", "Create", "Update", "Delete", "Remove"):
        return json_response({"ok": True}, status=202)
    if activity_type == "Create":
        # Two Note shapes matter: replies to our own /ap/o/<uuid> objects
        # (federated comments) and posts whose Mention tags point at one of
        # our repo actors (candidate issue requests). Everything else is
        # dropped here, before the remote-actor fetch (the handler re-checks
        # after verification). A nested Lemmy reply also qualifies when its
        # parent is an already-stored remote reply; that costs one indexed D1
        # read but avoids verifying unrelated fediverse traffic.
        note = ap.note_essentials(activity.get("object"))
        qualifies = bool(note and (
            ap.parse_local_object_url(origin, note["inReplyTo"])
            or _ap_note_repo_mention(origin, note)))
        if note and not qualifies and note["inReplyTo"].startswith("https://"):
            parent_row, _, _ = await _ap_comment_by_remote_id(
                env, note["inReplyTo"])
            qualifies = bool(parent_row)
        if not qualifies:
            return json_response({"ok": True}, status=202)
    elif activity_type == "Update":
        note = ap.note_essentials(activity.get("object"))
        if not note:
            return json_response({"ok": True}, status=202)
        target_row, _, _ = await _ap_comment_by_remote_id(env, note["id"])
        if not target_row:
            return json_response({"ok": True}, status=202)
    elif activity_type == "Remove":
        target_id = ap.activity_object_id(activity.get("object"))
        target_row, _, _ = await _ap_comment_by_remote_id(env, target_id)
        if not target_row:
            return json_response({"ok": True}, status=202)

    parsed_sig = ap.parse_signature_header(
        request.headers.get("signature") or "")
    if not parsed_sig:
        return json_response({"error": "signature_required"}, status=401)
    # The signature must cover the request target and the body digest, or it
    # proves nothing about this delivery.
    if ("(request-target)" not in parsed_sig["headers"]
            or "digest" not in parsed_sig["headers"]):
        return json_response({"error": "weak_signature"}, status=401)
    key_url = parsed_sig["keyId"].split("#")[0].rstrip("/")
    if urlparse(key_url).netloc != urlparse(actor_id).netloc:
        return json_response({"error": "key_actor_mismatch"}, status=401)
    if not ap.digest_matches(request.headers.get("digest") or "", body_bytes):
        return json_response({"error": "digest_mismatch"}, status=401)
    now = int(Date.now())
    date_header = (request.headers.get("date")
                   or request.headers.get("x-date") or "")
    if date_header:
        sent = ap.parse_http_date_ms(date_header)
        if sent and abs(now - sent) > AP_DATE_SKEW_MS:
            return json_response({"error": "date_skew"}, status=401)
    elif parsed_sig.get("created") is None:
        return json_response({"error": "date_required"}, status=401)
    if (parsed_sig.get("created") is not None
            and abs(now - parsed_sig["created"] * 1000) > AP_DATE_SKEW_MS):
        return json_response({"error": "created_skew"}, status=401)

    url = urlparse(request.url)
    path = url.path + (("?" + url.query) if url.query else "")
    headers_map = {}
    for name in parsed_sig["headers"]:
        if name.startswith("("):
            continue
        value = request.headers.get(name)
        if value is None:
            return json_response({"error": "missing_header"}, status=401)
        headers_map[name] = value
    base = ap.signing_string(
        "POST", path, headers_map, parsed_sig["headers"],
        created=parsed_sig.get("created"), expires=parsed_sig.get("expires"))
    if base is None:
        return json_response({"error": "bad_signature_params"}, status=401)
    remote = await _ap_remote_actor(env, key_url)
    verified = bool(remote and remote.get("pubkey_pem")
                    and await _ap_rsa_verify(
                        remote["pubkey_pem"], parsed_sig["signature"], base))
    if not verified:
        # The remote key may have rotated since we cached it — refresh once.
        remote = await _ap_remote_actor(env, key_url, force_refresh=True)
        verified = bool(remote and remote.get("pubkey_pem")
                        and await _ap_rsa_verify(
                            remote["pubkey_pem"], parsed_sig["signature"],
                            base))
    if not verified:
        return json_response({"error": "bad_signature"}, status=401)

    if activity_type == "Follow":
        return await _ap_handle_follow(env, request, activity, remote)
    if activity_type == "Undo":
        return await _ap_handle_undo(env, request, activity)
    if activity_type == "Create":
        return await _ap_handle_create(env, request, activity, remote)
    if activity_type == "Update":
        return await _ap_handle_update(env, activity, remote)
    if activity_type == "Delete":
        return await _ap_handle_delete(env, activity, remote)
    if activity_type == "Remove":
        return await _ap_handle_remove(env, activity, remote)
    # Like/Announce/Accept/... are acknowledged and dropped above.
    return json_response({"ok": True}, status=202)


# --- Client-facing endpoints ----------------------------------------------------

async def repo_media_handler(env, request, owner, repo, media_kind):
    # Owner-uploaded repo branding, served publicly (it is the repo's fediverse
    # avatar/header, fetched by every remote server). Same visibility gate as
    # the actor itself.
    if method_name(request) not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    # Privacy is checked before edge cache lookup: a once-public logo must not
    # remain observable for the cache TTL after its repository becomes private.
    if await _repo_is_private(env, owner, repo):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    # The repo actor's avatar/header: every remote server resolving the actor
    # fetches both images, so a federated post fans out into a burst here.
    # Key includes the ?v=<updated_at> buster from the actor document, so a
    # branding change starts a fresh entry immediately.
    parts = urlparse(request.url)
    cache_key = (_ap_origin(env, request) + parts.path
                 + (("?" + parts.query) if parts.query else ""))
    cached = await edge_cache_match_media(cache_key, "image/png")
    if cached is not None:
        return cached
    repo_bi = await blind_index(env, owner + "/" + repo)
    row = await d1_first(
        env, "SELECT data FROM repo_media WHERE repo_bi=? AND kind=?",
        repo_bi, media_kind)
    rec = await decrypt_row(env, row.get("data")) if row else None
    png_b64 = (rec or {}).get("png", "")
    if not png_b64:
        return json_response({"error": "not_found"}, status=404)
    try:
        raw = base64.b64decode(png_b64)
    except Exception:
        return json_response({"error": "not_found"}, status=404)
    # The actor document busts caches via ?v=<updated_at>, so long edge/browser
    # caching here is safe. Uint8Array.new copies into a JS-owned buffer — a
    # bare _to_js(bytes) view into WASM memory read off the GIL (edge-cache
    # put / client stream, after this returns) crashes the isolate.
    resp = JsResponse.new(Uint8Array.new(_to_js(bytes(raw))), to_js({
        "status": 200,
        "headers": {
            "content-type": "image/png",
            "cache-control": "public, max-age=86400",
        },
    }))
    await edge_cache_put(cache_key, resp)
    return resp


async def repo_card_handler(env, request, owner, repo):
    # Social-preview info card (adhoc #46): the repo page's og:image points
    # here, so a Mastodon/Slack/Twitter unfurl shows the repo's name,
    # description and stats grid (with the ForkMesh mark small in the corner)
    # instead of a full-bleed logo. Public — same visibility gate as the page
    # it previews — and edge-cached so link-preview fetch bursts after a share
    # cost one render per colo per TTL.
    if method_name(request) not in ("GET", "HEAD"):
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    # Check the signed catalog record before cache: privacy changes must revoke
    # cached social previews immediately rather than waiting for their TTL.
    if await _repo_is_private(env, owner, repo):
        return json_response(
            {"error": "not_found"}, status=404, cache_control="no-store")
    parts = urlparse(request.url)
    # Organization aliases are rewritten to their backing node before this
    # handler is dispatched, but the original Request URL deliberately stays
    # untouched.  Keep that public identity on the rendered card while using
    # ``owner`` below for every visibility/catalog/media lookup.  Otherwise an
    # unfurl of /forkmesh/forkmesh would advertise mirror2/forkmesh even though
    # the page, canonical URL and clone URL all belong to the organization.
    display_owner = owner
    display_repo = repo
    public_match = REPO_CARD_RE.match(parts.path)
    if public_match:
        candidate_owner = safe_segment(public_match.group(1))
        candidate_repo = safe_segment(public_match.group(2))
        if candidate_owner and candidate_repo == repo:
            if candidate_owner == owner:
                display_owner = candidate_owner
            elif await _org_repo_node(
                    env, candidate_owner, candidate_repo) == owner:
                display_owner = candidate_owner
            display_repo = candidate_repo
    card_version = parse_qs(parts.query).get("v", [""])[0]
    if not re.fullmatch(r"[A-Za-z0-9._-]{1,80}", card_version):
        card_version = ""
    cache_key = _ap_origin(env, request) + parts.path
    if card_version:
        cache_key += "?v=" + quote(card_version, safe="")
    cached = await edge_cache_match_media(cache_key, "image/png")
    if cached is not None:
        return cached
    repo_bi = await blind_index(env, owner + "/" + repo)
    row = await d1_first(
        env, "SELECT data FROM repositories WHERE key_bi=?", repo_bi)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    rec = (await decrypt_row(env, row.get("data"))) or {}
    stars_row = await d1_first(
        env, "SELECT COUNT(*) AS n FROM repo_stars WHERE repo_bi=?", repo_bi)
    followers = 0
    if await _ap_enabled(env):
        handle = ap.repo_handle(
            str(display_owner).lower(), str(display_repo).lower())
        actor_bi = await _ap_actor_bi(env, AP_ACTOR_REPO, handle)
        follow_row = await d1_first(
            env, "SELECT COUNT(*) AS c FROM ap_followers WHERE actor_bi=?",
            actor_bi)
        followers = (follow_row or {}).get("c", 0) or 0
    # Mirror count the way the network page groups them: catalog records that
    # share this repo's root commit (memoized decrypted catalog, so this full
    # pass doesn't re-decrypt per request).
    mirrors = 0
    try:
        now_ms = int(time.time() * 1000)
        for entry in await _decrypted_public_catalog(env, now_ms):
            if repo_mirror_same_group(rec, entry.get("data")):
                mirrors += 1
    except Exception:
        mirrors = 0
    info = {
        "owner": display_owner,
        "repo": display_repo,
        "description": rec.get("description", ""),
        "branch": rec.get("branch", ""),
        "host": urlparse(_ap_origin(env, request)).netloc or "forkmesh.com",
        "stars": (stars_row or {}).get("n", 0) or 0,
        "mirrors": max(1, mirrors),
        "issues": rec.get("issueCount", ""),
        "pulls": rec.get("pullCount", ""),
        "commits": rec.get("commitCount", ""),
        "branches": rec.get("branchCount", ""),
        "sizeBytes": rec.get("sizeBytes", 0),
        "updatedAt": rec.get("updatedAt", ""),
        "followers": followers,
    }
    png = og_card.render_repo_card(info, time.time())
    # Stats drift, so keep the browser TTL modest; preview crawlers cache the
    # rendered card on their side anyway. Uint8Array.new copies into a JS-owned
    # buffer — a bare _to_js(bytes) view into WASM memory read off the GIL
    # (edge-cache put / client stream, after this returns) crashes the isolate.
    resp = JsResponse.new(Uint8Array.new(_to_js(bytes(png))), to_js({
        "status": 200,
        "headers": {
            "content-type": "image/png",
            "cache-control": "public, max-age=3600",
        },
    }))
    await edge_cache_put(cache_key, resp)
    return resp


async def repo_star_handler(env, request, owner, repo):
    # Star/unstar a repo. A star is a plain per-account preference (not signed
    # by the owner's key), so it lives in its own repo_stars table - the same
    # trust model as profile_follows - rather than inside the owner-signed
    # catalog record. GET is public (count + the caller's own state, if a
    # session is supplied); POST/DELETE require a logged-in session, same as
    # ACCOUNT_FOLLOW_RE.
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST", "DELETE"):
        return json_response({"error": "method_not_allowed"}, status=405)
    if await _repo_is_private(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    repo_bi = await blind_index(env, owner + "/" + repo)

    if method == "GET":
        viewer_bi, viewer_rec = await _account_session_record(env, request)
        starred = False
        if viewer_rec:
            row = await d1_first(
                env,
                "SELECT 1 AS yes FROM repo_stars WHERE repo_bi=? AND account_bi=?",
                repo_bi, viewer_bi)
            starred = bool(row)
        count_row = await d1_first(
            env, "SELECT COUNT(*) AS n FROM repo_stars WHERE repo_bi=?", repo_bi)
        return json_response({
            "ok": True,
            "count": int((count_row or {}).get("n", 0) or 0),
            "starred": starred,
        })

    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    account_bi, account_rec = await _account_session_record(env, request, data)
    if not account_rec:
        return json_response({"error": "invalid_session"}, status=401)

    if method == "POST":
        await d1_run(
            env,
            "INSERT OR IGNORE INTO repo_stars (repo_bi, account_bi, created_at) "
            "VALUES (?,?,?)",
            repo_bi, account_bi, int(Date.now()))
        starred = True
    else:
        await d1_run(
            env, "DELETE FROM repo_stars WHERE repo_bi=? AND account_bi=?",
            repo_bi, account_bi)
        starred = False

    count_row = await d1_first(
        env, "SELECT COUNT(*) AS n FROM repo_stars WHERE repo_bi=?", repo_bi)
    return json_response({
        "ok": True,
        "count": int((count_row or {}).get("n", 0) or 0),
        "starred": starred,
    })


async def fedi_comments_handler(env, request, owner, repo):
    # Remote fediverse replies for one thread, shown alongside (never inside)
    # the Ed25519-signed event log. Public data — same visibility as the
    # thread itself — so the only gate is repo privacy.
    if method_name(request) != "GET":
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    if await _repo_is_private(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    params = parse_qs(urlparse(request.url).query)
    kind = clean_string(params.get("kind", [""])[0], 20).lower()
    ref = clean_string(
        params.get("number", [""])[0] or params.get("ref", [""])[0], 80)
    if kind not in AP_FEDI_KINDS or not ref:
        return json_response({"error": "kind_and_ref_required"}, status=400)
    context_bi = await blind_index(
        env, "ap-context:" + ap.context_key(owner, repo, kind, ref))
    rows = await d1_all(
        env,
        "SELECT data, ts, lifecycle FROM ap_comments WHERE context_bi=?"
        " ORDER BY ts ASC LIMIT 200",
        context_bi)
    normalized_records = {}
    legacy_comments = []
    for row in rows or []:
        rec = await decrypt_row(env, row.get("data"))
        if not rec:
            continue
        source_instance = (
            rec.get("sourceInstance", "")
            or urlparse(rec.get("remoteId", "")).hostname
            or urlparse(rec.get("remoteUrl", "")).hostname
            or "")
        if source_instance and await _ap_domain_blocked(
                env, source_instance):
            continue
        if rec.get("schema") == ap_threads.THREAD_SCHEMA \
                and rec.get("remoteId"):
            normalized_records[rec["remoteId"]] = rec
            continue
        # Pre-0065 rows remain readable and explicitly non-native while normal
        # ActivityPub redelivery gradually upgrades them to lifecycle records.
        legacy_comments.append({
            "author": rec.get("author", ""),
            "authorName": rec.get("authorName", ""),
            "authorUrl": rec.get("authorUrl", ""),
            "body": rec.get("content", ""),
            "url": rec.get("remoteUrl", ""),
            "ts": int(rec.get("ts", 0) or row.get("ts", 0) or 0),
            "federated": True,
            "nativeEvent": False,
            "lifecycle": "active",
            "depth": 0,
            "sourceInstance": source_instance,
            "sourceSoftware": "activitypub",
            "provenance": {
                "source": "activitypub",
                "instance": source_instance,
                "backlink": rec.get("remoteUrl", ""),
                "nativeEvent": False,
                "nativeEventId": "",
                "separationNotice": (
                    "Remote ActivityPub reply; not part of ForkMesh's signed "
                    "native event log."),
            },
        })
    comments = legacy_comments + ap_threads.thread_projection(
        normalized_records)
    comments.sort(key=lambda item: (
        int(item.get("ts", 0) or 0),
        str(item.get("published", "")),
        str(item.get("remoteId", ""))))
    return json_response({"ok": True, "comments": comments},
                         cache_control="public, max-age=30")


async def ap_publish_handler(env, request, owner, repo):
    # Owner-node push of canonical announcements the relay never sees through
    # the signed inboxes (published releases, merged PRs). Same signed-token
    # gate as the inbox drain, so only the owner's key can speak for the repo.
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    if not await _authorize_owner(env, request, owner):
        return json_response({"error": "unauthorized"}, status=401)
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    kind = clean_string(data.get("kind", ""), 20).lower()
    if kind not in AP_FEDI_KINDS:
        return json_response({"error": "invalid_kind"}, status=400)
    default_type = "publish" if kind == "release" else "open"
    event_type = clean_string(
        data.get("eventType", "") or default_type, 20).lower()
    ref = clean_string(
        str(data.get("ref", "") or data.get("number", "")
            or data.get("tag", "")), 80)
    manual = data.get("manual") is True
    await _ap_publish_repo_event(
        env, request, owner, repo, kind, event_type, ref,
        clean_string(data.get("title", ""), 240),
        clean_string(data.get("body", ""), 4000),
        clean_string(data.get("author", "") or owner, MAX_NODE_NAME),
        manual=manual)
    return json_response({
        "ok": True,
        "mode": "manual_immediate" if manual else "daily_digest",
    }, status=202)


async def _authorize_repo_owner_web(env, request, owner, repo, data):
    """True when the caller may manage this repo's fediverse presence from the
    web: the repo owner proven by their session token, or the owner's desktop
    node proving its Ed25519 key —
    the same trust gate as the About editor / ap-publish, with a distinct
    canonical so a signed token can't be replayed onto another endpoint."""
    actor = await _authed_account_name(env, request, data)
    if actor and await _account_owns_node(env, actor, owner):
        return True
    if data.get("ownerSig") and data.get("ts"):
        ts = str(data.get("ts", "") or "")
        owner_pub = await _owner_pubkey(env, owner)
        canonical = ("forkmesh-ap-posts-v1\n" + owner + "\n" + repo +
                     "\n" + ts).encode()
        if owner_pub and _ts_ok(ts) and await ed25519_verify(
                owner_pub, str(data.get("ownerSig", "") or ""), canonical):
            return True
    return False


async def ap_digest_handler(env, request, owner, repo):
    """Owner-only preview of the encrypted automatic-update queue."""
    await ensure_schema(env)
    method = method_name(request)
    if method not in ("GET", "POST"):
        return json_response({"error": "method_not_allowed"}, status=405)
    if await _repo_is_private(env, owner, repo):
        return json_response({"error": "not_found"}, status=404)
    data = {}
    if method == "POST":
        try:
            data = await request.json()
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
    if not await _authorize_repo_owner_web(env, request, owner, repo, data):
        return json_response({"error": "not_authorized"}, status=403)
    settings = await _ap_repo_settings_get(env, owner, repo)
    preview = await _ap_digest_preview(
        env, str(owner).lower() + "/" + str(repo).lower())
    preview.update({
        "ok": True,
        "enabled": bool(
            settings["federate"] and settings["broadcastEvents"]),
        "cadence": "daily",
        "minimumIntervalMs": fedi_digest.DAY_MS,
        "automatedLabel": True,
    })
    return json_response(preview, cache_control="no-store")


async def ap_posts_handler(env, request, owner, repo):
    # Repo-owner fediverse-post management (dashboard "manage posts" dropdown,
    # issue #426): list the repo actor's federated posts, or delete one. A
    # delete broadcasts a Delete(Tombstone) to every follower inbox so the post
    # disappears from Mastodon timelines, then drops the local object. POST-only
    # so the session token rides in the body, never a query string / access log.
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    await ensure_schema(env)
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    if not await _authorize_repo_owner_web(env, request, owner, repo, data):
        return json_response({"error": "not_authorized"}, status=403)
    action = clean_string(data.get("action", "list"), 12).lower()
    handle = ap.repo_handle(owner.lower(), repo.lower())
    actor_bi = await _ap_actor_bi(env, AP_ACTOR_REPO, handle)
    if action == "list":
        rows = await d1_all(
            env,
            "SELECT object_uuid, data, published FROM ap_objects"
            " WHERE actor_bi=? ORDER BY published DESC LIMIT 50", actor_bi)
        posts = []
        for row in rows or []:
            rec = await decrypt_row(env, row.get("data"))
            note = (rec or {}).get("note") or {}
            posts.append({
                "id": row.get("object_uuid"),
                "content": note.get("content") or "",  # our own safe HTML
                "url": note.get("url") or "",
                "published": int(row.get("published") or 0),
            })
        return json_response({"ok": True, "posts": posts})
    if action != "delete":
        return json_response({"error": "bad_action"}, status=400)
    object_uuid = clean_string(data.get("id", ""), 64).strip()
    if not object_uuid:
        return json_response({"error": "missing_id"}, status=400)
    # Only delete a post the repo actor actually authored: the actor_bi filter
    # stops one owner's token from reaching another actor's objects.
    row = await d1_first(
        env,
        "SELECT object_uuid FROM ap_objects WHERE object_uuid=? AND actor_bi=?",
        object_uuid, actor_bi)
    if not row:
        return json_response({"error": "not_found"}, status=404)
    # Drop the local object first: even with federation disabled or zero
    # followers the owner's intent (remove the post) is honored — /ap/o/<uuid>
    # starts 404ing and it vanishes from the repo's fediverse profile feed.
    await d1_run(env, "DELETE FROM ap_objects WHERE object_uuid=?", object_uuid)
    origin = _ap_origin(env, request)
    object_url = origin + "/ap/o/" + object_uuid
    # Drop the edge-parked Note (max-age 300) so the object 404s immediately
    # rather than lingering a cache TTL after the owner deleted it.
    await edge_cache_delete(object_url)
    actor_url = _ap_actor_url(origin, AP_ACTOR_REPO, handle)
    now = int(Date.now())
    queued = False
    if await _ap_enabled(env):
        followers = await d1_all(
            env,
            "SELECT inbox, shared_inbox FROM ap_followers WHERE actor_bi=?",
            actor_bi)
        body_str = json.dumps(ap.delete_activity(
            actor_url, object_url, actor_url + "/followers", now))
        out_data = await encrypt_row(env, {
            "body": body_str, "actorKind": AP_ACTOR_REPO,
            "actorHandle": handle, "actorUrl": actor_url})
        seen = set()
        for follower in followers or []:
            inbox = ((follower.get("shared_inbox") or "").strip()
                     or (follower.get("inbox") or "").strip())
            if not inbox or inbox in seen:
                continue
            seen.add(inbox)
            await d1_run(
                env,
                "INSERT INTO ap_outbox (inbox, data, attempts, next_ts,"
                " created_at) VALUES (?,?,0,?,?)",
                inbox, out_data, now, now)
            queued = True
        if queued:
            await _ap_drain_outbox(env, AP_IMMEDIATE_DELIVERIES)
    return json_response({"ok": True, "deleted": object_uuid,
                          "federated": queued})


# --- Admin: fediverse configuration ------------------------------------------
# Same signed-admin gate as the relay allowlist: the admin proves control of
# their node key and carries is_admin. GET returns the switch + blocklist +
# live stats; POST flips the switch or (un)blocks a remote domain. Blocking a
# domain also purges its followers, cached actors and queued deliveries.

async def _admin_ap_settings(env, request):
    await ensure_schema(env)
    params = parse_qs(urlparse(request.url).query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    ts = clean_string(params.get("ts", [""])[0], 20)
    sig = clean_string(params.get("sig", [""])[0], 200)
    canonical = ("forkmesh-admin-ap-v1\n" + node + "\n" + ts).encode()
    if not await _admin_authorized(env, node, ts, sig, canonical):
        return json_response({"error": "unauthorized"}, status=401)
    settings = await _ap_settings(env, fresh=True)
    stats = {}
    for label, table in (("actors", "ap_actors"),
                         ("followers", "ap_followers"),
                         ("remoteActors", "ap_remote_actors"),
                         ("objects", "ap_objects"),
                         ("comments", "ap_comments"),
                         ("queuedDeliveries", "ap_outbox")):
        row = await d1_first(env, "SELECT COUNT(*) AS c FROM " + table)
        stats[label] = (row or {}).get("c", 0) or 0
    return json_response({
        "ok": True,
        "enabled": settings["enabled"],
        "blockedDomains": sorted(settings["blocked"]),
        "stats": stats,
    })


async def _admin_ap_update(env, request):
    await ensure_schema(env)
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
    ts = clean_string(data.get("ts", ""), 20)
    sig = clean_string(data.get("sig", ""), 200)
    action = clean_string(data.get("action", ""), 20)
    domain = clean_string(data.get("domain", ""), 253).lower()
    if action not in ("enable", "disable", "block", "unblock"):
        return json_response({"error": "bad_action"}, status=400)
    canonical = ("forkmesh-admin-ap-update-v1\n" + node + "\n" + action +
                 "\n" + domain + "\n" + ts).encode()
    audit_target_type = (
        "activitypub_domain"
        if action in ("block", "unblock") else "activitypub")
    audit_target = domain if audit_target_type == "activitypub_domain" else "global"
    if not await _admin_authorized(env, node, ts, sig, canonical):
        await _audit_sensitive_action(
            # `node` is only a claimed identity until the signature verifies;
            # do not attribute a denied request to an account an attacker named.
            env, "", "admin.activitypub_" + action,
            audit_target_type, audit_target, "denied",
            {"reason": "unauthorized", "claimedActorPresent": bool(node)})
        return json_response({"error": "unauthorized"}, status=401)
    now = int(Date.now())
    if action in ("block", "unblock") and not ap.valid_domain(domain):
        await _audit_sensitive_action(
            env, node, "admin.activitypub_" + action,
            audit_target_type, audit_target, "denied",
            {"reason": "invalid_domain"})
        return json_response({"error": "invalid_domain"}, status=400)
    try:
        if action in ("enable", "disable"):
            await d1_run(
                env,
                "INSERT INTO ap_settings (k, v) VALUES ('enabled', ?)"
                " ON CONFLICT(k) DO UPDATE SET v=excluded.v",
                "1" if action == "enable" else "0")
        elif action == "block":
            await d1_run(
                env,
                "INSERT OR IGNORE INTO ap_blocked_domains (domain, added_by,"
                " added_at) VALUES (?,?,?)",
                domain, node, now)
            # Purge existing state from the blocked server. valid_domain
            # limits the charset to [a-z0-9.-], so the LIKE patterns cannot
            # contain SQL wildcards beyond the ones we add.
            for pattern in ("https://" + domain + "/%",
                            "https://%." + domain + "/%"):
                await d1_run(
                    env, "DELETE FROM ap_followers WHERE follower_id LIKE ?",
                    pattern)
                await d1_run(
                    env,
                    "DELETE FROM ap_remote_actors WHERE actor_id LIKE ?",
                    pattern)
                await d1_run(
                    env, "DELETE FROM ap_outbox WHERE inbox LIKE ?", pattern)
        else:
            await d1_run(
                env, "DELETE FROM ap_blocked_domains WHERE domain=?", domain)
    except Exception:
        await _audit_sensitive_action(
            env, node, "admin.activitypub_" + action,
            audit_target_type, audit_target, "failed",
            {"reason": "mutation_error"})
        raise
    await _audit_sensitive_action(
        env, node, "admin.activitypub_" + action,
        audit_target_type, audit_target, "success")
    settings = await _ap_settings(env, fresh=True)
    return json_response({
        "ok": True,
        "enabled": settings["enabled"],
        "blockedDomains": sorted(settings["blocked"]),
    })


async def _owner_signing_pubkeys(env, owner):
    # Every Ed25519 pubkey allowed to sign as this owner's desktop node: the
    # account's primary pubkey plus any still-enabled device key that carries
    # the owner_sign capability. A reinstalled or key-rotated node stores its
    # new keypair in account_devices (login upserts it) but login only sets the
    # primary rec["pubkey"] when it is empty, so it is never promoted. A drain
    # gate that trusted ONLY the primary therefore silently 401'd that node on
    # every GET /api/sync — its issues/PRs/commits/agent-prompts/about edits and
    # chat state stopped reaching it, with no visible error (the node just backs
    # off). The device keys are already stored and account-bound (added only
    # through an authenticated login/claim), so reusing them is the durable node
    # identity the account should keep signing with.
    keys = []
    owner_pub = await _owner_pubkey(env, owner)
    if owner_pub:
        keys.append(owner_pub)
    account_bi = await blind_index(env, owner)
    for device in await _account_devices_list(env, account_bi):
        pub = device.get("pubkey") or ""
        # enabled == active and not revoked (see _account_devices_list); revoking
        # a device in settings closes it out of the drain gate immediately.
        if (pub and pub not in keys and device.get("enabled")
                and "owner_sign" in (device.get("capabilities") or [])):
            keys.append(pub)
    return keys


async def _catalog_publication_key(env, owner, maintainer):
    """Return an account-bound key allowed to sign one catalog publication.

    Catalog publication follows the same durable desktop-node identity policy
    as sync and HTTPS mirror registration. The account must still exist (the
    caller checks that separately), while a reinstalled or headless node may
    publish with its enabled, non-revoked ``owner_sign`` device key without
    replacing the account's primary key.
    """
    maintainer = clean_string(maintainer, 120).strip()
    if not valid_node_pubkey(maintainer):
        return ""
    allowed = await _owner_signing_pubkeys(env, owner)
    return maintainer if maintainer in allowed else ""


async def _verify_owner_signature(env, owner, sig, canonical):
    for pub in await _owner_signing_pubkeys(env, owner):
        if await ed25519_verify(pub, sig, canonical):
            return True
    return False


async def _authorize_owner(env, request, owner):
    if not owner:
        return False
    params = parse_qs(urlparse(request.url).query)
    ts = params.get("ts", [""])[0]
    sig = params.get("sig", [""])[0]
    if not ts or not sig:
        return False
    try:
        skew = abs(int(Date.now()) - int(ts))
    except (TypeError, ValueError):
        return False
    if skew > LOGIN_MAX_SKEW_MS:
        return False
    canonical = ("forkmesh-issues-pull-v1\n" + owner + "\n" + ts).encode()
    return await _verify_owner_signature(env, owner, sig, canonical)


async def _authorize_repo_inbox_owner(env, request, owner, repo):
    """Authorize a repository inbox drain without losing organization context.

    Organization repository URLs are rewritten to their backing node before
    route matching, while the original Worker Request deliberately retains the
    public alias URL.  A desktop organization administrator signs that public
    owner name (the one stored in its RepositoryRecord), not the backing mirror
    node name.  Accept that proof only when the alias is still linked to this
    exact public repository and the signer is a current org owner/admin.

    Private repositories deliberately stay on the direct owner-key path:
    organization membership alone is never a plaintext/private-inbox grant.
    """
    if await _authorize_owner(env, request, owner):
        return True
    try:
        original_url = urlparse(request.url)
        match = REPO_API_PREFIX_RE.match(original_url.path)
    except Exception:
        return False
    if not match:
        return False
    alias_owner = (safe_segment(match.group(1)) or "").lower()
    alias_repo = (safe_segment(match.group(2)) or "").lower()
    owner_l = str(owner or "").strip().lower()
    repo_l = str(repo or "").strip().lower()
    if (
        not alias_owner
        or alias_owner == owner_l
        or alias_repo != repo_l
        or await _repo_is_private(env, owner_l, repo_l)
    ):
        return False

    # Re-check the durable link instead of trusting the short-lived alias memo:
    # revoking/unlinking an organization must revoke drain authority at once.
    org_bi, org_row = await _org_row(env, alias_owner)
    if not org_row:
        return False
    linked = await d1_first(
        env,
        "SELECT 1 AS ok FROM org_repos "
        "WHERE org_bi=? AND repo=? AND node_owner=?",
        org_bi, repo_l, owner_l,
    )
    if not linked:
        return False

    params = parse_qs(original_url.query)
    ts = params.get("ts", [""])[0]
    sig = params.get("sig", [""])[0]
    if not ts or not sig:
        return False
    try:
        skew = abs(int(Date.now()) - int(ts))
    except (TypeError, ValueError):
        return False
    if skew > LOGIN_MAX_SKEW_MS:
        return False
    canonical = (
        "forkmesh-issues-pull-v1\n" + alias_owner + "\n" + ts
    ).encode()
    members = await d1_all(
        env,
        "SELECT name,role FROM org_members "
        "WHERE org_bi=? AND role IN ('owner','admin') "
        "ORDER BY name LIMIT ?",
        org_bi, MAX_ORG_MEMBERS,
    )
    for member in members or []:
        if str(member.get("role") or "") not in ("owner", "admin"):
            continue
        account = clean_string(
            member.get("name") or "", MAX_NODE_NAME
        ).strip().lower()
        if (
            valid_node_name(account)
            and await _verify_owner_signature(
                env, account, sig, canonical
            )
        ):
            return True
    return False


async def _authorize_owner_account(env, owner, data, request=None,
                                   allow_admin=True):
    # Authorize the caller as the repo owner (or a network admin) via their
    # logged-in account SESSION — not a self-asserted name. Used for the website
    # agents tab (adhoc #225). This gate protects immediate, unreviewed side
    # effects: queuing a prompt into a running coding agent on the owner's
    # machine, and reading an agent's transcript / session list. The earlier
    # version trusted data["ownerAccount"] verbatim, so anyone who knew a public
    # owner/repo name could drive those owner-only actions (agent hijack / private
    # data disclosure). The sessionToken (POST body or bearer) must now resolve to
    # the owner account itself or a network admin.
    # Returns (True, None) on success, or (False, error_json_response) on failure.
    _, rec = await _account_session_record(env, request, data)
    actor = (rec.get("name", "") if rec else "").strip().lower()
    if not actor:
        return False, json_response({"error": "not_authorized"}, status=403)
    owns_node = await _account_owns_node(env, actor, owner)
    if not owns_node and not (allow_admin and await _is_admin(env, actor)):
        return False, json_response({"error": "not_authorized"}, status=403)
    return True, None


async def _inbox_author_over_quota(env, table, repo_bi, submitter_bi):
    # True when this submitter already holds MAX_PENDING_PER_AUTHOR un-merged rows
    # in this repo's inbox (table is a fixed literal, safe to interpolate).
    if not submitter_bi:
        return False
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM " + table +
        " WHERE repo_bi=? AND submitter_bi=?",
        repo_bi, submitter_bi,
    )
    return bool(row and (row.get("c", 0) or 0) >= MAX_PENDING_PER_AUTHOR)


async def _best_effort_inbox_side_effect(awaitable):
    # Inbox acceptance is the durable D1 insert. Notification/subscription
    # fan-out is useful, but it must not turn an accepted web submission into 500.
    try:
        await awaitable
    except Exception:
        pass


async def enqueue_notification(env, recipient, kind, title, body="", repo="",
                               href="", actor="", source="", dedupe="",
                               ts=0, meta=None):
    # Account-scoped notification index. It intentionally stores only an encrypted
    # payload plus blind indexes/read state; the canonical event stays in repo git
    # files or a signed inbox table.
    await ensure_schema(env)
    recipient = clean_string(recipient, MAX_NODE_NAME).lower()
    actor = clean_string(actor, MAX_NODE_NAME).lower()
    if not valid_node_name(recipient) or kind not in NOTIFICATION_KINDS:
        return False
    if actor and actor == recipient:
        return False
    now = int(ts or Date.now())
    payload = notification_payload(
        kind, title, body=body, repo=repo, href=href, actor=actor,
        source=source, ts=now, meta=meta)
    recipient_bi = await blind_index(env, recipient)
    dedupe_value = dedupe or (kind + ":" + recipient + ":" + source + ":" +
                              repo + ":" + str(now))
    dedupe_bi = await blind_index(env, "notification:" + recipient + ":" + dedupe_value)
    await d1_run(
        env,
        """INSERT INTO notifications (dedupe_bi, recipient_bi, ts, read_at, data)
           VALUES (?,?,?,?,?)
           ON CONFLICT(dedupe_bi) DO UPDATE SET
             recipient_bi=excluded.recipient_bi,
             ts=excluded.ts,
             data=excluded.data""",
        dedupe_bi, recipient_bi, now, 0, await encrypt_row(env, payload),
    )
    cutoff = now - NOTIFICATION_RETAIN_MS
    await d1_run(
        env,
        "DELETE FROM notifications WHERE recipient_bi=? AND ts < ?",
        recipient_bi, cutoff,
    )
    await d1_run(
        env,
        """DELETE FROM notifications
           WHERE recipient_bi=? AND dedupe_bi NOT IN (
             SELECT dedupe_bi FROM notifications
             WHERE recipient_bi=? ORDER BY ts DESC LIMIT ?
           )""",
        recipient_bi, recipient_bi, MAX_NOTIFICATIONS_PER_RECIPIENT,
    )
    return True


async def notify_mentions(env, owner, repo, actor, title, body, href, source,
                          number=0):
    # number is optional (0 = not a numbered item, e.g. a brand-new PR before
    # the owner assigns it) so every existing call site keeps working
    # unchanged; callers that DO know the number pass it as a keyword so the
    # digest email can show "#N" instead of just a bare title.
    for name in notification_mentions(title, body):
        await enqueue_notification(
            env, name, "mention", "You were mentioned in " + owner + "/" + repo,
            body=(title or body or "Open the repository item to read the mention."),
            repo=owner + "/" + repo, href=href, actor=actor, source=source,
            dedupe="mention:" + owner + "/" + repo + ":" + source + ":" + name +
                   ":" + clean_string(actor, 80) + ":" + clean_string(title, 80) +
                   ":" + clean_string(body, 80),
            meta={"number": number} if number else {},
        )


def _thread_key(owner, repo, source, number):
    try:
        n = int(number or 0)
    except (TypeError, ValueError):
        n = 0
    return ("thread:" + (owner or "") + "/" + (repo or "") + ":" +
            (source or "") + ":" + str(n))


async def subscribe_thread(env, owner, repo, source, number, subscriber,
                           muted=False):
    # Record (or mute) one node's subscription to an issue/PR thread. Auto-called
    # for anyone who comments so they hear about later replies; the signed
    # subscribe endpoint calls it too. An explicit mute is sticky: a later
    # auto-subscribe won't silently re-enable a thread the user muted.
    subscriber = clean_string(subscriber, MAX_NODE_NAME).lower()
    if not valid_node_name(subscriber):
        return False
    try:
        number = int(number or 0)
    except (TypeError, ValueError):
        number = 0
    if number <= 0:
        # A brand-new submission has no durable number yet (the owner assigns it on
        # drain), so its thread key would collide with every other new item.
        return False
    await ensure_schema(env)
    thread_bi = await blind_index(env, _thread_key(owner, repo, source, number))
    subscriber_bi = await blind_index(env, subscriber)
    if not muted:
        existing = await d1_first(
            env,
            "SELECT data FROM thread_subscriptions "
            "WHERE thread_bi=? AND subscriber_bi=?",
            thread_bi, subscriber_bi)
        if existing:
            rec = await decrypt_row(env, existing.get("data", ""))
            if rec and rec.get("muted"):
                return False  # keep an explicit unsubscribe
            return True  # already subscribed
    await d1_run(
        env,
        "INSERT INTO thread_subscriptions (thread_bi, subscriber_bi, ts, data) "
        "VALUES (?,?,?,?) ON CONFLICT(thread_bi, subscriber_bi) DO UPDATE SET "
        "ts=excluded.ts, data=excluded.data",
        thread_bi, subscriber_bi, int(Date.now()),
        await encrypt_row(env, {"node": subscriber, "muted": bool(muted)}),
    )
    return True


async def notify_subscribers(env, owner, repo, source, number, actor, title,
                             body, href):
    # Fan a new comment out to everyone following the thread, minus the commenter
    # and anyone already covered by an @mention on this same event (so a mentioned
    # subscriber gets one notification, not two).
    try:
        number = int(number or 0)
    except (TypeError, ValueError):
        number = 0
    if number <= 0:
        return
    await ensure_schema(env)
    thread_bi = await blind_index(env, _thread_key(owner, repo, source, number))
    rows = await d1_all(
        env, "SELECT data FROM thread_subscriptions WHERE thread_bi=?", thread_bi)
    if not rows:
        return
    mentioned = set(notification_mentions(title, body))
    snippet = clean_string(body or title, 80)
    for row in rows:
        rec = await decrypt_row(env, row.get("data", ""))
        if not rec or rec.get("muted"):
            continue
        name = clean_string(rec.get("node", ""), MAX_NODE_NAME).lower()
        if not valid_node_name(name) or name == actor or name in mentioned:
            continue
        await enqueue_notification(
            env, name, "subscribed", "New activity in " + owner + "/" + repo,
            body=(title or body or "There's a new reply on a thread you follow."),
            repo=owner + "/" + repo, href=href, actor=actor, source=source,
            dedupe="subscribed:" + owner + "/" + repo + ":" + source + ":" +
                   str(number) + ":" + name + ":" + clean_string(actor, 80) +
                   ":" + snippet,
            meta={"number": number, "source": source},
        )


async def notify_pending_inbox(env, owner, repo, source, actor, title, number=0):
    kind = "pull_submitted" if source == "pull" else "pending_inbox"
    label = {
        "issue": "Issue submitted",
        "pull": "Pull request submitted",
        "commit_comment": "Commit comment submitted",
        "discussion": "Discussion submitted",
    }.get(source, "Pending inbox item")
    await enqueue_notification(
        env, owner, kind, label + " for " + owner + "/" + repo,
        body=title or "A signed item is waiting in your desktop inbox.",
        repo=owner + "/" + repo, href=repo_web_href(owner, repo),
        actor=actor, source=source,
        dedupe="pending:" + owner + "/" + repo + ":" + source + ":" +
               clean_string(actor, 120) + ":" + str(number) + ":" + clean_string(title, 120),
        meta={"number": number, "source": source},
    )


async def notify_issue_assignees(env, owner, repo, assignees, actor, title, number=0):
    for assignee in sorted({clean_string(a, MAX_NODE_NAME).lower() for a in (assignees or [])}):
        if not valid_node_name(assignee):
            continue
        await enqueue_notification(
            env, assignee, "issue_assigned",
            "Issue assigned in " + owner + "/" + repo,
            body=title or "You were assigned to an issue.",
            repo=owner + "/" + repo,
            href=repo_web_href(owner, repo),
            actor=actor, source="issue_assigned",
            dedupe="issue-assigned:" + owner + "/" + repo + ":" + str(number) +
                   ":" + assignee,
            meta={"number": number},
        )


async def notify_bounty_event(env, rec, kind):
    owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower()
    repo = clean_string(rec.get("repo", ""), MAX_REPO_SEGMENT)
    if not owner or not repo:
        return
    number = int(rec.get("number", 0) or 0)
    title = "Bounty funded" if kind == "bounty_funded" else "Bounty paid"
    await enqueue_notification(
        env, owner, kind, title + " on " + owner + "/" + repo,
        body=("Issue #" + str(number) + " bounty is " +
              ("funded." if kind == "bounty_funded" else "paid.")),
        repo=owner + "/" + repo,
        href=repo_web_href(owner, repo),
        source="bounty", dedupe=kind + ":" + owner + "/" + repo + ":" + str(number),
        meta={"number": number, "status": rec.get("status", "")},
    )


async def notify_release_published(env, owner, repo, release):
    tag = clean_string((release or {}).get("tag", ""), 128)
    actor = clean_string((release or {}).get("created_by", ""), MAX_NODE_NAME).lower()
    await enqueue_notification(
        env, owner, "release_published",
        "Release " + (tag or "published") + " published",
        body=(release or {}).get("name", "") or ("Release " + tag + " is live."),
        repo=owner + "/" + repo,
        href=repo_web_href(owner, repo),
        actor=actor, source="release",
        dedupe="release:" + owner + "/" + repo + ":" + tag,
        ts=int((release or {}).get("published_at", 0) or 0),
        meta={"tag": tag},
    )


async def _repo_notification_target(env, repo_bi):
    row = await d1_first(env, "SELECT data FROM repositories WHERE key_bi=?", repo_bi)
    if not row:
        return "", ""
    rec = await decrypt_row(env, row.get("data", ""))
    if not rec:
        return "", ""
    return (clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower(),
            clean_string(rec.get("name", ""), MAX_REPO_SEGMENT))


async def notify_host_status(env, repo_bi, kind):
    owner, repo = await _repo_notification_target(env, repo_bi)
    if not owner or not repo:
        return
    title = "Host online" if kind == "host_online" else "Host offline"
    await enqueue_notification(
        env, owner, kind, title + " for " + owner + "/" + repo,
        body=("A desktop host is reachable." if kind == "host_online"
              else "No live host has checked in recently."),
        repo=owner + "/" + repo,
        href=repo_web_href(owner, repo),
        source="host", dedupe=kind + ":" + repo_bi,
    )


async def notify_stale_hosts_offline(env, cutoff):
    rows = await d1_all(env, "SELECT repo_bi FROM host_presence WHERE ts < ?", cutoff)
    for row in rows:
        repo_bi = row.get("repo_bi")
        if repo_bi:
            await notify_host_status(env, repo_bi, "host_offline")


async def notifications_handler(env, request):
    await ensure_schema(env)
    method = method_name(request)
    if method == "GET":
        params = parse_qs(urlparse(request.url).query)
        node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
        if not valid_node_name(node):
            return json_response({"error": "node_required"}, status=400)
        # A notification inbox is private to its owner: only the account itself,
        # proven by its session token (bearer header on this GET), may read it.
        if await _authed_account_name(env, request) != node:
            return json_response({"error": "unauthorized"}, status=401)
        try:
            limit = int(params.get("limit", ["40"])[0])
        except (TypeError, ValueError):
            limit = 40
        limit = max(1, min(limit, MAX_NOTIFICATIONS_FETCH))
        recipient_bi = await blind_index(env, node)
        rows = await d1_all(
            env,
            """SELECT dedupe_bi, ts, read_at, data FROM notifications
               WHERE recipient_bi=? ORDER BY ts DESC LIMIT ?""",
            recipient_bi, limit,
        )
        items = []
        unread = 0
        # Derive the AES key once for the whole page instead of per row: each
        # derivation is its own async WebCrypto round trip, and this endpoint is
        # polled often enough that N sequential round trips (one per notification)
        # measurably drags out the request.
        row_key = await _data_key(env) if rows else None
        for row in rows:
            rec = await decrypt_row(env, row.get("data", ""), key=row_key)
            if not rec:
                continue
            read_at = int(row.get("read_at") or 0)
            rec["id"] = row.get("dedupe_bi", "")
            rec["readAt"] = read_at
            rec["ts"] = int(row.get("ts") or rec.get("ts") or 0)
            if not read_at:
                unread += 1
            items.append(rec)
        return json_response({"ok": True, "notifications": items, "unread": unread})

    if method == "POST":
        try:
            data = await request.json()
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
        if not valid_node_name(node):
            return json_response({"error": "node_required"}, status=400)
        # Marking notifications read mutates the owner's inbox: same session gate
        # as the GET (token from the POST body or an Authorization: Bearer header).
        if await _authed_account_name(env, request, data) != node:
            return json_response({"error": "unauthorized"}, status=401)
        recipient_bi = await blind_index(env, node)
        now = int(Date.now())
        if data.get("all"):
            await d1_run(
                env, "UPDATE notifications SET read_at=? WHERE recipient_bi=?",
                now, recipient_bi)
            return json_response({"ok": True})
        ids = data.get("ids") if isinstance(data.get("ids"), list) else []
        for item_id in ids[:MAX_NOTIFICATIONS_FETCH]:
            item_id = clean_string(item_id, 160)
            if item_id:
                await d1_run(
                    env,
                    "UPDATE notifications SET read_at=? WHERE recipient_bi=? AND dedupe_bi=?",
                    now, recipient_bi, item_id)
        return json_response({"ok": True})

    return json_response({"error": "method_not_allowed"}, status=405)


async def mirror_requests_handler(env, request):
    # Peer mirror requests (issue #385): a repo owner asks another node to
    # mirror their repo, the target's holder accepts or rejects, and on accept
    # that node starts mirroring. The request is parked as a bounded list on the
    # TARGET account record (heartbeat-delivered, like claim/ownership-transfer);
    # accepted entries ride back on the target node's signed heartbeat so its
    # desktop clones the repo. All actions are session-gated (the dashboard
    # login), exactly like the notification inbox this feeds.
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    action = clean_string(data.get("action", "create"), 20) or "create"
    actor = await _authed_account_name(env, request, data)
    if not valid_node_name(actor):
        return json_response({"error": "unauthorized"}, status=401)
    now = int(Date.now())

    if action == "create":
        target = clean_string(data.get("target", ""), MAX_NODE_NAME).lower()
        owner = clean_string(data.get("owner", ""), MAX_NODE_NAME).lower()
        repo = clean_string(data.get("repo", ""), MAX_REPO_SEGMENT).strip()
        if not valid_node_name(target) or not valid_node_name(owner) or not repo:
            return json_response({"error": "bad_request"}, status=400)
        # "Ask a node to mirror YOUR repo": only the repo owner (proven by the
        # session, not a self-asserted body field) may send the request.
        if owner != actor:
            return json_response({"error": "forbidden"}, status=403)
        if target == owner:
            return json_response({"error": "self_target"}, status=400)
        if await _repo_is_private(env, owner, repo):
            # Mirroring is a public-repo affair (the /mirrors payload and clone
            # fallback are public-only); private repos need a share token flow.
            return json_response({"error": "private_repo"}, status=400)
        key_bi = await blind_index(env, owner + "/" + repo)
        repo_row = await d1_first(
            env, "SELECT data FROM repositories WHERE key_bi=?", key_bi)
        if not repo_row:
            return json_response({"error": "repo_not_found"}, status=404)
        target_bi, target_rec = await _account_row(env, target)
        if not target_rec or target_rec.get("status") != "active":
            return json_response({"error": "target_not_found"}, status=404)
        req_id = mirror_request_id(owner, repo, target)
        entry = {"id": req_id, "requester": owner, "owner": owner, "repo": repo,
                 "status": "pending", "ts": now}
        target_rec["mirror_requests"] = add_mirror_request(
            target_rec.get("mirror_requests"), entry)
        await _save_account(env, target_bi, target_rec)
        await enqueue_notification(
            env, target, "mirror_request", "Mirror request from " + owner,
            body=(owner + " asked your node to mirror " + owner + "/" + repo +
                  ". Accept to start mirroring it."),
            repo=owner + "/" + repo, href=repo_web_href(owner, repo),
            actor=owner, source="mirror_request",
            dedupe="mirror_request:" + req_id,
            meta={"requestId": req_id, "owner": owner, "repo": repo,
                  "requester": owner, "state": "pending"})
        return json_response({"ok": True, "requestId": req_id, "status": "pending"})

    if action in ("accept", "reject"):
        req_id = clean_string(data.get("requestId", ""), 200).strip().lower()
        if not req_id:
            return json_response({"error": "bad_request"}, status=400)
        target_bi, target_rec = await _account_row(env, actor)
        if not target_rec:
            return json_response({"error": "unauthorized"}, status=401)
        existing = find_mirror_request(target_rec.get("mirror_requests"), req_id)
        if not existing:
            return json_response({"error": "not_found"}, status=404)
        status = "accepted" if action == "accept" else "rejected"
        updated_list, updated = set_mirror_request_status(
            target_rec.get("mirror_requests"), req_id, status, ts=now)
        target_rec["mirror_requests"] = updated_list
        await _save_account(env, target_bi, target_rec)
        owner = clean_string((updated or {}).get("owner", ""), MAX_NODE_NAME).lower()
        repo = clean_string((updated or {}).get("repo", ""), MAX_REPO_SEGMENT).strip()
        requester = clean_string(
            (updated or {}).get("requester", ""), MAX_NODE_NAME).lower()
        # Let the requester know the outcome (recipient != actor is guaranteed:
        # a request never targets its own owner).
        if requester and owner and repo:
            verb = "accepted" if action == "accept" else "declined"
            tail = (" — their node will start mirroring it shortly."
                    if action == "accept" else ".")
            await enqueue_notification(
                env, requester, "mirror_request",
                actor + " " + verb + " your mirror request",
                body=(actor + " " + verb + " your request to mirror " +
                      owner + "/" + repo + tail),
                repo=owner + "/" + repo, href=repo_web_href(owner, repo),
                actor=actor, source="mirror_request",
                dedupe="mirror_request_reply:" + req_id + ":" + status,
                meta={"requestId": req_id, "owner": owner, "repo": repo,
                      "state": status})
        return json_response({"ok": True, "status": status})

    return json_response({"error": "bad_action"}, status=400)


async def subscribe_handler(env, request, owner, repo):
    # Signed subscribe/unsubscribe for one issue or PR thread (issue #361). The
    # request is signed with the node's own Ed25519 key — the same proof of
    # control as a heartbeat — so only the account holder can watch or mute a
    # thread on their own behalf.
    await ensure_schema(env)
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    node = clean_string(data.get("node", ""), MAX_NODE_NAME).lower()
    source = clean_string(data.get("source", ""), 20)
    if source not in ("issue", "pull"):
        return json_response({"error": "bad_source"}, status=400)
    try:
        number = int(data.get("number", 0))
    except (TypeError, ValueError):
        number = 0
    if number <= 0:
        return json_response({"error": "bad_number"}, status=400)
    subscribed = bool(data.get("subscribed", True))
    ts = clean_string(data.get("ts", ""), 20)
    signature = clean_string(data.get("sig", ""), 200)
    if not valid_node_name(node) or not _ts_ok(ts):
        return json_response({"error": "unauthorized"}, status=401)
    _, rec = await _account_row(env, node)
    pubkey = rec.get("pubkey", "") if rec else ""
    if not pubkey:
        return json_response({"error": "unauthorized"}, status=401)
    canonical = ("forkmesh-subscribe-v1\n" + owner + "/" + repo + "\n" + source +
                 "\n" + str(number) + "\n" + ("1" if subscribed else "0") +
                 "\n" + ts).encode()
    if not await ed25519_verify(pubkey, signature, canonical):
        return json_response({"error": "bad_signature"}, status=401)
    privacy_reader = globals().get("_repo_is_private")
    if callable(privacy_reader) and await privacy_reader(env, owner, repo):
        viewers = {
            node,
            clean_string((rec or {}).get("owner", ""), MAX_NODE_NAME).lower(),
        }
        viewers.discard("")
        allowed = False
        for viewer in viewers:
            if (viewer == str(owner).lower()
                    or await _account_owns_node(env, viewer, owner)):
                allowed = True
                break
        if not allowed:
            repo_bi = await blind_index(env, owner + "/" + repo)
            for viewer in viewers:
                grantee_bi = await blind_index(env, viewer)
                shared = await d1_first(
                    env,
                    "SELECT 1 AS one FROM repo_shares "
                    "WHERE repo_bi=? AND grantee_bi=?",
                    repo_bi, grantee_bi,
                )
                if shared:
                    allowed = True
                    break
        if not allowed:
            return json_response({"error": "not_found"}, status=404)
    await subscribe_thread(env, owner, repo, source, number, node,
                           muted=not subscribed)
    return json_response({"ok": True, "subscribed": subscribed})


async def send_notification_digests(env):
    # Cron: roll each recipient's unread notifications into a single email so a
    # reply reaches people who don't have the app open (issue #361). Only the main
    # relay sends mail; recipients need a verified email and must not have opted
    # out. Best-effort — never raise from the cron.
    if not _is_main_relay(env):
        return
    await ensure_schema(env)
    now = int(Date.now())
    max_age_cut = now - NOTIFICATION_DIGEST_MIN_AGE_MS
    recips = await d1_all(
        env,
        "SELECT DISTINCT recipient_bi FROM notifications "
        "WHERE read_at=0 AND ts<=? LIMIT ?",
        max_age_cut, NOTIFICATION_DIGEST_MAX_RECIPIENTS)
    for recip in recips or []:
        recipient_bi = recip.get("recipient_bi")
        if not recipient_bi:
            continue
        acct = await d1_first(
            env, "SELECT data FROM users WHERE user_bi=?", recipient_bi)
        if not acct:
            acct = await d1_first(
                env, "SELECT data FROM nodes WHERE node_bi=?", recipient_bi)
        if not acct:
            continue
        rec = await decrypt_row(env, acct.get("data", ""))
        if not rec or rec.get("status") != "active":
            continue
        # Use the node owner's email if the node has an owner; otherwise use the node's email.
        email_rec = rec
        owner = clean_string(rec.get("owner", ""), MAX_NODE_NAME).lower()
        if owner:
            _, owner_rec = await _account_row(env, owner)
            if owner_rec and owner_rec.get("status") == "active":
                email_rec = owner_rec
        email = clean_string(email_rec.get("email", ""), 254).strip()
        if not email or not email_rec.get("email_verified"):
            continue
        if email_rec.get("email_notifications") is False:
            continue  # explicit opt-out
        last = int(rec.get("last_digest_ts", 0) or 0)
        if last and now - last < NOTIFICATION_DIGEST_INTERVAL_MS:
            continue
        rows = await d1_all(
            env,
            "SELECT ts, data FROM notifications "
            "WHERE recipient_bi=? AND read_at=0 AND ts>? AND ts<=? "
            "ORDER BY ts DESC LIMIT ?",
            recipient_bi, last, max_age_cut, NOTIFICATION_DIGEST_MAX_ITEMS)
        items = []
        newest = last
        prefs = notification_email_preferences(email_rec)
        for row in rows or []:
            row_ts = int(row.get("ts") or 0)
            newest = max(newest, row_ts)
            payload = await decrypt_row(env, row.get("data", ""))
            if not payload:
                continue
            kind = clean_string(payload.get("kind", ""), 40)
            if not prefs.get(kind, False):
                continue
            items.append(payload)
        if not items:
            if newest > last:
                rec["last_digest_ts"] = newest
                await _save_account(env, recipient_bi, rec)
            continue
        node = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        subject, text, html = _notification_digest_email(node, items)
        if await _send_email(env, email, subject, text, html):
            rec["last_digest_ts"] = newest
            await _save_account(env, recipient_bi, rec)
    await send_general_chat_digests(env)


async def _general_chat_encrypted_message_count(env, since_ts, until_ts):
    await ensure_schema(env)
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM chat_history "
        "WHERE room_key=? AND ts>? AND ts<=?",
        FLAGSHIP_ROOM_KEY, int(since_ts or 0), int(until_ts or 0),
    )
    return int((row or {}).get("c") or 0)


async def send_general_chat_digests(env):
    # The #general room history is retained as encrypted frames. The daily email
    # intentionally reports only a count since the recipient's last digest; it
    # never decrypts or embeds message text.
    if not _is_main_relay(env):
        return
    await ensure_schema(env)
    now = int(Date.now())
    # Recipients come from the authoritative users table (accounts is legacy and
    # is drained as records migrate); it only holds user-kind records, exactly
    # the population eligible for this digest.
    rows = await d1_all(
        env,
        "SELECT user_bi AS name_bi, data FROM users ORDER BY username LIMIT ?",
        GENERAL_CHAT_EMAIL_MAX_RECIPIENTS,
    )
    for row in rows or []:
        name_bi = row.get("name_bi")
        if not name_bi:
            continue
        rec = await decrypt_row(env, row.get("data", ""))
        if not rec or rec.get("status") != "active" or _account_kind(rec) != "user":
            continue
        email = clean_string(rec.get("email", ""), 254).strip()
        if not email or not rec.get("email_verified"):
            continue
        if rec.get("email_notifications") is False:
            continue
        if not notification_email_enabled(rec, "general_chat"):
            continue
        last = int(rec.get("last_general_chat_digest_ts", 0) or 0)
        if last and now - last < GENERAL_CHAT_EMAIL_INTERVAL_MS:
            continue
        since = max(last, now - GENERAL_CHAT_EMAIL_LOOKBACK_MS)
        count = await _general_chat_encrypted_message_count(env, since, now)
        if count <= 0:
            rec["last_general_chat_digest_ts"] = now
            await _save_account(env, name_bi, rec)
            continue
        name = clean_string(rec.get("name", ""), MAX_NODE_NAME).lower()
        subject, text, html = _general_chat_digest_email(name, count)
        if await _send_email(env, email, subject, text, html):
            rec["last_general_chat_digest_ts"] = now
            await _save_account(env, name_bi, rec)


def _forkmesh_email_card_html(heading, intro_html, body_html, footer_html=""):
    # The card is dark, always. It is painted with inline dark styles AND
    # declares itself dark-only via <meta name="color-scheme" content="dark">,
    # so mail clients neither auto-invert it (the way they darken plain light
    # emails in dark mode) nor repaint it to a light theme. An earlier version
    # advertised "light dark" with a prefers-color-scheme:light override, but
    # that override fired in readers whose dark theme doesn't set the OS
    # prefers-color-scheme (e.g. Gmail's dark theme), leaving ForkMesh mail
    # glaringly white while every other email showed dark. Forcing dark keeps
    # the brand card consistent with the rest of a dark inbox.
    return (
        "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\">"
        "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
        "<meta name=\"color-scheme\" content=\"dark\">"
        "<meta name=\"supported-color-schemes\" content=\"dark\">"
        "</head>"
        "<body style=\"margin:0;padding:0;background:#090909\">"
        "<div class=\"fm-bg\" style=\"margin:0;padding:28px 16px;background:#090909;"
        "font-family:'ForkMesh Lato',-apple-system,BlinkMacSystemFont,"
        "Segoe UI,Helvetica,Arial,sans-serif;color:#f5f5f5;line-height:1.55\">"
        "<div class=\"fm-card\" style=\"max-width:560px;margin:0 auto;border:1px solid #313134;"
        "border-radius:8px;background:#141416;padding:24px\">"
        "<p class=\"fm-brand\" style=\"margin:0 0 22px;color:#a3a3a3;font-size:13px;"
        "letter-spacing:0;font-weight:700\">ForkMesh</p>"
        "<h1 class=\"fm-h1\" style=\"margin:0 0 14px;color:#f5f5f5;font-size:24px;"
        "line-height:1.25;font-weight:800\">" + heading + "</h1>"
        "<p class=\"fm-text\" style=\"margin:0 0 18px;color:#d4d4d8;font-size:15px\">" +
        intro_html + "</p>" + body_html +
        (footer_html if footer_html else "") +
        "</div></div></body></html>")


def _format_email_ts(ts_ms):
    """Human-readable UTC timestamp for email bodies, e.g. '2026-07-09 14:32
    UTC'. Sortable/unambiguous rather than locale-flavored, and built from
    time.gmtime/strftime with only the portable %Y/%m/%d/%H/%M directives —
    no timezone database, no platform-specific no-leading-zero flags (those
    aren't guaranteed to work under Pyodide's WASM libc)."""
    try:
        ts_ms = int(ts_ms or 0)
        if ts_ms <= 0:
            return ""
        return time.strftime("%Y-%m-%d %H:%M UTC", time.gmtime(ts_ms / 1000))
    except Exception:
        return ""


def _notification_digest_email(node, items):
    n = len(items)
    subject = ("ForkMesh: " + str(n) + " new notification" +
               ("s" if n != 1 else ""))
    lines = ["Hi " + node + ",", "",
             "You have " + str(n) + " unread ForkMesh notification" +
             ("s" if n != 1 else "") + ":", ""]
    html_items = []
    for it in items:
        title = clean_string(it.get("title", ""), 160) or "Notification"
        body = clean_string(it.get("body", ""), 300)
        repo = clean_string(it.get("repo", ""), 180)
        actor = clean_string(it.get("actor", ""), 120)
        meta_in = it.get("meta")
        try:
            number = int((meta_in or {}).get("number", 0) or 0)
        except (TypeError, ValueError):
            number = 0
        when = _format_email_ts(it.get("ts"))
        # "[owner/repo] #42 Title", falling back gracefully as each piece is
        # missing (a brand-new PR/comment has no number yet; an old digest
        # backlog item might predate actor tracking).
        prefix = ("[" + repo + "] ") if repo else ""
        number_prefix = ("#" + str(number) + " ") if number > 0 else ""
        lines.append("- " + prefix + number_prefix + title)
        # A second indented line for who/when, only when there's something to
        # show — matches the existing "    body" indent convention below.
        who_when = " · ".join(filter(None, [
            ("by " + actor) if actor else "", when]))
        if who_when:
            lines.append("    " + who_when)
        if body:
            lines.append("    " + body)
        meta_html = " &middot; ".join(filter(None, [
            _html_escape("#" + str(number)) if number > 0 else "",
            ("by <strong>" + _html_escape(actor) + "</strong>") if actor else "",
            _html_escape(when) if when else "",
        ]))
        html_items.append(
            "<div class=\"fm-item\" style=\"border:1px solid #313134;border-radius:8px;"
            "background:#0f0f11;padding:12px 14px;margin:0 0 10px\">"
            "<p class=\"fm-item-title\" style=\"margin:0;color:#f5f5f5;font-size:14px;"
            "font-weight:800\">" + _html_escape(prefix + title) + "</p>" +
            ("<p class=\"fm-muted\" style=\"margin:4px 0 0;color:#8a8a93;font-size:12px\">" +
             meta_html + "</p>" if meta_html else "") +
            ("<p class=\"fm-item-body\" style=\"margin:6px 0 0;color:#a3a3a3;font-size:13px;"
             "line-height:1.45\">" + _html_escape(body) + "</p>"
             if body else "") + "</div>")
    lines += ["", "Open ForkMesh to read and reply.",
              "To stop these emails, turn off email notifications in your "
              "profile settings."]
    text = "\n".join(lines)
    html = _forkmesh_email_card_html(
        _html_escape(str(n) + " new notification" + ("s" if n != 1 else "")),
        "Hi <strong class=\"fm-strong\" style=\"color:#f5f5f5\">" +
        _html_escape(node or "there") +
        "</strong>, you have " + str(n) + " unread ForkMesh notification" +
        ("s" if n != 1 else "") + ".",
        "<div style=\"margin:0 0 18px\">" + "".join(html_items) + "</div>"
        "<p class=\"fm-text\" style=\"margin:0 0 16px;color:#d4d4d8;font-size:14px\">Open "
        "ForkMesh to read and reply.</p>",
        "<p class=\"fm-muted\" style=\"margin:22px 0 0;color:#8a8a93;font-size:12px\">To stop "
        "these emails, update email notifications in your profile settings."
        "</p>",
    )
    return subject, text, html


def _general_chat_digest_email(node, count):
    n = int(count or 0)
    subject = ("ForkMesh: " + str(n) + " encrypted #general message" +
               ("s" if n != 1 else ""))
    text = (
        "Hi " + (node or "there") + ",\n\n"
        "You have " + str(n) + " encrypted #general message" +
        ("s" if n != 1 else "") + " since your last digest.\n\n"
        "Message contents are not sent over email. Log in on the web or open "
        "the ForkMesh app to read and reply.\n\n"
        "To stop these emails, update email notifications in your profile settings.")
    html = _forkmesh_email_card_html(
        _html_escape(str(n) + " encrypted #general message" +
                     ("s" if n != 1 else "")),
        "Hi <strong class=\"fm-strong\" style=\"color:#f5f5f5\">" +
        _html_escape(node or "there") +
        "</strong>, #general has encrypted activity since your last digest.",
        "<div class=\"fm-item\" style=\"border:1px solid #313134;border-radius:8px;"
        "background:#0f0f11;padding:14px;margin:0 0 18px\">"
        "<p class=\"fm-item-title\" style=\"margin:0;color:#f5f5f5;font-size:28px;"
        "font-weight:800;line-height:1\">"
        + str(n) + "</p>"
        "<p class=\"fm-item-body\" style=\"margin:8px 0 0;color:#d4d4d8;font-size:14px\">encrypted "
        "#general message" + ("s" if n != 1 else "") + " waiting</p>"
        "</div>"
        "<p class=\"fm-text\" style=\"margin:0;color:#d4d4d8;font-size:14px\">Message contents "
        "are not sent over email. Log in on the web or open the ForkMesh app "
        "to read and reply.</p>",
        "<p class=\"fm-muted\" style=\"margin:22px 0 0;color:#8a8a93;font-size:12px\">To stop "
        "these emails, update email notifications in your profile settings."
        "</p>",
    )
    return subject, text, html


def _html_escape(text):
    return (str(text or "").replace("&", "&amp;").replace("<", "&lt;")
            .replace(">", "&gt;").replace('"', "&quot;"))


def _build_rev(env):
    # The git rev deploy.sh stamps as a Worker var on every production deploy.
    try:
        val = env.BUILD_REV
        if val:
            return str(val)
    except (AttributeError, TypeError):
        pass
    return "dev"


async def poll_handler(env, request):
    # One lightweight digest the client polls on its regular tick INSTEAD of
    # separately re-fetching the full profile (/api/accounts/<name> — avatar and
    # all) and the full notification list every time. It returns only cheap
    # change tokens (a couple of indexed reads, no avatar blob, no per-row
    # notification decrypt); the client fires those heavier fetches only when a
    # token here actually moves. Rolling three per-minute polls into one keeps
    # the hot dashboard path off the Worker CPU limit.
    await ensure_schema(env)
    params = parse_qs(urlparse(request.url).query)
    node = clean_string(params.get("node", [""])[0], MAX_NODE_NAME).lower()
    out = {"ok": True, "rev": _build_rev(env)}
    if not valid_node_name(node):
        return json_response(out)
    # The digest exposes the account's own profile-change token and unread count,
    # so it is returned only to the account itself (session bearer token). Anyone
    # else — or an anonymous poll — gets just the build rev, no per-account data.
    if await _authed_account_name(env, request) != node:
        return json_response(out)
    name_bi, rec = await _account_row(env, node)
    if rec:
        # Token folds the profile fields the dashboard actually re-renders, so a
        # change to any of them (verification, avatar, admin grant, ownership)
        # invalidates it and triggers the full /api/accounts/<name> fetch.
        out["profile"] = {"token": ":".join(str(x) for x in (
            rec.get("status", ""),
            1 if rec.get("email_verified") else 0,
            rec.get("avatar_updated_at", 0) or 0,
            1 if await _is_admin(env, node) else 0,
            rec.get("owner", "") or "",
        ))}
        # Unread count is returned outright so the bell badge updates from the
        # poll alone; token (latest ts + row total) moves on any add/remove so
        # the full list is re-pulled only when it changed.
        notif = await d1_first(
            env,
            "SELECT COUNT(*) AS total, "
            "SUM(CASE WHEN read_at=0 THEN 1 ELSE 0 END) AS unread, "
            "MAX(ts) AS latest FROM notifications WHERE recipient_bi=?",
            name_bi)
        total = int((notif or {}).get("total") or 0)
        unread = int((notif or {}).get("unread") or 0)
        latest = int((notif or {}).get("latest") or 0)
        out["notif"] = {"unread": unread, "token": str(latest) + ":" + str(total)}
    return json_response(out)


def _forkbot_extract_mention_command(message):
    text = clean_string(message, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return ""
    match = re.search(
        r"(?is)(?:^|[^A-Za-z0-9_-])@?forkbot\b[:,]?\s*(.*)$", text)
    return match.group(1).strip() if match else ""


def _forkbot_parse_issue_command(command):
    # Fast, offline path for an explicitly phrased request ("create an issue
    # to ..."). A miss here is NOT a rejection: the handler falls back to the
    # AI intent classifier (_forkbot_ai_interpret), which recognises the same
    # intent from natural phrasing ("forkbot can you track the flaky login
    # test?") and from the surrounding conversation. This regex just spares an
    # AI round trip for the obvious wording and still works when AI is off.
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    # Verb-first ("create an issue to ...") or noun-first ("issue to ...",
    # "bug: ...") — both common phrasings, both answerable offline.
    match = re.match(
        r"(?is)^(?:please\s+|can\s+you\s+|could\s+you\s+|would\s+you\s+|"
        r"pls\s+|plz\s+)*"
        r"(?:(?:create|open|file|make|report|log|raise|add|track|submit)\s+)?"
        r"(?:an?\s+|a\s+new\s+)?"
        r"(?:issue|bug|ticket|task|feature\s+request)\b"
        r"\s*(?:(?:to|for|about|that|saying|called|titled|re|regarding)\s+|"
        r"[:\-]\s*)?"
        r"(.+)$",
        text,
    )
    if not match:
        return None
    description = re.sub(r"\s+", " ", match.group(1)).strip(" .:-")
    if len(description) < 3:
        return None
    return {"description": description}


def _forkbot_command_hints_issue(command):
    """Cheap offline signal that a ForkBot mention is about recording work —
    used ONLY when the AI classifier is unreachable, so an unreachable model
    degrades to filing the raw request instead of refusing with the help hint
    (that refusal is exactly what users saw while the AI binding was silently
    failing)."""
    return bool(re.search(
        r"(?i)\b(issues?|bugs?|tickets?|tasks?|todo|feature\s+request|"
        r"create|open|file|track|log|report)\b",
        clean_string(command, FORKBOT_MAX_COMMAND)))


def _forkbot_polite_prefix():
    # Shared lead-in the offline parsers strip: "please can you ..." etc.
    return (r"(?:please\s+|can\s+you\s+|could\s+you\s+|would\s+you\s+|"
            r"pls\s+|plz\s+)*")


def _forkbot_parse_list_command(command):
    """Offline fast path for "list the last N issues" phrasings. Mirrors the
    create-issue fast path: a miss is NOT a rejection (the AI classifier still
    gets a shot at natural wording), a hit spares the AI round trip and keeps
    the feature working when AI is off. Returns {"count": n} or None."""
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    match = re.match(
        r"(?is)^" + _forkbot_polite_prefix() +
        r"(?:list|show(?:\s+me)?|display|give\s+me|what\s+are)\s+"
        r"(?:the\s+)?(?:last|latest|most\s+recent|recent|newest)?\s*"
        r"(\d{1,3})?\s*(?:few\s+)?issues\b",
        text,
    )
    if not match:
        return None
    try:
        count = int(match.group(1) or FORKBOT_LIST_DEFAULT)
    except (TypeError, ValueError):
        count = FORKBOT_LIST_DEFAULT
    return {"count": max(1, min(count, FORKBOT_LIST_MAX))}


def _forkbot_parse_count_command(command):
    """Offline fast path for "how many issues are there" phrasings. These ask
    for a total, not a listing, so they must not fall through to the list
    parser above (which would hand back a few issues and never say how many
    exist in total). Returns True or None."""
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    match = re.match(
        r"(?is)^" + _forkbot_polite_prefix() +
        r"(?:how\s+many\s+issues\b(?:\s+are\s+there|\s+exist|"
        r"\s+do\s+we\s+have)?|"
        r"(?:what(?:'s|\s+is)\s+the\s+)?(?:number|count)\s+of\s+issues|"
        r"issue\s+count)\s*[?.!]*$",
        text,
    )
    return {} if match else None


def _forkbot_parse_search_command(command):
    """Offline fast path for "search issues for X" phrasings. Requires the
    word issue(s) so a bare "find the bug" still flows to the create/AI paths.
    Returns {"query": text} or None."""
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    match = re.match(
        r"(?is)^" + _forkbot_polite_prefix() +
        r"(?:search|find|look\s+(?:for|up)|grep)\s+"
        r"(?:the\s+|any\s+|all\s+)?(?:open\s+|closed\s+)?issues?\b\s*"
        r"(?:(?:for|about|regarding|matching|mentioning|containing|on|with)"
        r"\s+)?[:\-]?\s*(.+)$",
        text,
    )
    if not match:
        return None
    query = re.sub(r"\s+", " ", match.group(1)).strip(" .:-\"'")
    if len(query) < 2:
        return None
    return {"query": query[:100]}


def _forkbot_parse_agent_command(command):
    """Offline fast path for "start an agent on the latest issue / issue #N".
    Returns {"issueNumber": n} (0 = the most recent issue) or None."""
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    match = re.match(
        r"(?is)^" + _forkbot_polite_prefix() +
        r"(?:start|run|launch|kick\s+off|spin\s+up|put|assign|set|sic)\s+"
        r"(?:an?\s+)?(?:coding\s+|code\s+)?agent\s+"
        r"(?:on|to|at|for|onto|against)?\s*(?:the\s+)?"
        r"(?:most\s+recent|latest|newest|last|recent)?\s*"
        r"issue\s*(?:#\s*)?(\d+)?",
        text,
    )
    if not match:
        return None
    try:
        number = int(match.group(1) or 0)
    except (TypeError, ValueError):
        number = 0
    return {"issueNumber": number}


def _forkbot_parse_show_command(command):
    """Offline fast path for "show issue #N" / "show the latest issue".
    "open issue ..." intentionally stays with the create-issue parser (there
    "open" is the filing verb). Returns {"issueNumber": n} (0 = latest) or
    None."""
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip()
    if not text:
        return None
    match = re.match(
        r"(?is)^" + _forkbot_polite_prefix() +
        r"(?:show(?:\s+me)?|view|describe|summarize|"
        r"what(?:'s|\s+is)\s+(?:in|the\s+status\s+of))\s+"
        r"(?:the\s+)?(?:most\s+recent\s+|latest\s+|newest\s+|last\s+)?"
        r"issue\s*(?:#\s*)?(\d+)?\s*$",
        text,
    )
    if not match:
        return None
    try:
        number = int(match.group(1) or 0)
    except (TypeError, ValueError):
        number = 0
    return {"issueNumber": number}


def _forkbot_parse_help_command(command):
    text = clean_string(command, FORKBOT_MAX_COMMAND).strip().lower()
    if not text:
        return False
    return bool(re.match(
        r"^(?:help|\?+|what\s+can\s+you\s+do|what\s+do\s+you\s+do|"
        r"commands|usage)\s*[!.?]*$", text))


def _forkbot_help_message():
    # Also the fallback reply for anything ForkBot could not map to an action,
    # so it doubles as discoverable usage text.
    return (
        "I can open an issue from the conversation (\"forkbot open an issue "
        "for the flaky login test\"), list recent issues (\"forkbot list the "
        "last 5 issues\" - up to %d), say how many issues there are "
        "(\"forkbot how many issues are there?\"), search issues (\"forkbot "
        "search issues for relay retries\"), show one issue (\"forkbot show "
        "issue #12\"), and - for the repo owner - start a coding agent "
        "(\"forkbot start an agent on the latest issue\")." % FORKBOT_LIST_MAX
    )


def _forkbot_context_text(context):
    """Flatten the recent conversation the client forwarded into a short,
    plain-text transcript for the AI. Each entry is {sender, text}; the client
    already excludes ForkBot's own lines and caps the count, but we bound it
    again here so a hostile client can't blow the prompt budget."""
    if not isinstance(context, list):
        return ""
    lines = []
    for entry in context[-FORKBOT_CONTEXT_MAX_MESSAGES:]:
        if not isinstance(entry, dict):
            continue
        sender = clean_string(entry.get("sender", ""), MAX_NODE_NAME).strip() or "user"
        text = clean_string(entry.get("text", ""), FORKBOT_CONTEXT_MAX_CHARS).strip()
        if not text:
            continue
        lines.append("%s: %s" % (sender, text))
    return "\n".join(lines)


def _forkbot_issue_title(description):
    text = re.sub(r"\s+", " ", clean_string(description, 240)).strip(" .:-")
    if not text:
        return "Issue from #general"
    for sep in (". ", "! ", "? "):
        idx = text.find(sep)
        if 12 <= idx <= 120:
            text = text[:idx]
            break
    if len(text) > 120:
        text = text[:117].rstrip() + "..."
    return text or "Issue from #general"


def _forkbot_fallback_issue_fields(description):
    body = clean_string(description, MAX_ISSUE_BYTES).strip()
    title = _forkbot_issue_title(body)
    return {"title": title, "body": body}


def _forkbot_json_object_from_text(text):
    if not isinstance(text, str):
        return None
    raw = text.strip()
    if not raw:
        return None
    try:
        parsed = json.loads(raw)
        return parsed if isinstance(parsed, dict) else None
    except Exception:
        pass
    start = raw.find("{")
    end = raw.rfind("}")
    if start >= 0 and end > start:
        try:
            parsed = json.loads(raw[start:end + 1])
            return parsed if isinstance(parsed, dict) else None
        except Exception:
            return None
    return None


def _forkbot_clean_ai_issue_fields(parsed):
    if not isinstance(parsed, dict):
        return None
    title = clean_string(parsed.get("title", ""), 240).strip()
    body = clean_string(parsed.get("body", ""), MAX_ISSUE_BYTES).strip()
    if not title or not body:
        return None
    return {"title": _forkbot_issue_title(title), "body": body}


async def _forkbot_run_ai(env, system_prompt, user_prompt, schema=None):
    """Run the Workers AI chat model and return the raw response text/object
    (or None). Shared by the issue-drafting and intent-classification helpers.

    When `schema` is given, the first attempt requests Workers AI JSON mode
    (response_format json_schema) so a supporting model MUST return valid
    JSON; models/plans without JSON mode fall back to a plain prompt-only
    attempt. Every failure path logs the reason — the original implementation
    swallowed all exceptions, which left ForkBot silently degraded (raw-echo
    issue titles, natural requests answered with the help hint) with nothing
    in the logs to say why."""
    ai = getattr(env, "AI", None)
    if ai is None or js_nullish(ai) or not hasattr(ai, "run"):
        await log_error(
            env, 500, "AI", "forkbot/ai",
            "ForkBot AI unavailable: env.AI binding is missing")
        return None
    model = clean_string(getattr(env, "FORKBOT_AI_MODEL", ""), 120) or \
        FORKBOT_AI_DEFAULT_MODEL
    base_payload = {
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": user_prompt},
        ],
        "max_tokens": 512,
    }
    attempts = []
    if schema:
        with_format = dict(base_payload)
        with_format["response_format"] = {
            "type": "json_schema", "json_schema": schema,
        }
        attempts.append(with_format)
    attempts.append(base_payload)
    result = None
    ran = False
    last_error = None
    for payload in attempts:
        try:
            result = await ai.run(model, to_js(payload))
            ran = True
            break
        except Exception as error:
            last_error = error
            continue
    if not ran:
        await log_error(
            env, 500, "AI", "forkbot/ai",
            "ForkBot AI call failed (%s): %s"
            % (model, _safe_error_text(last_error)[:300]))
        return None
    try:
        if hasattr(result, "to_py"):
            result = result.to_py()
    except Exception:
        pass
    if isinstance(result, dict):
        for key in ("response", "text", "output"):
            value = result.get(key)
            if isinstance(value, str):
                return value
            # JSON mode returns the parsed object under "response".
            if isinstance(value, dict):
                return value
        # Some bindings return the parsed object directly rather than a text
        # field; hand the dict back so the caller can read fields off it.
        return result
    if isinstance(result, str):
        return result
    await log_error(
        env, 500, "AI", "forkbot/ai",
        "ForkBot AI returned an unusable %s response (%s)"
        % (type(result).__name__, model))
    return None


# JSON schemas for Workers AI JSON mode: a supporting model is FORCED to emit
# exactly these shapes, eliminating the markdown-fence / chatty-preamble
# failure modes small instruct models are prone to.
FORKBOT_ISSUE_FIELDS_SCHEMA = {
    "type": "object",
    "properties": {
        "title": {"type": "string"},
        "body": {"type": "string"},
    },
    "required": ["title", "body"],
}
FORKBOT_INTENT_SCHEMA = {
    "type": "object",
    "properties": {
        "intent": {"type": "string", "enum": [
            "create_issue", "list_issues", "count_issues", "search_issues",
            "show_issue", "start_agent", "help", "none"]},
        "title": {"type": "string"},
        "body": {"type": "string"},
        "count": {"type": "integer"},
        "query": {"type": "string"},
        "issueNumber": {"type": "integer"},
    },
    "required": ["intent"],
}


async def _forkbot_ai_issue_fields(env, description, context_text=""):
    system_prompt = (
        "You turn a chat request into a ForkMesh issue. Use the conversation "
        "context to resolve what the user is referring to. Respond with ONLY "
        'one JSON object, no other text: {"title":"short summary",'
        '"body":"what is wrong or what needs doing, with detail from the '
        'conversation"}.'
    )
    user_prompt = clean_string(description, FORKBOT_MAX_COMMAND)
    if context_text:
        user_prompt = (
            "Recent conversation:\n" + context_text +
            "\n\nRequest: " + user_prompt)
    result = await _forkbot_run_ai(
        env, system_prompt, user_prompt, schema=FORKBOT_ISSUE_FIELDS_SCHEMA)
    if result is None:
        return None
    if isinstance(result, dict):
        return _forkbot_clean_ai_issue_fields(result)
    return _forkbot_clean_ai_issue_fields(_forkbot_json_object_from_text(result))


async def _forkbot_ai_interpret(env, command, context_text=""):
    """Decide from meaning (not fixed phrasing) which ForkBot action the user
    wants — pulling the subject from the recent conversation when the mention
    itself is only a pointer ("forkbot log that").

    Returns one of:
      {"intent": "create_issue", "title", "body"}
      {"intent": "list_issues", "count"}
      {"intent": "count_issues"}
      {"intent": "search_issues", "query"}
      {"intent": "show_issue", "issueNumber"}   (0 = the most recent issue)
      {"intent": "start_agent", "issueNumber"}  (0 = the most recent issue)
      {"intent": "help"} / {"intent": "none"}
    or None when the model is unavailable/unparseable — callers treat None as
    "AI could not decide" and fall back to a heuristic, NOT as a refusal."""
    system_prompt = (
        "You are ForkBot, an assistant in a ForkMesh chat room. Classify what "
        "the user wants and respond with ONLY one JSON object, no other text. "
        "Actions: record a bug/task/feature as an issue -> "
        '{"intent":"create_issue","title":"short summary","body":"the problem '
        'or task, with detail from the conversation"}; list recent issues -> '
        '{"intent":"list_issues","count":N} (how many they asked for, 5 if '
        "unspecified); asking for a TOTAL count of issues rather than a list "
        '-> {"intent":"count_issues"}; search existing issues for a topic -> '
        '{"intent":"search_issues","query":"the search words"}; show one '
        'existing issue -> {"intent":"show_issue","issueNumber":N} (0 for the '
        "most recent); start a coding agent working on an issue -> "
        '{"intent":"start_agent","issueNumber":N} (0 for the most recent); '
        'asking what ForkBot can do -> {"intent":"help"}. When in doubt and '
        "the message describes a problem, task, or request, treat it as "
        "create_issue; a greeting or small talk is "
        '{"intent":"none"}. Examples: "issue to add dark mode" -> '
        '{"intent":"create_issue","title":"Add dark mode","body":"Add dark '
        'mode."}; "what came in this week?" -> '
        '{"intent":"list_issues","count":5}; "how many issues are there?" -> '
        '{"intent":"count_issues"}; "anything about relay retries?" '
        '-> {"intent":"search_issues","query":"relay retries"}; "get an '
        'agent going on that new issue" -> '
        '{"intent":"start_agent","issueNumber":0}; "hello!" -> '
        '{"intent":"none"}.'
    )
    user_prompt = command
    if context_text:
        user_prompt = (
            "Recent conversation:\n" + context_text +
            "\n\nMessage to ForkBot: " + command)
    result = await _forkbot_run_ai(
        env, system_prompt, user_prompt, schema=FORKBOT_INTENT_SCHEMA)
    if result is None:
        return None
    parsed = result if isinstance(result, dict) else \
        _forkbot_json_object_from_text(result)
    if not isinstance(parsed, dict):
        return None
    intent = clean_string(parsed.get("intent", ""), 40).strip().lower()
    if intent == "list_issues":
        try:
            count = int(parsed.get("count", FORKBOT_LIST_DEFAULT)
                        or FORKBOT_LIST_DEFAULT)
        except (TypeError, ValueError):
            count = FORKBOT_LIST_DEFAULT
        return {"intent": "list_issues",
                "count": max(1, min(count, FORKBOT_LIST_MAX))}
    if intent == "count_issues":
        return {"intent": "count_issues"}
    if intent == "search_issues":
        query = clean_string(parsed.get("query", ""), 100).strip()
        if not query:
            return None
        return {"intent": "search_issues", "query": query}
    if intent in ("show_issue", "start_agent"):
        try:
            number = int(parsed.get("issueNumber", 0) or 0)
        except (TypeError, ValueError):
            number = 0
        return {"intent": intent, "issueNumber": max(0, number)}
    if intent == "help":
        return {"intent": "help"}
    if intent not in ("create_issue", "none"):
        # Some models omit the field but still return title/body when they
        # decided to draft an issue; treat a usable draft as create_issue.
        intent = "create_issue" if (parsed.get("title") or parsed.get("body")) \
            else "none"
    if intent != "create_issue":
        return {"intent": "none"}
    fields = _forkbot_clean_ai_issue_fields(parsed)
    if not fields:
        # The model wanted an issue but produced no usable draft — let the
        # caller's heuristic take over instead of refusing.
        return None
    return {"intent": "create_issue", "title": fields["title"],
            "body": fields["body"]}


async def _forkbot_repo_gateway_json(env, owner, repo, action_query):
    """Read public repository data through the normal HTTPS mirror gateway."""
    owner = safe_segment(owner)
    repo = safe_segment(repo)
    action = clean_string(action_query, 400).lstrip("/")
    if (
        not owner or not repo
        or not re.match(
            r"^(tree|blobs|blob|raw|history|commit|branches|search|stats|sizes)"
            r"(?:\?|$)",
            action,
        )
    ):
        return None
    try:
        origin = _public_base_url(env).rstrip("/")
        response = await asyncio.wait_for(
            js_fetch(
                "%s/api/repo/%s/%s/%s"
                % (origin, quote(owner), quote(repo), action)
            ),
            timeout=FORKBOT_GATEWAY_TIMEOUT_MS / 1000,
        )
        if int(getattr(response, "status", 0) or 0) != 200:
            return None
        data = await response.json()
        if hasattr(data, "to_py"):
            data = data.to_py()
        return data if isinstance(data, dict) else None
    except Exception:
        return None


def _forkbot_missing_tree(data):
    # The host answers "that folder isn't in git yet" in a few git-flavored
    # ways (same set the dashboard's isMissingMirrorFolder knows); all of them
    # mean "no issues filed", not "host unreachable".
    error = str((data or {}).get("error", "")).lower()
    return any(marker in error for marker in (
        "not_found", "not a valid object name", "pathspec",
        "does not exist", "unknown revision"))


def _forkbot_issue_json_path(number, subdir=""):
    # Issues are split by status into .forkmesh/issues/open/<N>/ and
    # .forkmesh/issues/closed/<N>/ (adhoc #14); pre-split mirrors keep the
    # numbered folder directly under the root (subdir "").
    base = ".forkmesh/issues"
    if subdir:
        base += "/" + subdir
    return "%s/%d/issue-%d.json" % (base, int(number), int(number))


def _forkbot_issue_json_candidates(number):
    """Every path issue <number>'s record may live at, most likely first."""
    return [_forkbot_issue_json_path(number, subdir)
            for subdir in ("open", "closed", "")]


def _forkbot_blob_text(blob):
    if not isinstance(blob, dict) or not blob.get("ok"):
        return ""
    content = blob.get("content", "")
    if not isinstance(content, str):
        return ""
    if blob.get("encoding") == "base64":
        try:
            return base64.b64decode(content).decode("utf-8", "replace")
        except Exception:
            return ""
    return content


def _forkbot_parse_issue_record(text, number):
    """Reduce one .forkmesh/issues/<N>/issue-<N>.json blob to the fields a chat
    line needs. Tolerant of junk: a malformed record still yields a usable
    "#N" stub rather than dropping the issue from the list."""
    try:
        parsed = json.loads(text or "{}")
    except Exception:
        parsed = None
    if not isinstance(parsed, dict):
        parsed = {}
    events = parsed.get("events")
    open_event = {}
    if isinstance(events, list):
        for event in events:
            if isinstance(event, dict) and event.get("type") == "open":
                open_event = event
                break
    title = clean_string(
        parsed.get("title") or open_event.get("title") or "", 240).strip()
    return {
        "number": int(parsed.get("number") or number or 0),
        "title": title or ("issue #%d" % int(number or 0)),
        "status": clean_string(
            parsed.get("status") or parsed.get("state") or "open", 40),
        "author": clean_string(
            parsed.get("authorName") or open_event.get("authorName") or
            parsed.get("author") or open_event.get("author") or "unknown",
            MAX_NODE_NAME),
        "body": clean_string(
            open_event.get("body") or parsed.get("body") or "", 600).strip(),
    }


async def _forkbot_recent_issue_numbers(env, owner, repo):
    """Issue numbers committed to the live mirror, newest first. Returns None
    when no host could serve the tree (offline), [] when the repo simply has
    no issues folder yet. Issues are split into open/ and closed/ status
    folders (adhoc #14); numbered folders directly under the root are the
    pre-split legacy layout."""
    root = await _forkbot_repo_gateway_json(
        env, owner, repo, "tree?path=" + quote(".forkmesh/issues", safe=""))
    if root is None:
        return None
    entries = root.get("entries")
    if not isinstance(entries, list):
        return [] if _forkbot_missing_tree(root) else None
    numbers = set()
    subdirs = []
    for entry in entries:
        if not isinstance(entry, dict) or entry.get("type") != "tree":
            continue
        name = str(entry.get("name", ""))
        if name.isdigit():
            numbers.add(int(name))
        elif name in ("open", "closed"):
            subdirs.append(name)
    for subdir in subdirs:
        tree = await _forkbot_repo_gateway_json(
            env, owner, repo,
            "tree?path=" + quote(".forkmesh/issues/" + subdir, safe=""))
        sub_entries = tree.get("entries") if isinstance(tree, dict) else None
        if not isinstance(sub_entries, list):
            continue
        for entry in sub_entries:
            if not isinstance(entry, dict) or entry.get("type") != "tree":
                continue
            name = str(entry.get("name", ""))
            if name.isdigit():
                numbers.add(int(name))
    return sorted(numbers, reverse=True)


async def _forkbot_load_issue_records(env, owner, repo, numbers):
    """Batched read of the given issues' JSON records over the live tunnel
    (one /blobs round trip, like the website's issue list). Unreadable issues
    are skipped; returns records in the order requested."""
    numbers = [int(n) for n in numbers][:FORKBOT_LIST_MAX]
    if not numbers:
        return []
    # A record lives at open/<N>/, closed/<N>/, or the pre-split legacy <N>/
    # depending on its status; ask for every candidate in the one batch (3 ×
    # FORKBOT_LIST_MAX stays within MAX_BLOB_BATCH) and keep whichever answered.
    query = "&".join(
        "path=" + quote(path, safe="")
        for n in numbers for path in _forkbot_issue_json_candidates(n))
    data = await _forkbot_repo_gateway_json(env, owner, repo, "blobs?" + query)
    blobs = data.get("blobs") if isinstance(data, dict) else None
    if not isinstance(blobs, dict):
        return []
    records = []
    for number in numbers:
        text = ""
        for path in _forkbot_issue_json_candidates(number):
            text = _forkbot_blob_text(blobs.get(path))
            if text:
                break
        if not text:
            continue
        records.append(_forkbot_parse_issue_record(text, number))
    return records


async def _forkbot_search_issues(env, owner, repo, query):
    """One host-side git grep over the mirror (the /search tunnel op, issue
    #360); ForkBot only reads the issues bucket. Returns the matches, or None
    when no host answered."""
    data = await _forkbot_repo_gateway_json(
        env, owner, repo, "search?q=" + quote(query, safe=""))
    if not isinstance(data, dict) or not data.get("ok"):
        return None
    issues = data.get("issues")
    if not isinstance(issues, list):
        return []
    matches = []
    for hit in issues:
        if not isinstance(hit, dict):
            continue
        try:
            number = int(hit.get("number", 0) or 0)
        except (TypeError, ValueError):
            continue
        if number <= 0:
            continue
        matches.append({
            "number": number,
            "title": clean_string(hit.get("title", ""), 240).strip()
            or ("issue #%d" % number),
            "snippet": clean_string(hit.get("snippet", ""), 200).strip(),
        })
    return matches


def _forkbot_issue_lines(records):
    lines = []
    for record in records:
        line = "#%d %s (%s" % (
            record["number"], record["title"], record["status"])
        if record.get("author") and record["author"] != "unknown":
            line += ", by " + record["author"]
        lines.append(line + ")")
    return "\n".join(lines)


async def _forkbot_next_issue_number(env, repo_bi, owner, repo):
    """Allocate a proposed issue number for a ForkBot-created issue.

    Desktop nodes assign the authoritative number when they merge the inbox
    (nextNumber() = highest issue dir + 1) and keep a proposed number when its
    slot is free, so the goal here is to propose the same number the desktop
    would — and never propose one twice. We seed/re-anchor a persisted per-repo
    counter from the catalog's published issueMaxNumber (the desktop's real max
    at its last publish), then hand out the next value and advance. Best-effort:
    on any storage hiccup we fall back to 0 (the desktop assigns and the reply
    just omits a number) rather than failing the issue creation."""
    seed_next = 1
    try:
        row = await d1_first(
            env, "SELECT data FROM repositories WHERE key_bi=?", repo_bi)
        rec = await decrypt_row(env, row.get("data")) if row else None
        if rec:
            for key in ("issueMaxNumber", "issueCount"):
                value = rec.get(key)
                if value in (None, ""):
                    continue
                try:
                    seed_next = max(seed_next, int(value) + 1)
                    break
                except (TypeError, ValueError):
                    continue
    except Exception:
        pass
    try:
        # Seed on first use / re-anchor upward to the catalog max, never
        # backward (MAX keeps already-handed-out numbers monotonic).
        await d1_run(
            env,
            "INSERT INTO issue_seq (repo_bi, next_number) VALUES (?, ?) "
            "ON CONFLICT(repo_bi) DO UPDATE SET "
            "next_number = MAX(issue_seq.next_number, ?)",
            repo_bi, seed_next, seed_next,
        )
        seq_row = await d1_first(
            env, "SELECT next_number FROM issue_seq WHERE repo_bi=?", repo_bi)
        number = int((seq_row or {}).get("next_number", seed_next) or seed_next)
        await d1_run(
            env, "UPDATE issue_seq SET next_number=? WHERE repo_bi=?",
            number + 1, repo_bi)
        return number
    except Exception:
        return 0


def _forkbot_attributed_body(body, source, actor):
    """Append a footer crediting ForkBot and the human who asked for the issue,
    so a reader of the merged issue can see it came from a chat request rather
    than assuming a person typed it up. The fediverse path builds its own
    "Filed from a fediverse mention by ..." attribution before calling in, so
    only the default chat source gets the footer here (avoids double-crediting).
    """
    if source != "forkbot":
        return body
    if actor and actor != FORKBOT_AUTHOR:
        footer = "Filed by ForkBot at @%s's request via chat." % actor
    else:
        footer = "Filed by ForkBot via chat."
    body = (body or "").rstrip()
    if not body:
        return "_%s_" % footer
    return "%s\n\n---\n_%s_" % (body, footer)


async def _forkbot_enqueue_issue(env, owner, repo, title, body, requester,
                                 source="forkbot", labels=None,
                                 attachments=None,
                                 federated_mention_id="",
                                 federated_remote_url=""):
    """Queue a relay-authored issue for the owner's desktop node. ForkBot chat
    requests use the defaults. A manually reviewed fediverse item can reuse
    this path with its random review id so the owner node can later confirm
    the exact issue it materialized; inbound posts never call this directly."""
    await ensure_schema(env)
    repo_bi = await blind_index(env, owner + "/" + repo)
    count = await d1_first(
        env, "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=?", repo_bi)
    if count and int(count.get("c", 0) or 0) >= MAX_PENDING_ISSUES:
        return False, "inbox_full"
    submitter_bi = await blind_index(env, FORKBOT_AUTHOR)
    if await _inbox_author_over_quota(env, "issue_inbox", repo_bi, submitter_bi):
        return False, "author_quota"

    now = int(Date.now())
    actor = clean_string(requester, MAX_NODE_NAME).lower() or FORKBOT_AUTHOR
    body = _forkbot_attributed_body(body, source, actor)
    # Proposed number the desktop honors when the slot is free (0 = let the
    # desktop assign). Allocated before the insert so it lands in the stored
    # item and can be echoed straight back to the chat.
    number = await _forkbot_next_issue_number(env, repo_bi, owner, repo)
    tracked_mention_id = clean_string(federated_mention_id, 32).lower()
    if not re.fullmatch(r"[a-f0-9]{32}", tracked_mention_id):
        tracked_mention_id = ""
    event = {
        "type": "open",
        "id": (
            "fediverse-review-" + tracked_mention_id
            if tracked_mention_id else "forkbot-%d" % now
        ),
        "author": FORKBOT_AUTHOR,
        "authorName": FORKBOT_NAME,
        "ts": now,
        "title": clean_string(title, 240),
        "body": clean_string(body, MAX_ISSUE_BYTES),
        "attachments": [entry["name"] for entry in (attachments or [])],
        "sig": "",
    }
    item = {
        "number": number,
        "titleIfNew": event["title"],
        "event": event,
        "meta": {
            "labels": list(labels) if labels else ["forkbot"],
            "milestone": "",
            "priority": 0,
            "assignees": [],
            "wantsAgent": False,
            "model": "",
            "provider": "",
        },
        "submitter": FORKBOT_AUTHOR,
        "submittedAt": now,
        "source": source,
        "requestedBy": actor,
        "issueNumber": number,
    }
    if tracked_mention_id:
        item["fediverseMentionId"] = tracked_mention_id
        item["fediverseRemoteUrl"] = clean_string(
            federated_remote_url, 1600)
    if attachments:
        item["attachmentData"] = [
            {"name": entry["name"], "data": entry["data"]}
            for entry in attachments]
    await d1_run(
        env,
        "INSERT INTO issue_inbox (repo_bi, data, submitter_bi) VALUES (?,?,?)",
        repo_bi, await encrypt_row(env, item), submitter_bi,
    )
    await _record_contributor(env, FORKBOT_AUTHOR, "issues")
    await _best_effort_inbox_side_effect(
        notify_pending_inbox(
            env, owner, repo, "issue", FORKBOT_AUTHOR, item.get("titleIfNew", ""),
            number))
    await _best_effort_inbox_side_effect(
        notify_mentions(
            env, owner, repo, FORKBOT_AUTHOR, item.get("titleIfNew", ""),
            event.get("body", ""), repo_web_href(owner, repo), "issue",
            number=number))
    return True, item


async def _forkbot_enqueue_agent_request(env, owner, repo, number, requester):
    """Queue a "start a coding agent on issue #number" request through the
    same signed-inbox channel as everything else: a ForkBot comment event on
    the existing issue whose meta carries wantsAgent. The owner's desktop node
    starts the agent when it merges the inbox — the relay never runs anything
    itself. Caller has already verified the requester is the repo owner/admin
    (the same privilege gate issues_handler applies to wantsAgent)."""
    await ensure_schema(env)
    repo_bi = await blind_index(env, owner + "/" + repo)
    count = await d1_first(
        env, "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=?", repo_bi)
    if count and int(count.get("c", 0) or 0) >= MAX_PENDING_ISSUES:
        return False, "inbox_full"
    submitter_bi = await blind_index(env, FORKBOT_AUTHOR)
    if await _inbox_author_over_quota(env, "issue_inbox", repo_bi, submitter_bi):
        return False, "author_quota"

    now = int(Date.now())
    actor = clean_string(requester, MAX_NODE_NAME).lower() or FORKBOT_AUTHOR
    event = {
        "type": "comment",
        "id": "forkbot-agent-%d" % now,
        "author": FORKBOT_AUTHOR,
        "authorName": FORKBOT_NAME,
        "ts": now,
        "body": "@%s asked ForkBot to start a coding agent on this issue."
                % actor,
        "attachments": [],
        "sig": "",
    }
    item = {
        "number": int(number),
        "titleIfNew": "",
        "event": event,
        "meta": {
            "labels": [],
            "milestone": "",
            "priority": 0,
            "assignees": [],
            "wantsAgent": True,
            "model": "",
            "provider": "",
        },
        "submitter": FORKBOT_AUTHOR,
        "submittedAt": now,
        "source": "forkbot",
        "requestedBy": actor,
    }
    await d1_run(
        env,
        "INSERT INTO issue_inbox (repo_bi, data, submitter_bi) VALUES (?,?,?)",
        repo_bi, await encrypt_row(env, item), submitter_bi,
    )
    await _best_effort_inbox_side_effect(
        notify_pending_inbox(
            env, owner, repo, "issue", FORKBOT_AUTHOR,
            "agent request for issue #%d" % int(number), int(number)))
    return True, item


def _forkbot_gateway_offline_reply(owner, repo):
    return json_response({
        "ok": True,
        "action": "issues_unavailable",
        "botMessage": (
            "I couldn't reach a live host for %s/%s — issues are served from "
            "the owner's desktop node. Try again once it's back online."
        ) % (owner, repo),
    })


async def _forkbot_action_count(env, owner, repo):
    # A "how many" question wants a total, not a capped listing — reusing
    # _forkbot_action_list here would silently truncate at FORKBOT_LIST_MAX
    # and never actually answer the question asked.
    numbers = await _forkbot_recent_issue_numbers(env, owner, repo)
    if numbers is None:
        return _forkbot_gateway_offline_reply(owner, repo)
    total = len(numbers)
    if not total:
        message = "No issues have been filed in %s/%s yet." % (owner, repo)
    else:
        message = "There %s %d issue%s in %s/%s." % (
            "is" if total == 1 else "are", total,
            "" if total == 1 else "s", owner, repo)
    return json_response({
        "ok": True, "action": "issues_counted", "count": total,
        "botMessage": message,
    })


async def _forkbot_action_list(env, owner, repo, count):
    numbers = await _forkbot_recent_issue_numbers(env, owner, repo)
    if numbers is None:
        return _forkbot_gateway_offline_reply(owner, repo)
    issue_url = repo_web_href(owner, repo) + "/issues"
    if not numbers:
        return json_response({
            "ok": True, "action": "issues_listed", "issues": [],
            "botMessage": "No issues have been filed in %s/%s yet."
                          % (owner, repo),
        })
    records = await _forkbot_load_issue_records(env, owner, repo,
                                                numbers[:count])
    if not records:
        return _forkbot_gateway_offline_reply(owner, repo)
    lines = _forkbot_issue_lines(records)
    header = "Last %d issue%s in %s/%s:" % (
        len(records), "" if len(records) == 1 else "s", owner, repo)
    footer = "Full list: " + issue_url
    if len(numbers) > len(records):
        footer = ("Say \"list the last N issues\" for more (up to %d). "
                  % FORKBOT_LIST_MAX) + footer
    return json_response({
        "ok": True,
        "action": "issues_listed",
        "owner": owner,
        "repo": repo,
        "issues": records,
        "botMessage": header + "\n" + lines + "\n" + footer,
    })


async def _forkbot_action_search(env, owner, repo, query):
    matches = await _forkbot_search_issues(env, owner, repo, query)
    if matches is None:
        return _forkbot_gateway_offline_reply(owner, repo)
    if not matches:
        return json_response({
            "ok": True, "action": "issues_searched", "query": query,
            "issues": [],
            "botMessage": "No issues matching \"%s\" in %s/%s."
                          % (query, owner, repo),
        })
    top = matches[:FORKBOT_SEARCH_MAX]
    lines = []
    for hit in top:
        line = "#%d %s" % (hit["number"], hit["title"])
        if hit.get("snippet"):
            line += " — " + hit["snippet"]
        lines.append(line)
    header = "Issues matching \"%s\" in %s/%s:" % (query, owner, repo)
    if len(matches) > len(top):
        header = "Top %d of %d issues matching \"%s\" in %s/%s:" % (
            len(top), len(matches), query, owner, repo)
    return json_response({
        "ok": True,
        "action": "issues_searched",
        "owner": owner,
        "repo": repo,
        "query": query,
        "issues": top,
        "botMessage": header + "\n" + "\n".join(lines),
    })


async def _forkbot_action_show(env, owner, repo, number):
    if number <= 0:
        numbers = await _forkbot_recent_issue_numbers(env, owner, repo)
        if numbers is None:
            return _forkbot_gateway_offline_reply(owner, repo)
        if not numbers:
            return json_response({
                "ok": True, "action": "issue_shown", "issue": None,
                "botMessage": "No issues have been filed in %s/%s yet."
                              % (owner, repo),
            })
        number = numbers[0]
    records = await _forkbot_load_issue_records(env, owner, repo, [number])
    if not records:
        return json_response({
            "ok": True, "action": "issue_shown", "issue": None,
            "botMessage": (
                "I couldn't read issue #%d from a live %s/%s host — it may "
                "not exist, or the owner's node is offline."
            ) % (number, owner, repo),
        })
    record = records[0]
    bot_message = "#%d %s (%s, opened by %s)." % (
        record["number"], record["title"], record["status"], record["author"])
    if record.get("body"):
        bot_message += " " + record["body"]
    return json_response({
        "ok": True,
        "action": "issue_shown",
        "owner": owner,
        "repo": repo,
        "issue": record,
        "botMessage": bot_message,
    })


async def _forkbot_action_start_agent(env, owner, repo, number, sender):
    # Starting a coding agent on the owner's machine is an immediate,
    # unreviewed side effect, so it keeps the same privilege gate the web
    # issue form's wantsAgent has (adhoc #225): the repo owner's account or a
    # network admin. Chat sender names are client-claimed, matching the trust
    # model of the web form's ownerAccount field.
    requester = clean_string(sender, MAX_NODE_NAME).strip().lower()
    authorized = bool(requester) and (
        requester == owner.lower() or await _is_admin(env, requester))
    if not authorized:
        return json_response({
            "ok": True,
            "action": "agent_denied",
            "botMessage": (
                "Starting a coding agent is limited to the repo owner (or a "
                "network admin) — ask %s to kick it off."
            ) % owner,
        })
    numbers = await _forkbot_recent_issue_numbers(env, owner, repo)
    if numbers is None:
        return _forkbot_gateway_offline_reply(owner, repo)
    if not numbers:
        return json_response({
            "ok": True, "action": "agent_denied",
            "botMessage": "There are no issues in %s/%s to start an agent on."
                          % (owner, repo),
        })
    if number <= 0:
        number = numbers[0]
    elif number not in numbers:
        return json_response({
            "ok": True, "action": "agent_denied",
            "botMessage": "Issue #%d isn't in the %s/%s mirror."
                          % (number, owner, repo),
        })
    records = await _forkbot_load_issue_records(env, owner, repo, [number])
    title = records[0]["title"] if records else ""
    ok, result = await _forkbot_enqueue_agent_request(
        env, owner, repo, number, requester)
    if not ok:
        return json_response({"error": result}, status=429)
    bot_message = (
        "Queued a coding agent for issue #%d%s in %s/%s. The owner's node "
        "will start it when it next syncs the inbox."
    ) % (number, (": " + title) if title else "", owner, repo)
    return json_response({
        "ok": True,
        "action": "agent_requested",
        "owner": owner,
        "repo": repo,
        "issueNumber": number,
        "title": title,
        "botMessage": bot_message,
    }, status=201)


async def forkbot_chat_handler(env, request):
    if method_name(request) != "POST":
        return json_response({"error": "method_not_allowed"}, status=405)
    try:
        data = await request.json()
    except Exception:
        return json_response({"error": "invalid_json"}, status=400)
    if not isinstance(data, dict):
        return json_response({"error": "invalid_json"}, status=400)

    message = clean_string(data.get("message", ""), FORKBOT_MAX_COMMAND)
    command = _forkbot_extract_mention_command(message)
    if not command:
        return json_response({"ok": True, "ignored": True})

    # Recent (client-decrypted) conversation the mention sits in, so ForkBot can
    # resolve "that bug" / "the issue we discussed" instead of only the one line.
    context_text = _forkbot_context_text(data.get("context"))
    sender = clean_string(data.get("sender", ""), MAX_NODE_NAME)
    owner = FORKBOT_DEFAULT_OWNER
    repo = FORKBOT_DEFAULT_REPO

    # Decide the action. Prefer meaning over fixed wording:
    #  1. Cheap regexes catch explicitly phrased commands offline (list /
    #     search / start-agent / show / help / create), sparing an AI round
    #     trip and keeping every command working when AI is off.
    #  2. Otherwise the AI classifier reads the command + conversation and
    #     picks the intent (drafting the issue when one is wanted).
    #  3. AI unreachable (None — distinct from a confident "none") but the
    #     message plainly talks about issues/bugs/tracking: file the raw text
    #     rather than refusing. Only a confident "none" or a message with no
    #     work-recording signal at all gets the help hint.
    action = None
    for intent_name, parser in (
            ("count_issues", _forkbot_parse_count_command),
            ("list_issues", _forkbot_parse_list_command),
            ("search_issues", _forkbot_parse_search_command),
            ("start_agent", _forkbot_parse_agent_command),
            ("show_issue", _forkbot_parse_show_command)):
        parsed_intent = parser(command)
        if parsed_intent is not None:
            action = {"intent": intent_name, **parsed_intent}
            break
    if action is None and _forkbot_parse_help_command(command):
        action = {"intent": "help"}

    fields = None
    if action is None:
        parsed = _forkbot_parse_issue_command(command)
        if parsed:
            action = {"intent": "create_issue"}
            fields = await _forkbot_ai_issue_fields(
                env, parsed["description"], context_text)
            if not fields:
                fields = _forkbot_fallback_issue_fields(parsed["description"])
        else:
            interpreted = await _forkbot_ai_interpret(env, command, context_text)
            if interpreted and interpreted.get("intent") == "create_issue":
                action = {"intent": "create_issue"}
                fields = {"title": interpreted["title"],
                          "body": interpreted["body"]}
            elif interpreted and interpreted.get("intent") != "none":
                action = interpreted
            elif interpreted is None and _forkbot_command_hints_issue(command):
                action = {"intent": "create_issue"}
                fields = _forkbot_fallback_issue_fields(command)

    intent = (action or {}).get("intent", "")
    if intent == "count_issues":
        return await _forkbot_action_count(env, owner, repo)
    if intent == "list_issues":
        return await _forkbot_action_list(env, owner, repo, action["count"])
    if intent == "search_issues":
        return await _forkbot_action_search(env, owner, repo, action["query"])
    if intent == "show_issue":
        return await _forkbot_action_show(
            env, owner, repo, int(action.get("issueNumber", 0) or 0))
    if intent == "start_agent":
        return await _forkbot_action_start_agent(
            env, owner, repo, int(action.get("issueNumber", 0) or 0), sender)

    if intent != "create_issue" or not fields or not fields.get("body"):
        return json_response({
            "ok": True,
            "action": "help",
            "botMessage": _forkbot_help_message(),
        })

    ok, result = await _forkbot_enqueue_issue(
        env, owner, repo, fields["title"], fields["body"], sender)
    if not ok:
        return json_response({"error": result}, status=429)
    title = result.get("titleIfNew", fields["title"])
    number = int(result.get("issueNumber", 0) or 0)
    # /owner/repo/issues is the web route for the repo's issue list; the number
    # is the proposed one the desktop honors when it merges the inbox.
    issue_url = repo_web_href(owner, repo) + "/issues"
    if number > 0:
        bot_message = (
            "Opened issue #%d in %s/%s: %s. It'll show at %s once the owner "
            "node syncs the inbox."
        ) % (number, owner, repo, title, issue_url)
    else:
        bot_message = (
            "Opened an issue in %s/%s: %s. It'll show at %s once the owner "
            "node syncs the inbox."
        ) % (owner, repo, title, issue_url)
    return json_response({
        "ok": True,
        "action": "issue_created",
        "owner": owner,
        "repo": repo,
        "title": title,
        "issueNumber": number,
        "issueUrl": issue_url,
        "botMessage": bot_message,
    }, status=201)


def _clean_issue_attachment_data(value):
    """Validate the base64 image bytes a no-write-access node ships alongside a
    signed issue/comment "open"/"comment" event (see MAX_ISSUE_ATTACHMENT_BYTES).
    Returns (cleaned_list, error); cleaned_list entries are {"name","data"} with
    data re-encoded from the decoded bytes so nothing but valid base64 survives."""
    if not isinstance(value, list):
        return [], None
    if len(value) > MAX_ISSUE_ATTACHMENTS:
        return [], "too_many_attachments"
    cleaned = []
    for entry in value:
        if not isinstance(entry, dict):
            return [], "bad_attachment"
        name = entry.get("name", "")
        if not isinstance(name, str) or not ISSUE_ATTACHMENT_NAME_RE.match(name):
            return [], "bad_attachment"
        data = entry.get("data", "")
        if not isinstance(data, str) or len(data) > 4 * (
                (MAX_ISSUE_ATTACHMENT_BYTES + 2) // 3):
            return [], "attachment_too_large"
        try:
            raw = base64.b64decode(data, validate=True)
        except Exception:
            return [], "bad_attachment"
        if len(raw) > MAX_ISSUE_ATTACHMENT_BYTES:
            return [], "attachment_too_large"
        cleaned.append({"name": name, "data": base64.b64encode(raw).decode()})
    return cleaned, None


async def _log_inbox_drain(env, repo_bi, kind, count):
    # Audit trail for inbox acks (adhoc #97): one row per non-empty drain so a
    # "web-filed item vanished but never synced" report is traceable. Content-free
    # (blind-indexed repo, a count) and best-effort — never fail the ack over it.
    if count <= 0:
        return
    try:
        await d1_run(
            env,
            "INSERT INTO inbox_drain_log (ts, repo_bi, kind, count) VALUES (?,?,?,?)",
            int(Date.now()), repo_bi, kind, int(count))
    except Exception:
        pass


def _drain_ids_from_request(request):
    # ?ids=1,2,3 on an inbox-drain DELETE: the node acks exactly the rows it
    # merged, so a submission inserted after the node's read survives to the
    # next sync instead of being swept away undelivered (adhoc #97).
    params = parse_qs(urlparse(request.url).query)
    raw = params.get("ids", [""])[0]
    ids = []
    for part in raw.split(","):
        part = part.strip()
        if not part:
            continue
        try:
            ids.append(int(part))
        except (TypeError, ValueError):
            continue
    return ids


async def _drain_issue_inbox(env, request, repo_bi):
    """Ack (delete) the exact issue-inbox rows named by ?ids=, returning how many
    were removed, and record the drain in inbox_drain_log. Rows the node did not
    ack (including a submission that arrived after it read the queue) are left
    for the next sync; a request with no ids removes nothing (adhoc #97)."""
    ids = _drain_ids_from_request(request)
    if not ids:
        return 0
    marks = ",".join("?" for _ in ids)
    row = await d1_first(
        env,
        "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=? "
        "AND id IN (%s)" % marks,
        repo_bi, *ids)
    removed = int(row.get("c", 0)) if row else 0
    await d1_run(
        env,
        "DELETE FROM issue_inbox WHERE repo_bi=? AND id IN (%s)" % marks,
        repo_bi, *ids)
    await _log_inbox_drain(env, repo_bi, "issues", removed)
    return removed


async def _confirm_fediverse_issue_materializations(env, request):
    """Apply bounded owner-node confirmations carried by a signed inbox ack."""
    values = parse_qs(urlparse(request.url).query).get("materialized", [""])
    raw = values[0] if values else ""
    runtime = _WorldCommunityRuntime(env, request)
    confirmed = 0
    for value in str(raw or "").split(",")[:MAX_PENDING_PER_AUTHOR]:
        mention_id, separator, number_text = value.partition(":")
        if (
            not separator
            or not re.fullmatch(r"[a-f0-9]{32}", mention_id)
        ):
            continue
        try:
            number = int(number_text)
        except (TypeError, ValueError):
            continue
        if number <= 0:
            continue
        if await fediverse_mentions_api.confirm_materialized(
            runtime, mention_id, number
        ):
            confirmed += 1
    return confirmed


async def issues_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    repo_bi = await blind_index(env, owner + "/" + repo)
    if method == "POST":
        try:
            data = await request.json()
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        event = data.get("event")
        if not isinstance(event, dict):
            return json_response({"error": "event_required"}, status=400)
        try:
            number = int(data.get("number", 0))
        except (TypeError, ValueError):
            number = 0
        if len((event.get("body", "") or "").encode("utf-8")) > MAX_ISSUE_BYTES:
            return json_response({"error": "issue_too_large"}, status=413)
        if not await verify_issue_event(number, event):
            return json_response({"error": "bad_signature"}, status=401)
        # Screenshots the submitter had no working tree to copy in ride along as
        # base64 bytes, named to match the signed event's attachments list.
        attachment_data, attach_err = _clean_issue_attachment_data(
            data.get("attachmentData"))
        if attach_err:
            status = 413 if attach_err in (
                "too_many_attachments", "attachment_too_large") else 400
            return json_response({"error": attach_err}, status=status)
        count = await d1_first(
            env, "SELECT COUNT(*) AS c FROM issue_inbox WHERE repo_bi=?", repo_bi
        )
        if count and count.get("c", 0) >= MAX_PENDING_ISSUES:
            return json_response({"error": "inbox_full"}, status=429)
        submitter_bi = await blind_index(env, event.get("author", ""))
        if await _inbox_author_over_quota(env, "issue_inbox", repo_bi, submitter_bi):
            return json_response({"error": "author_quota"}, status=429)
        # Issue-level metadata for a new issue (labels/milestone/priority/
        # assignees). Not signature-bound; the owner applies it on merge. Bounded
        # to keep a submission small and the lists sane.
        meta_in = data.get("meta")
        meta = {}
        if isinstance(meta_in, dict):
            labels = meta_in.get("labels")
            assignees = meta_in.get("assignees")
            try:
                priority = int(meta_in.get("priority", 0))
            except (TypeError, ValueError):
                priority = 0
            # "wantsAgent" makes the owner's node start a coding agent on this
            # issue automatically once merged — unlike the other meta fields
            # above, that's an immediate, unreviewed side effect, so it's only
            # honored when the request comes from a privileged account: the repo
            # owner, or an admin acting on the owner's behalf (adhoc #225).
            wants_agent = False
            agent_model = ""
            agent_provider = ""
            if meta_in.get("wantsAgent"):
                ok, err = await _authorize_owner_account(env, owner, data, request)
                if not ok:
                    return err
                wants_agent = True
                # Optional model choice (e.g. "opus"/"sonnet"/"haiku"/"fable" or a
                # full model id) for the agent the desktop node auto-starts on this
                # issue; empty leaves the provider's own default. Only meaningful
                # alongside wantsAgent, so it's not parsed otherwise.
                agent_model = clean_string(meta_in.get("model", ""), 60)
                # Optional agent-provider choice from the web dropdown (adhoc #234);
                # only a known provider is honored, else the node picks its default.
                provider_in = clean_string(meta_in.get("provider", ""), 40)
                if provider_in in ("claude-code", "claude-api", "openai"):
                    agent_provider = provider_in
            meta = {
                "labels": [clean_string(x, 60) for x in (labels or [])][:20]
                if isinstance(labels, list) else [],
                "milestone": clean_string(meta_in.get("milestone", ""), 120),
                "project": clean_string(meta_in.get("project", ""), 120),
                "priority": priority if 0 <= priority <= 99 else 0,
                "assignees": [clean_string(x, 60) for x in (assignees or [])][:20]
                if isinstance(assignees, list) else [],
                "wantsAgent": wants_agent,
                "model": agent_model,
                "provider": agent_provider,
            }
        item = {
            "number": number,
            "titleIfNew": clean_string(data.get("titleIfNew", ""), 240),
            "event": event,
            "meta": meta,
            "attachmentData": attachment_data,
            "submitter": clean_string(event.get("author", ""), 120),
            "submittedAt": int(Date.now()),
        }
        await d1_run(
            env,
            "INSERT INTO issue_inbox (repo_bi, data, submitter_bi) VALUES (?,?,?)",
            repo_bi, await encrypt_row(env, item), submitter_bi,
        )
        await _record_contributor(env, event.get("author", ""), "issues")
        actor = clean_string(event.get("authorName", "") or event.get("author", ""), MAX_NODE_NAME).lower()
        await _best_effort_inbox_side_effect(
            notify_pending_inbox(
                env, owner, repo, "issue", actor, item.get("titleIfNew", ""),
                number))
        await _best_effort_inbox_side_effect(
            notify_mentions(
                env, owner, repo, actor, item.get("titleIfNew", ""),
                event.get("body", ""), repo_web_href(owner, repo), "issue",
                number=number))
        assignees = list(meta.get("assignees", [])) if isinstance(meta, dict) else []
        if isinstance(event.get("assignees"), list):
            assignees.extend(event.get("assignees"))
        await _best_effort_inbox_side_effect(
            notify_issue_assignees(
                env, owner, repo, assignees, actor, item.get("titleIfNew", ""),
                number))
        # Subscriptions (issue #361): tell everyone already following this issue
        # about the new activity, then auto-subscribe the commenter so they hear
        # about later replies. Both no-op for a brand-new issue (number 0).
        await _best_effort_inbox_side_effect(
            notify_subscribers(
                env, owner, repo, "issue", number, actor,
                item.get("titleIfNew", ""), event.get("body", ""),
                repo_web_href(owner, repo)))
        await _best_effort_inbox_side_effect(
            subscribe_thread(env, owner, repo, "issue", number, actor))
        await notify_repo_host(env, owner, repo, "issues")
        # Fediverse: announce content events (opens/comments — never labels or
        # status flips) to any followers of the repo/author actors.
        if event.get("type") in ("open", "comment"):
            await _best_effort_inbox_side_effect(_ap_publish_repo_event(
                env, request, owner, repo, "issue", event.get("type"),
                number, item.get("titleIfNew", ""), event.get("body", ""),
                event.get("authorName", "")))
        return json_response({"ok": True}, status=201)

    if method == "GET":
        if not await _authorize_owner(env, request, owner):
            return json_response({"error": "unauthorized"}, status=401)
        rows = await d1_all(
            env, "SELECT id, data FROM issue_inbox WHERE repo_bi=? ORDER BY id ASC",
            repo_bi,
        )
        pending = []
        for r in rows:
            rec = await decrypt_row(env, r["data"])
            if rec:
                # The row id lets the node ack exactly what it merged so a
                # submission that lands mid-drain isn't swept away undelivered
                # (adhoc #97) — the "stayed pending, then vanished, never synced"
                # bug. A DELETE must name the ids to remove; without them the
                # drain removes nothing.
                rec["id"] = r.get("id")
                pending.append(rec)
        return json_response({"ok": True, "pending": pending})

    if method == "DELETE":
        if not await _authorize_owner(env, request, owner):
            return json_response({"error": "unauthorized"}, status=401)
        materialized = await _confirm_fediverse_issue_materializations(
            env, request)
        removed = await _drain_issue_inbox(env, request, repo_bi)
        return json_response({
            "ok": True,
            "drained": removed,
            "materialized": materialized,
        })

    return json_response({"error": "method_not_allowed"}, status=405)


async def pulls_handler(env, request, owner, repo):
    await ensure_schema(env)
    method = method_name(request)
    repo_bi = await blind_index(env, owner + "/" + repo)
    if method == "POST":
        try:
            data = await request.json()
        except Exception:
            return json_response({"error": "invalid_json"}, status=400)
        # A submission is either a whole new PR ("pull") or a signed conversation
        # event ("event" + "number") — a comment or review on an existing PR.
        event = data.get("event")
        if isinstance(event, dict):
            try:
                number = int(data.get("number", 0))
            except (TypeError, ValueError):
                number = 0
            if len((event.get("body", "") or "").encode("utf-8")) > MAX_ISSUE_BYTES:
                return json_response({"error": "event_too_large"}, status=413)
            if not await verify_pull_comment_event(number, event):
                return json_response({"error": "bad_signature"}, status=401)
            count = await d1_first(
                env, "SELECT COUNT(*) AS c FROM pull_inbox WHERE repo_bi=?", repo_bi
            )
            if count and count.get("c", 0) >= MAX_PENDING_PULLS:
                return json_response({"error": "inbox_full"}, status=429)
            submitter_bi = await blind_index(env, event.get("author", ""))
            if await _inbox_author_over_quota(
                    env, "pull_inbox", repo_bi, submitter_bi):
                return json_response({"error": "author_quota"}, status=429)
            item = {
                "number": number,
                "event": event,
                "submitter": clean_string(event.get("author", ""), 120),
                "submittedAt": int(Date.now()),
            }
            await d1_run(
                env,
                "INSERT INTO pull_inbox (repo_bi, data, submitter_bi) "
                "VALUES (?,?,?)",
                repo_bi, await encrypt_row(env, item), submitter_bi,
            )
            await _record_contributor(env, event.get("author", ""), "pulls")
            actor = clean_string(event.get("authorName", "") or event.get("author", ""), MAX_NODE_NAME).lower()
            await notify_pending_inbox(env, owner, repo, "pull", actor, event.get("body", ""), number)
            await notify_mentions(env, owner, repo, actor, "Pull request comment", event.get("body", ""),
                                  repo_web_href(owner, repo), "pull", number=number)
            # Subscriptions (issue #361): fan the comment out to the PR's
            # followers, then auto-subscribe the commenter.
            await notify_subscribers(env, owner, repo, "pull", number, actor,
                                     "Pull request comment", event.get("body", ""),
                                     repo_web_href(owner, repo))
            await subscribe_thread(env, owner, repo, "pull", number, actor)
            await notify_repo_host(env, owner, repo, "pulls")
            if event.get("type") in ("comment", "review"):
                await _best_effort_inbox_side_effect(_ap_publish_repo_event(
                    env, request, owner, repo, "pull", event.get("type"),
                    number, "", event.get("body", ""),
                    event.get("authorName", "")))
            return json_response({"ok": True}, status=201)
        pull = data.get("pull")
        if not isinstance(pull, dict):
            return json_response({"error": "pull_required"}, status=400)
        signed_fields = ("title", "base", "head", "patch", "commits")
        if any(
                field in pull and not isinstance(pull.get(field), str)
                for field in signed_fields):
            return json_response({"error": "pull_invalid"}, status=400)
        description = (
            pull.get("description")
            if "description" in pull else pull.get("body", ""))
        if not isinstance(description, str):
            return json_response({"error": "pull_invalid"}, status=400)
        if len(description.encode("utf-8")) > MAX_ISSUE_BYTES:
            return json_response(
                {"error": "description_too_large"}, status=413)
        # `description` is the native Qt wire name. Normalize legacy browser
        # `body` submissions before encrypting the inbox item so either kind of
        # sender drains into the same lossless PullRequest representation.
        pull["description"] = description
        pull.pop("body", None)
        pull_bytes = len((pull.get("patch", "") or "").encode("utf-8")) + len(
            (pull.get("commits", "") or "").encode("utf-8"))
        if pull_bytes > MAX_PULL_BYTES:
            return json_response({"error": "pull_too_large"}, status=413)
        if not await verify_pull_event(pull):
            return json_response({"error": "bad_signature"}, status=401)
        count = await d1_first(
            env, "SELECT COUNT(*) AS c FROM pull_inbox WHERE repo_bi=?", repo_bi
        )
        if count and count.get("c", 0) >= MAX_PENDING_PULLS:
            return json_response({"error": "inbox_full"}, status=429)
        submitter_bi = await blind_index(env, pull.get("author", ""))
        if await _inbox_author_over_quota(env, "pull_inbox", repo_bi, submitter_bi):
            return json_response({"error": "author_quota"}, status=429)
        item = {
            "pull": pull,
            "submitter": clean_string(pull.get("author", ""), 120),
            "submittedAt": int(Date.now()),
        }
        await d1_run(
            env,
            "INSERT INTO pull_inbox (repo_bi, data, submitter_bi) VALUES (?,?,?)",
            repo_bi, await encrypt_row(env, item), submitter_bi,
        )
        await _record_contributor(env, pull.get("author", ""), "pulls")
        actor = clean_string(pull.get("authorName", "") or pull.get("author", ""), MAX_NODE_NAME).lower()
        title = clean_string(pull.get("title", "") or pull.get("subject", ""), 240)
        await notify_pending_inbox(env, owner, repo, "pull", actor, title, 0)
        await notify_mentions(env, owner, repo, actor, title, description,
                              repo_web_href(owner, repo), "pull")
        await notify_repo_host(env, owner, repo, "pulls")
        # Badge (adhoc #44): render the PR's visual fingerprint from the
        # signed patch and attach it to the federated note as its lead image.
        # Best-effort — a badge failure must never block the submission.
        badge = None
        try:
            stats = patch_file_stats(pull.get("patch", "") or "")
            if stats:
                png = pull_badge_png(
                    title, clean_string(
                        pull.get("authorName", "") or pull.get("author", ""),
                        MAX_NODE_NAME), stats)
                badge = {"mediaType": "image/png",
                         "data": base64.b64encode(png).decode("ascii")}
        except Exception:
            badge = None
        await _best_effort_inbox_side_effect(_ap_publish_repo_event(
            env, request, owner, repo, "pull", "open", 0, title,
            description, pull.get("authorName", ""),
            extra_images=[badge] if badge else None))
        return json_response({"ok": True}, status=201)

    if method == "GET":
        if not await _authorize_repo_inbox_owner(
                env, request, owner, repo):
            return json_response({"error": "unauthorized"}, status=401)
        rows = await d1_all(
            env, "SELECT data FROM pull_inbox WHERE repo_bi=? ORDER BY id ASC",
            repo_bi,
        )
        pending = [rec for rec in
                   [await decrypt_row(env, r["data"]) for r in rows] if rec]
        return json_response({"ok": True, "pending": pending})

    if method == "DELETE":
        if not await _authorize_repo_inbox_owner(
                env, request, owner, repo):
            return json_response({"error": "unauthorized"}, status=401)
        await d1_run(env, "DELETE FROM pull_inbox WHERE repo_bi=?", repo_bi)
        return json_response({"ok": True})

    return json_response({"error": "method_not_allowed"}, status=405)


